use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

type FetchFut = Pin<Box<dyn Future<Output = (u32, Result<u64, ()>)> + Send + 'static>>;

struct TimerState {
    waker: Option<Waker>,
    stop: bool,
}

struct DeadlineFuture {
    at: Option<Instant>,
    state: Arc<(Mutex<TimerState>, Condvar)>,
    started: bool,
}

impl DeadlineFuture {
    fn new(duration: Duration) -> Self {
        DeadlineFuture {
            at: Instant::now().checked_add(duration),
            state: Arc::new((Mutex::new(TimerState { waker: None, stop: false }), Condvar::new())),
            started: false,
        }
    }
}

impl Future for DeadlineFuture {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let at = match self.at {
            Some(at) => at,
            None => return Poll::Pending,
        };
        if Instant::now() >= at {
            return Poll::Ready(());
        }
        {
            let mut state = self.state.0.lock().unwrap();
            state.waker = Some(cx.waker().clone());
        }
        if !self.started {
            self.started = true;
            let state = Arc::clone(&self.state);
            thread::spawn(move || {
                let (lock, cvar) = &*state;
                let mut guard = lock.lock().unwrap();
                loop {
                    if guard.stop {
                        return;
                    }
                    let now = Instant::now();
                    if now >= at {
                        break;
                    }
                    let remaining = at - now;
                    let (next, _) = cvar.wait_timeout(guard, remaining).unwrap();
                    guard = next;
                }
                let waker = guard.waker.take();
                drop(guard);
                if let Some(waker) = waker {
                    waker.wake();
                }
            });
        }
        Poll::Pending
    }
}

impl Drop for DeadlineFuture {
    fn drop(&mut self) {
        let (lock, cvar) = &*self.state;
        if let Ok(mut state) = lock.lock() {
            state.stop = true;
        }
        cvar.notify_all();
    }
}

struct Solve {
    fetcher: Box<Fetcher>,
    ids: Vec<u32>,
    next: usize,
    in_flight: Vec<(u32, FetchFut)>,
    timer: DeadlineFuture,
    sum: u64,
}

impl Solve {
    fn start_one(&mut self) {
        let id = self.ids[self.next];
        self.next += 1;
        let fetcher = self.fetcher.clone();
        let fut: FetchFut = Box::pin(async move {
            let value = fetcher.fetch(id).await.map_err(|_| ());
            (id, value)
        });
        self.in_flight.push((id, fut));
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        loop {
            if Pin::new(&mut this.timer).poll(cx).is_ready() {
                this.in_flight.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            while this.in_flight.len() < MAX_IN_FLIGHT && this.next < this.ids.len() {
                this.start_one();
            }

            if this.in_flight.is_empty() {
                return Poll::Ready(Ok(this.sum));
            }

            let mut progressed = false;
            let mut index = 0;
            while index < this.in_flight.len() {
                match this.in_flight[index].1.as_mut().poll(cx) {
                    Poll::Ready((_, Ok(value))) => {
                        this.sum = this.sum.wrapping_add(value);
                        this.in_flight.swap_remove(index);
                        progressed = true;
                    }
                    Poll::Ready((id, Err(()))) => {
                        this.in_flight.clear();
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => {
                        index += 1;
                    }
                }
            }

            if !progressed {
                return Poll::Pending;
            }
        }
    }
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    Solve {
        fetcher: Box::new(fetch),
        ids,
        next: 0,
        in_flight: Vec::new(),
        timer: DeadlineFuture::new(deadline),
        sum: 0,
    }
    .await
}

