use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::Duration;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchFut =
    Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>>>>;

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    struct Timer {
        state: Arc<(Mutex<(bool, bool, Option<Waker>)>, Condvar)>,
        handle: Option<JoinHandle<()>>,
    }

    impl Timer {
        fn start(after: Duration) -> Self {
            let state: Arc<(Mutex<(bool, bool, Option<Waker>)>, Condvar)> =
                Arc::new((Mutex::new((false, false, None)), Condvar::new()));
            let shared = Arc::clone(&state);
            let handle = thread::spawn(move || {
                let (lock, cvar) = &*shared;
                let guard = lock.lock().unwrap();
                let (mut s, _) = cvar.wait_timeout_while(guard, after, |s| !s.1).unwrap();
                if !s.1 {
                    s.0 = true;
                    if let Some(waker) = s.2.take() {
                        waker.wake();
                    }
                }
            });
            Timer {
                state,
                handle: Some(handle),
            }
        }

        fn register(&self, waker: &Waker) {
            let (lock, _) = &*self.state;
            lock.lock().unwrap().2 = Some(waker.clone());
        }

        fn elapsed(&self) -> bool {
            let (lock, _) = &*self.state;
            lock.lock().unwrap().0
        }
    }

    impl Drop for Timer {
        fn drop(&mut self) {
            {
                let (lock, cvar) = &*self.state;
                let mut s = lock.lock().unwrap();
                s.1 = true;
                cvar.notify_all();
            }
            if let Some(handle) = self.handle.take() {
                let _ = handle.join();
            }
        }
    }

    let timer = Timer::start(deadline);
    let mut pending = ids.into_iter();
    let mut in_flight: Vec<(u32, FetchFut)> = Vec::new();
    let mut sum: u64 = 0;

    poll_fn(move |cx: &mut Context<'_>| loop {
        if timer.elapsed() {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        let mut advanced = false;

        let mut i = 0;
        while i < in_flight.len() {
            let result = in_flight[i].1.as_mut().poll(cx);
            match result {
                Poll::Ready(Ok(value)) => {
                    sum += value;
                    in_flight.swap_remove(i);
                    advanced = true;
                }
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(SolveError::Fetch { id: in_flight[i].0 }));
                }
                Poll::Pending => i += 1,
            }
        }

        while in_flight.len() < 4 {
            match pending.next() {
                Some(id) => {
                    let fetcher = fetch.clone();
                    in_flight.push((id, Box::pin(async move { fetcher.fetch(id).await })));
                    advanced = true;
                }
                None => break,
            }
        }

        if in_flight.is_empty() {
            return Poll::Ready(Ok(sum));
        }

        if !advanced {
            timer.register(cx.waker());
            if timer.elapsed() {
                return Poll::Ready(Err(SolveError::Deadline));
            }
            return Poll::Pending;
        }
    })
    .await
}

