use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let stage_ref = &stage;

    let results = FanOut::new([StageName::FetchA, StageName::FetchB])
        .at_most(2)
        .run(move |name| async move { stage_ref.run(name).await })
        .await;

    let mut artifacts = match results {
        Ok(artifacts) => artifacts.into_iter(),
        Err(FanOutError::Item { index, .. }) => {
            return Err(PipelineError::Stage {
                name: if index == 0 {
                    StageName::FetchA
                } else {
                    StageName::FetchB
                },
            });
        }
        Err(FanOutError::TimedOut { .. }) => return Err(PipelineError::Deadline),
        Err(FanOutError::Flow(error)) => {
            return Err(if error.is_cancelled() {
                PipelineError::Cancelled
            } else {
                PipelineError::Deadline
            });
        }
        Err(_) => return Err(PipelineError::Deadline),
    };

    let fetch_a = artifacts.next().ok_or(PipelineError::Deadline)?;
    let fetch_b = artifacts.next().ok_or(PipelineError::Deadline)?;

    let combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    let _ = (fetch_a, fetch_b, combined);

    Ok(Published::from(published))
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(outcome) => outcome,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let fetches = {
        let stage = stage.clone();
        FanOut::new([StageName::FetchA, StageName::FetchB])
            .at_most(2)
            .run(move |name| {
                let stage = stage.clone();
                let failed = name.clone();
                async move { stage.run(name).await.map_err(|_| failed) }
            })
            .await
    };

    match fetches {
        Ok(_) => {}
        Err(FanOutError::Item { error, .. }) => {
            return Err(PipelineError::Stage { name: error });
        }
        Err(FanOutError::TimedOut { .. }) => return Err(PipelineError::Deadline),
        Err(_) => return Err(PipelineError::Cancelled),
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageError, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async move {
        let fetch_stage = stage.clone();
        let fetched = FanOut::new([StageName::FetchA, StageName::FetchB])
            .at_most(2)
            .run(move |name: StageName| {
                let stage = fetch_stage.clone();
                async move { stage.run(name).await }
            })
            .await;

        match fetched {
            Ok(_) => {}
            Err(error) => return Err(classify_fanout(error)),
        }

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok(Published::from(artifact))
    };

    match timeout(deadline, pipeline).await {
        Ok(outcome) => outcome,
        Err(_) => Err(PipelineError::Deadline),
    }
}

fn classify_fanout(error: FanOutError<StageError>) -> PipelineError {
    match error {
        FanOutError::Item { index, .. } => PipelineError::Stage {
            name: match index {
                0 => StageName::FetchA,
                _ => StageName::FetchB,
            },
        },
        FanOutError::Flow(flow) if flow.is_cancelled() => PipelineError::Cancelled,
        _ => PipelineError::Deadline,
    }
}

