async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let fetched = FanOut::new([StageName::FetchA, StageName::FetchB])
        .at_most(2)
        .run(|name| {
            let stage = stage.clone();
            async move { stage.run(name).await.map_err(|_| ()) }
        })
        .await;

    match fetched {
        Ok(_) => {}
        Err(FanOutError::Item { index, .. }) => {
            let name = if index == 0 {
                StageName::FetchA
            } else {
                StageName::FetchB
            };
            return Err(PipelineError::Stage { name });
        }
        Err(FanOutError::TimedOut { .. }) => return Err(PipelineError::Deadline),
        Err(_) => return Err(PipelineError::Cancelled),
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;
    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;
    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

enum Either<A, B> {
    Left(A),
    Right(B),
}

struct Select2<A: Future, B: Future> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
}

impl<A: Future, B: Future> Select2<A, B> {
    fn new(a: A, b: B) -> Self {
        Self {
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
        }
    }
}

impl<A: Future, B: Future> Future for Select2<A, B> {
    type Output = Either<A::Output, B::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Some(mut a) = this.a.take() {
            match a.as_mut().poll(cx) {
                Poll::Ready(value) => {
                    this.b = None;
                    return Poll::Ready(Either::Left(value));
                }
                Poll::Pending => this.a = Some(a),
            }
        }

        if let Some(mut b) = this.b.take() {
            match b.as_mut().poll(cx) {
                Poll::Ready(value) => {
                    this.a = None;
                    return Poll::Ready(Either::Right(value));
                }
                Poll::Pending => this.b = Some(b),
            }
        }

        Poll::Pending
    }
}

struct FetchBoth<FA, FB> {
    a: Option<Pin<Box<FA>>>,
    b: Option<Pin<Box<FB>>>,
    va: Option<Artifact>,
    vb: Option<Artifact>,
}

impl<FA, FB> Unpin for FetchBoth<FA, FB> {}

impl<FA, FB> FetchBoth<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    fn new(a: FA, b: FB) -> Self {
        Self {
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
            va: None,
            vb: None,
        }
    }
}

impl<FA, FB> Future for FetchBoth<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Some(mut a) = this.a.take() {
            match a.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.va = Some(value),
                Poll::Ready(Err(_)) => {
                    this.b = None;
                    return Poll::Ready(Err(StageName::FetchA));
                }
                Poll::Pending => this.a = Some(a),
            }
        }

        if let Some(mut b) = this.b.take() {
            match b.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.vb = Some(value),
                Poll::Ready(Err(_)) => {
                    this.a = None;
                    return Poll::Ready(Err(StageName::FetchB));
                }
                Poll::Pending => this.b = Some(b),
            }
        }

        match (this.va.take(), this.vb.take()) {
            (Some(a), Some(b)) => Poll::Ready(Ok((a, b))),
            (a, b) => {
                this.va = a;
                this.vb = b;
                Poll::Pending
            }
        }
    }
}

struct Timer {
    dur: Duration,
    started: bool,
}

impl Timer {
    fn after(dur: Duration) -> Self {
        Self {
            dur,
            started: false,
        }
    }
}

impl Future for Timer {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();

        if this.dur.is_zero() {
            return Poll::Ready(());
        }

        if !this.started {
            this.started = true;
            let waker = cx.waker().clone();
            let dur = this.dur;
            std::thread::spawn(move || {
                std::thread::sleep(dur);
                waker.wake();
            });
        }

        Poll::Pending
    }
}

enum StageOutcome {
    Failed,
    Expired,
}

enum FetchOutcome {
    Failed(StageName),
    Expired,
}

async fn timed<Fut>(start: Instant, limit: Duration, fut: Fut) -> Result<Artifact, StageOutcome>
where
    Fut: Future<Output = Result<Artifact, StageError>>,
{
    let timer = Timer::after(limit.saturating_sub(start.elapsed()));
    match Select2::new(fut, timer).await {
        Either::Left(Ok(artifact)) => Ok(artifact),
        Either::Left(Err(_)) => Err(StageOutcome::Failed),
        Either::Right(()) => Err(StageOutcome::Expired),
    }
}

async fn timed_fetch<FA, FB>(
    start: Instant,
    limit: Duration,
    a: FA,
    b: FB,
) -> Result<(Artifact, Artifact), FetchOutcome>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    let both = FetchBoth::new(a, b);
    let timer = Timer::after(limit.saturating_sub(start.elapsed()));
    match Select2::new(both, timer).await {
        Either::Left(Ok(pair)) => Ok(pair),
        Either::Left(Err(name)) => Err(FetchOutcome::Failed(name)),
        Either::Right(()) => Err(FetchOutcome::Expired),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let start = Instant::now();

    match timed_fetch(
        start,
        deadline,
        stage.run(StageName::FetchA),
        stage.run(StageName::FetchB),
    )
    .await
    {
        Ok(_) => {}
        Err(FetchOutcome::Failed(name)) => return Err(PipelineError::Stage { name }),
        Err(FetchOutcome::Expired) => return Err(PipelineError::Deadline),
    }

    match timed(start, deadline, stage.run(StageName::Combine)).await {
        Ok(_) => {}
        Err(StageOutcome::Failed) => return Err(PipelineError::Stage {
            name: StageName::Combine,
        }),
        Err(StageOutcome::Expired) => return Err(PipelineError::Deadline),
    }

    match timed(start, deadline, stage.run(StageName::Publish)).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(StageOutcome::Failed) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
        Err(StageOutcome::Expired) => Err(PipelineError::Deadline),
    }
}

