#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn fetch_name(index: usize) -> StageName {
    if index == 0 {
        StageName::FetchA
    } else {
        StageName::FetchB
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async move {
        FanOut::new(0..2usize)
            .at_most(2)
            .run(|index| {
                let stage = stage.clone();
                async move { stage.run(fetch_name(index)).await.map_err(|_| ()) }
            })
            .await
            .map_err(|error| match error {
                FanOutError::Item { index, .. } => PipelineError::Stage {
                    name: fetch_name(index),
                },
                FanOutError::TimedOut { .. } => PipelineError::Deadline,
                FanOutError::Flow(error) if error.is_cancelled() => PipelineError::Cancelled,
                FanOutError::Flow(_) => PipelineError::Deadline,
                _ => PipelineError::Deadline,
            })?;

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

        Ok(Published::from(artifact))
    };

    match lgwks_bot::rt::time::timeout(deadline, pipeline).await {
        Ok(outcome) => outcome,
        Err(_) => Err(PipelineError::Deadline),
    }
}

