    match timeout(deadline, run_pipeline(stage)).await {
        Ok(outcome) => outcome,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let fetch_stage = stage.clone();
    let _artifacts = FanOut::new(vec![StageName::FetchA, StageName::FetchB])
        .at_most(2)
        .run(move |name| {
            let stage = fetch_stage.clone();
            async move {
                match stage.run(name.clone()).await {
                    Ok(artifact) => Ok(artifact),
                    Err(_) => Err(name),
                }
            }
        })
        .await
        .map_err(pipeline_error)?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

fn pipeline_error(error: FanOutError<StageName>) -> PipelineError {
    match error {
        FanOutError::Item { error, .. } => PipelineError::Stage { name: error },
        FanOutError::TimedOut { .. } => PipelineError::Deadline,
        FanOutError::Flow(flow) => {
            if flow.is_cancelled() {
                PipelineError::Cancelled
            } else {
                PipelineError::Deadline
            }
        }
        _ => PipelineError::Deadline,
    }
}

