use std::future::Future;
use std::pin::Pin;
use std::sync::mpsc::{self, RecvTimeoutError, Sender};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchFuture<'a> = Pin<Box<dyn Future<Output = (u32, Result<u64, ()>)> + Send + 'a>>;

struct Fanout<'a> {
    fetch: &'a Fetcher,
    pending: std::vec::IntoIter<u32>,
    in_flight: Vec<FetchFuture<'a>>,
    sum: u64,
    deadline_at: Instant,
    waker: Arc<Mutex<Option<Waker>>>,
    _timer: Option<Sender<()>>,
}

impl<'a> Fanout<'a> {
    fn refill(&mut self) -> bool {
        let fetch = self.fetch;
        let mut started = false;
        while self.in_flight.len() < MAX_IN_FLIGHT {
            if Instant::now() >= self.deadline_at {
                break;
            }
            let id = match self.pending.next() {
                Some(id) => id,
                None => break,
            };
            let fut = fetch.fetch(id);
            let boxed: FetchFuture<'a> = Box::pin(async move { (id, fut.await.map_err(|_| ())) });
            self.in_flight.push(boxed);
            started = true;
        }
        started
    }
}

impl<'a> Future for Fanout<'a> {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Ok(mut slot) = this.waker.lock() {
            *slot = Some(cx.waker().clone());
        }

        loop {
            if Instant::now() >= this.deadline_at {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let mut completed = false;
            let mut index = 0;
            while index < this.in_flight.len() {
                let polled = this.in_flight[index].as_mut().poll(cx);
                match polled {
                    Poll::Ready((_id, Ok(value))) => {
                        this.sum += value;
                        this.in_flight.swap_remove(index);
                        completed = true;
                    }
                    Poll::Ready((id, Err(()))) => {
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => {
                        index += 1;
                    }
                }
            }

            let started = this.refill();

            if this.in_flight.is_empty() && this.pending.as_slice().is_empty() {
                return Poll::Ready(Ok(this.sum));
            }

            if this.in_flight.is_empty() {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            if !completed && !started {
                if Instant::now() >= this.deadline_at {
                    return Poll::Ready(Err(SolveError::Deadline));
                }
                return Poll::Pending;
            }
        }
    }
}

fn spawn_deadline_timer(deadline_at: Instant, waker: Arc<Mutex<Option<Waker>>>) -> Sender<()> {
    let (tx, rx) = mpsc::channel::<()>();
    let _ = std::thread::Builder::new()
        .name("aggregate-deadline".to_string())
        .spawn(move || {
            let remaining = deadline_at.saturating_duration_since(Instant::now());
            if let Err(RecvTimeoutError::Timeout) = rx.recv_timeout(remaining) {
                if let Ok(slot) = waker.lock() {
                    if let Some(w) = slot.as_ref() {
                        w.wake_by_ref();
                    }
                }
            }
        });
    tx
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }

    let deadline_at = Instant::now() + deadline;
    let waker: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
    let timer = spawn_deadline_timer(deadline_at, Arc::clone(&waker));

    let mut fan = Fanout {
        fetch: &fetch,
        pending: ids.into_iter(),
        in_flight: Vec::with_capacity(MAX_IN_FLIGHT),
        sum: 0,
        deadline_at,
        waker,
        _timer: Some(timer),
    };

    let result = (&mut fan).await;
    drop(fan);
    result
}

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send + 'static>>;

struct Pending {
    id: u32,
    fut: FetchFuture,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let mut pending: VecDeque<Pending> = VecDeque::with_capacity(ids.len());
    for id in ids {
        let fetcher = fetch.clone();
        let fut: FetchFuture = Box::pin(async move { fetcher.fetch(id).await });
        pending.push_back(Pending { id, fut });
    }

    Solve {
        pending,
        active: Vec::new(),
        sum: 0,
        start: Instant::now(),
        deadline,
        timer: None,
    }
    .await
}

struct Solve {
    pending: VecDeque<Pending>,
    active: Vec<Pending>,
    sum: u64,
    start: Instant,
    deadline: Duration,
    timer: Option<Deadline>,
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();

        if me.pending.is_empty() && me.active.is_empty() {
            return Poll::Ready(Ok(me.sum));
        }

        match &mut me.timer {
            Some(timer) => timer.update_waker(cx.waker()),
            None => {
                let remaining = me.deadline.saturating_sub(me.start.elapsed());
                me.timer = Some(Deadline::start(cx.waker().clone(), remaining));
            }
        }

        loop {
            let timer_fired = me.timer.as_ref().map(Deadline::fired).unwrap_or(false);
            if timer_fired || me.start.elapsed() >= me.deadline {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let mut i = 0;
            while i < me.active.len() {
                match me.active[i].fut.as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        me.sum = me.sum.wrapping_add(value);
                        me.active.swap_remove(i);
                    }
                    Poll::Ready(Err(_)) => {
                        let id = me.active[i].id;
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => i += 1,
                }
            }

            if me.active.is_empty() && me.pending.is_empty() {
                return Poll::Ready(Ok(me.sum));
            }

            let mut started = false;
            while me.active.len() < MAX_IN_FLIGHT {
                match me.pending.pop_front() {
                    Some(item) => {
                        me.active.push(item);
                        started = true;
                    }
                    None => break,
                }
            }

            if !started {
                return Poll::Pending;
            }
        }
    }
}

struct DeadlineInner {
    stop: Mutex<bool>,
    cond: Condvar,
    fired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

struct Deadline {
    inner: Arc<DeadlineInner>,
    handle: Option<JoinHandle<()>>,
}

impl Deadline {
    fn start(waker: Waker, limit: Duration) -> Deadline {
        let inner = Arc::new(DeadlineInner {
            stop: Mutex::new(false),
            cond: Condvar::new(),
            fired: AtomicBool::new(false),
            waker: Mutex::new(Some(waker)),
        });

        let worker = Arc::clone(&inner);
        let handle = thread::spawn(move || {
            let mut stop = worker.stop.lock().unwrap();
            let begin = Instant::now();
            loop {
                if *stop {
                    return;
                }
                let elapsed = begin.elapsed();
                if elapsed >= limit {
                    break;
                }
                let (guard, timeout) = worker
                    .cond
                    .wait_timeout(stop, limit - elapsed)
                    .expect("deadline mutex poisoned");
                stop = guard;
                if timeout.timed_out() {
                    break;
                }
            }
            if *stop {
                return;
            }
            drop(stop);
            worker.fired.store(true, Ordering::SeqCst);
            let waker = worker.waker.lock().unwrap().take();
            if let Some(waker) = waker {
                waker.wake();
            }
        });

        Deadline {
            inner,
            handle: Some(handle),
        }
    }

    fn fired(&self) -> bool {
        self.inner.fired.load(Ordering::SeqCst)
    }

    fn update_waker(&self, waker: &Waker) {
        let mut slot = self.inner.waker.lock().unwrap();
        *slot = Some(waker.clone());
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        {
            let mut stop = self.inner.stop.lock().unwrap();
            *stop = true;
            self.inner.cond.notify_all();
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let pool: NonZeroUsize = match at_most(4) {
        Ok(pool) => pool,
        Err(_) => return Err(SolveError::Cancelled),
    };

    // Remembers the id of the first fetch that failed, so the returned error can
    // name a failing id even if `each` re-locates the body's error on the way out.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_inner = Arc::clone(&failed);
    let scope_ref: &Scope = &scope;

    let work = async move {
        let values = each(
            scope_ref,
            "fetch",
            Some(pool),
            ids.into_iter(),
            move |_step, id| {
                let fetch = fetch.clone();
                let failed = Arc::clone(&failed_inner);
                async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok(value),
                        Err(_) => {
                            let mut slot = match failed.lock() {
                                Ok(slot) => slot,
                                Err(poisoned) => poisoned.into_inner(),
                            };
                            if slot.is_none() {
                                *slot = Some(id);
                            }
                            Err(FlowError::failed("fetch failed"))
                        }
                    }
                }
            },
        )
        .await?;
        Ok::<u64, FlowError>(values.into_iter().sum())
    };

    match within(scope_ref, "solve", deadline, work).await {
        Ok(sum) => Ok(sum),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(SolveError::Cancelled),
        Err(_) => {
            let id = match failed.lock() {
                Ok(slot) => *slot,
                Err(poisoned) => *poisoned.into_inner(),
            };
            Err(SolveError::Fetch { id: id.unwrap_or(0) })
        }
    }
}

use std::future::poll_fn;
use std::future::Future;
use std::pin::Pin;
use std::sync::mpsc::{self, RecvTimeoutError, Sender};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};
use std::vec::IntoIter;

use ai_task_support::Fetcher;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let deadline_at = Instant::now().checked_add(deadline);

    let mut state = State {
        fetch,
        ids: ids.into_iter(),
        sum: 0,
        in_flight: Vec::new(),
        timer: DeadlineTimer::new(deadline_at),
    };

    poll_fn(|cx| state.poll(cx)).await
}

struct InFlight {
    fut: Pin<Box<dyn Future<Output = Result<u64, u32>> + Send>>,
}

struct State {
    fetch: Fetcher,
    ids: IntoIter<u32>,
    sum: u64,
    in_flight: Vec<InFlight>,
    timer: DeadlineTimer,
}

impl State {
    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<Result<u64, SolveError>> {
        loop {
            if self.timer.expired() {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let progressed = match self.poll_all(cx) {
                Ok(progressed) => progressed,
                Err(id) => return Poll::Ready(Err(SolveError::Fetch { id })),
            };

            if self.in_flight.is_empty() && self.ids.len() == 0 {
                return Poll::Ready(Ok(self.sum));
            }

            if let Err(id) = self.start_and_prime(cx) {
                return Poll::Ready(Err(SolveError::Fetch { id }));
            }

            if self.in_flight.is_empty() && self.ids.len() == 0 {
                return Poll::Ready(Ok(self.sum));
            }

            if progressed {
                continue;
            }

            self.timer.arm(cx.waker());
            return Poll::Pending;
        }
    }

    fn poll_all(&mut self, cx: &mut Context<'_>) -> Result<bool, u32> {
        let mut progressed = false;
        let mut index = 0;
        while index < self.in_flight.len() {
            let polled = {
                let entry = &mut self.in_flight[index];
                entry.fut.as_mut().poll(cx)
            };
            match polled {
                Poll::Ready(Ok(value)) => {
                    self.sum = self.sum.wrapping_add(value);
                    self.in_flight.swap_remove(index);
                    progressed = true;
                }
                Poll::Ready(Err(id)) => return Err(id),
                Poll::Pending => index += 1,
            }
        }
        Ok(progressed)
    }

    fn start_and_prime(&mut self, cx: &mut Context<'_>) -> Result<(), u32> {
        while self.in_flight.len() < MAX_IN_FLIGHT {
            let id = match self.ids.next() {
                Some(id) => id,
                None => break,
            };

            let fetch = self.fetch.clone();
            let mut fut: Pin<Box<dyn Future<Output = Result<u64, u32>> + Send>> =
                Box::pin(async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok(value),
                        Err(_) => Err(id),
                    }
                });

            match fut.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => {
                    self.sum = self.sum.wrapping_add(value);
                }
                Poll::Ready(Err(id)) => return Err(id),
                Poll::Pending => self.in_flight.push(InFlight { fut }),
            }
        }
        Ok(())
    }
}

struct DeadlineTimer {
    deadline: Option<Instant>,
    waker: Arc<Mutex<Option<Waker>>>,
    stop: Option<Sender<()>>,
    handle: Option<JoinHandle<()>>,
    started: bool,
}

impl DeadlineTimer {
    fn new(deadline: Option<Instant>) -> Self {
        DeadlineTimer {
            deadline,
            waker: Arc::new(Mutex::new(None)),
            stop: None,
            handle: None,
            started: false,
        }
    }

    fn expired(&self) -> bool {
        match self.deadline {
            Some(deadline) => Instant::now() >= deadline,
            None => false,
        }
    }

    fn arm(&mut self, waker: &Waker) {
        if let Ok(mut slot) = self.waker.lock() {
            *slot = Some(waker.clone());
        }

        if self.started {
            return;
        }

        let deadline = match self.deadline {
            Some(deadline) => deadline,
            None => return,
        };

        self.started = true;
        let remaining = deadline.saturating_duration_since(Instant::now());
        let (tx, rx) = mpsc::channel::<()>();
        let waker_slot = Arc::clone(&self.waker);

        let spawned = thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || match rx.recv_timeout(remaining) {
                Err(RecvTimeoutError::Timeout) => {
                    if let Ok(mut slot) = waker_slot.lock() {
                        if let Some(waker) = slot.take() {
                            waker.wake();
                        }
                    }
                }
                Ok(()) | Err(RecvTimeoutError::Disconnected) => {}
            });

        match spawned {
            Ok(handle) => {
                self.stop = Some(tx);
                self.handle = Some(handle);
            }
            Err(_) => {
                drop(tx);
                self.started = false;
            }
        }
    }
}

impl Drop for DeadlineTimer {
    fn drop(&mut self) {
        self.stop.take();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

type BoxFut = Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>>>>;

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    Solve::new(ids, fetch, deadline).await
}

struct Solve {
    fetch: Fetcher,
    queue: std::vec::IntoIter<u32>,
    remaining: usize,
    active: Vec<(u32, BoxFut)>,
    sum: u64,
    deadline_at: Instant,
    timer: Option<Timer>,
    finished: bool,
}

impl Unpin for Solve {}

impl Solve {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Self {
        let deadline_at = Instant::now() + deadline;
        let remaining = ids.len();
        let timer = if remaining == 0 {
            None
        } else {
            Some(Timer::start(deadline_at))
        };
        Solve {
            fetch,
            queue: ids.into_iter(),
            remaining,
            active: Vec::new(),
            sum: 0,
            deadline_at,
            timer,
            finished: false,
        }
    }

    fn start_one(&mut self, id: u32) {
        let fetcher = self.fetch.clone();
        let fut: BoxFut = Box::pin(async move { fetcher.fetch(id).await });
        self.active.push((id, fut));
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if this.finished {
            return Poll::Pending;
        }
        if let Some(timer) = &this.timer {
            timer.register(cx.waker());
        }

        loop {
            if this.active.is_empty() && this.remaining == 0 {
                this.finished = true;
                this.timer = None;
                return Poll::Ready(Ok(this.sum));
            }

            if Instant::now() >= this.deadline_at {
                this.finished = true;
                this.timer = None;
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let mut failed = None;
            let mut index = 0;
            while index < this.active.len() {
                let outcome = {
                    let (id, fut) = &mut this.active[index];
                    let id = *id;
                    match fut.as_mut().poll(cx) {
                        Poll::Ready(Ok(value)) => Some(Ok(value)),
                        Poll::Ready(Err(_)) => Some(Err(id)),
                        Poll::Pending => None,
                    }
                };
                match outcome {
                    Some(Ok(value)) => {
                        this.sum += value;
                        this.active.swap_remove(index);
                    }
                    Some(Err(id)) => {
                        failed = Some(id);
                        break;
                    }
                    None => index += 1,
                }
            }

            if let Some(id) = failed {
                this.finished = true;
                this.timer = None;
                return Poll::Ready(Err(SolveError::Fetch { id }));
            }

            let mut started = false;
            while this.active.len() < MAX_IN_FLIGHT && this.remaining > 0 {
                match this.queue.next() {
                    Some(id) => {
                        this.remaining -= 1;
                        this.start_one(id);
                        started = true;
                    }
                    None => {
                        this.remaining = 0;
                        break;
                    }
                }
            }

            if !started {
                return Poll::Pending;
            }
        }
    }
}

struct Timer {
    shared: Arc<TimerShared>,
}

struct TimerShared {
    inner: Mutex<TimerInner>,
    signal: Condvar,
    at: Instant,
}

struct TimerInner {
    done: bool,
    waker: Option<Waker>,
}

impl Timer {
    fn start(at: Instant) -> Timer {
        let shared = Arc::new(TimerShared {
            inner: Mutex::new(TimerInner {
                done: false,
                waker: None,
            }),
            signal: Condvar::new(),
            at,
        });
        let worker = Arc::clone(&shared);
        thread::spawn(move || timer_worker(worker));
        Timer { shared }
    }

    fn register(&self, waker: &Waker) {
        if let Ok(mut inner) = self.shared.inner.lock() {
            if !inner.done {
                inner.waker = Some(waker.clone());
            }
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        if let Ok(mut inner) = self.shared.inner.lock() {
            inner.done = true;
        }
        self.shared.signal.notify_all();
    }
}

fn timer_worker(shared: Arc<TimerShared>) {
    let mut inner = match shared.inner.lock() {
        Ok(guard) => guard,
        Err(_) => return,
    };
    loop {
        if inner.done {
            return;
        }
        let now = Instant::now();
        if now >= shared.at {
            let waker = inner.waker.take();
            drop(inner);
            if let Some(waker) = waker {
                waker.wake();
            }
            return;
        }
        let wait = shared.at - now;
        match shared.signal.wait_timeout(inner, wait) {
            Ok((guard, _)) => inner = guard,
            Err(_) => return,
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, OnceLock};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let limit = NonZeroUsize::new(4).expect("4 is non-zero");

    let failed: Arc<OnceLock<u32>> = Arc::new(OnceLock::new());

    let fanout = {
        let fetcher = fetch.clone();
        let failed = Arc::clone(&failed);
        each(
            &scope,
            "fetch",
            Some(limit),
            ids,
            move |_step, id| {
                let fetcher = fetcher.clone();
                let failed = Arc::clone(&failed);
                async move {
                    match fetcher.fetch(id).await {
                        Ok(value) => Ok::<u64, FlowError>(value),
                        Err(_) => {
                            let _ = failed.set(id);
                            Err(FlowError::failed(format!("fetch failed for id {id}")))
                        }
                    }
                }
            },
        )
    };

    match within(&scope, "solve", deadline, fanout).await {
        Ok(values) => Ok(values.into_iter().sum::<u64>()),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(_) => match failed.get() {
            Some(&id) => Err(SolveError::Fetch { id }),
            None => Err(SolveError::Cancelled),
        },
    }
}

use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{at_most, each, within, FlowError, ResultExt, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let pool = match at_most(4) {
        Ok(pool) => pool,
        Err(_) => return Err(SolveError::Cancelled),
    };

    let failed = Arc::new(AtomicU64::new(u64::MAX));

    let outcome = within(
        &scope,
        "solve",
        deadline,
        each(&scope, "fetch", Some(pool), ids, |_scope, id| {
            let fetch = fetch.clone();
            let failed = Arc::clone(&failed);
            async move {
                match fetch.fetch(id).await.or_fail() {
                    Ok(value) => Ok::<u64, FlowError>(value),
                    Err(error) => {
                        let _ = failed.compare_exchange(
                            u64::MAX,
                            u64::from(id),
                            Ordering::Relaxed,
                            Ordering::Relaxed,
                        );
                        Err(error)
                    }
                }
            }
        }),
    )
    .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(error) => {
            if error.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if let FlowError::TimedOut { .. } = error {
                return Err(SolveError::Deadline);
            }
            let id = failed.load(Ordering::Relaxed);
            if id == u64::MAX {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Fetch { id: id as u32 })
            }
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let limit = NonZeroUsize::new(4).expect("a fan-out bound of four is non-zero");

    let failure: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let fanout = each(&scope, "fetch", Some(limit), ids, |_step, id| {
        let fetch = fetch.clone();
        let failure = Arc::clone(&failure);
        async move {
            let observed = match failure.lock() {
                Ok(guard) => guard.is_some(),
                Err(_) => false,
            };
            if observed {
                return Ok::<u64, FlowError>(0);
            }
            match fetch.fetch(id).await {
                Ok(value) => Ok::<u64, FlowError>(value),
                Err(_) => {
                    if let Ok(mut guard) = failure.lock() {
                        if guard.is_none() {
                            *guard = Some(id);
                        }
                    }
                    Ok::<u64, FlowError>(0)
                }
            }
        }
    });

    let outcome = within(&scope, "solve", deadline, fanout).await;
    let failed = match failure.lock() {
        Ok(guard) => *guard,
        Err(_) => None,
    };

    match outcome {
        Ok(values) => match failed {
            Some(id) => Err(SolveError::Fetch { id }),
            None => {
                let total: u64 = values.into_iter().sum();
                Ok(total)
            }
        },
        Err(error) => {
            if let Some(id) = failed {
                Err(SolveError::Fetch { id })
            } else if error.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
    }
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type Work = Pin<Box<dyn Future<Output = (u32, Result<u64, ()>)> + Send>>;

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let deadline_at = Instant::now().checked_add(deadline);

    let fired = Arc::new(AtomicBool::new(false));
    let alive = Arc::new(AtomicBool::new(true));
    let waker_slot: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));

    {
        let fired = Arc::clone(&fired);
        let alive = Arc::clone(&alive);
        let waker_slot = Arc::clone(&waker_slot);
        std::thread::spawn(move || {
            let end = Instant::now().checked_add(deadline);
            while alive.load(Ordering::SeqCst) {
                match end {
                    Some(end) => {
                        let now = Instant::now();
                        if now >= end {
                            fired.store(true, Ordering::SeqCst);
                            if let Ok(mut slot) = waker_slot.lock() {
                                if let Some(waker) = slot.take() {
                                    waker.wake();
                                }
                            }
                            break;
                        }
                        std::thread::sleep((end - now).min(Duration::from_millis(10)));
                    }
                    None => break,
                }
            }
        });
    }

    struct StopOnDrop(Arc<AtomicBool>);
    impl Drop for StopOnDrop {
        fn drop(&mut self) {
            self.0.store(false, Ordering::SeqCst);
        }
    }
    let _stop = StopOnDrop(Arc::clone(&alive));

    let fired_poll = Arc::clone(&fired);
    let waker_poll = Arc::clone(&waker_slot);

    let mut iter = ids.into_iter();
    let mut active: Vec<Work> = Vec::new();
    let mut sum: u64 = 0;

    poll_fn(move |cx: &mut Context<'_>| -> Poll<Result<u64, SolveError>> {
        if let Ok(mut slot) = waker_poll.lock() {
            *slot = Some(cx.waker().clone());
        }

        let past_deadline = || {
            fired_poll.load(Ordering::SeqCst)
                || deadline_at.map_or(false, |d| Instant::now() >= d)
        };

        loop {
            if past_deadline() {
                active.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let mut i = 0;
            while i < active.len() {
                let polled = active[i].as_mut().poll(&mut *cx);
                match polled {
                    Poll::Ready((_, Ok(value))) => {
                        sum += value;
                        active.swap_remove(i);
                    }
                    Poll::Ready((id, Err(()))) => {
                        active.clear();
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => {
                        i += 1;
                    }
                }
            }

            let mut started = false;
            let mut hit_deadline = false;
            while active.len() < MAX_IN_FLIGHT {
                if past_deadline() {
                    hit_deadline = true;
                    break;
                }
                match iter.next() {
                    Some(id) => {
                        let fetcher = fetch.clone();
                        let work: Work = Box::pin(async move {
                            match fetcher.fetch(id).await {
                                Ok(value) => (id, Ok(value)),
                                Err(_) => (id, Err(())),
                            }
                        });
                        active.push(work);
                        started = true;
                    }
                    None => break,
                }
            }

            if hit_deadline {
                active.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            if started {
                continue;
            }

            if active.is_empty() {
                return Poll::Ready(Ok(sum));
            }

            return Poll::Pending;
        }
    })
    .await
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, ResultExt, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = Tenant::new("aggregate").expect("valid tenant name");
    let scope = Scope::root(tenant);

    let limit = NonZeroUsize::new(4).expect("non-zero concurrency bound");

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_in_body = Arc::clone(&failed);

    let work = each(&scope, "fetch", Some(limit), ids, move |_item_scope, id| {
        let fetch = fetch.clone();
        let failed = Arc::clone(&failed_in_body);
        async move {
            let outcome = fetch.fetch(id).await;
            if outcome.is_err() {
                let mut slot = failed.lock().expect("failure slot");
                if slot.is_none() {
                    *slot = Some(id);
                }
            }
            outcome.or_fail()
        }
    });

    match within(&scope, "aggregate", deadline, work).await {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(err) => {
            if let Some(id) = *failed.lock().expect("failure slot") {
                return Err(SolveError::Fetch { id });
            }
            match err {
                FlowError::TimedOut { .. } => Err(SolveError::Deadline),
                _ => Err(SolveError::Cancelled),
            }
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let started = Instant::now();

    let fetches = Box::pin(FetchBoth {
        a: Some(stage.run(StageName::FetchA)),
        b: Some(stage.run(StageName::FetchB)),
        ra: None,
        rb: None,
    });

    let budget = deadline.saturating_sub(started.elapsed());
    if budget.is_zero() {
        return Err(PipelineError::Deadline);
    }
    match WithDeadline::new(fetches, budget).await {
        Outcome::Value(Ok(_)) => {}
        Outcome::Value(Err(name)) => return Err(PipelineError::Stage { name }),
        Outcome::Deadline => return Err(PipelineError::Deadline),
    }

    let budget = deadline.saturating_sub(started.elapsed());
    if budget.is_zero() {
        return Err(PipelineError::Deadline);
    }
    match WithDeadline::new(Box::pin(stage.run(StageName::Combine)), budget).await {
        Outcome::Value(Ok(_)) => {}
        Outcome::Value(Err(_)) => return Err(PipelineError::Stage { name: StageName::Combine }),
        Outcome::Deadline => return Err(PipelineError::Deadline),
    }

    let budget = deadline.saturating_sub(started.elapsed());
    if budget.is_zero() {
        return Err(PipelineError::Deadline);
    }
    let artifact = match WithDeadline::new(Box::pin(stage.run(StageName::Publish)), budget).await {
        Outcome::Value(Ok(artifact)) => artifact,
        Outcome::Value(Err(_)) => return Err(PipelineError::Stage { name: StageName::Publish }),
        Outcome::Deadline => return Err(PipelineError::Deadline),
    };

    Ok(Published::from(artifact))
}

struct FetchBoth<FA, FB> {
    a: Option<FA>,
    b: Option<FB>,
    ra: Option<Artifact>,
    rb: Option<Artifact>,
}

impl<FA, FB> Future for FetchBoth<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };

        if this.ra.is_none() {
            let ready = match this.a.as_mut() {
                Some(fut) => Some(unsafe { Pin::new_unchecked(fut) }.poll(cx)),
                None => None,
            };
            match ready {
                Some(Poll::Ready(Ok(artifact))) => {
                    this.ra = Some(artifact);
                    this.a = None;
                }
                Some(Poll::Ready(Err(_))) => {
                    this.a = None;
                    this.b = None;
                    return Poll::Ready(Err(StageName::FetchA));
                }
                _ => {}
            }
        }

        if this.rb.is_none() {
            let ready = match this.b.as_mut() {
                Some(fut) => Some(unsafe { Pin::new_unchecked(fut) }.poll(cx)),
                None => None,
            };
            match ready {
                Some(Poll::Ready(Ok(artifact))) => {
                    this.rb = Some(artifact);
                    this.b = None;
                }
                Some(Poll::Ready(Err(_))) => {
                    this.a = None;
                    this.b = None;
                    return Poll::Ready(Err(StageName::FetchB));
                }
                _ => {}
            }
        }

        if this.ra.is_some() && this.rb.is_some() {
            let a = this.ra.take().unwrap();
            let b = this.rb.take().unwrap();
            return Poll::Ready(Ok((a, b)));
        }

        Poll::Pending
    }
}

enum Outcome<T> {
    Value(T),
    Deadline,
}

struct WithDeadline<F> {
    fut: Option<Pin<Box<F>>>,
    timer: Timer,
}

impl<F: Future> WithDeadline<F> {
    fn new(fut: Pin<Box<F>>, limit: Duration) -> Self {
        WithDeadline {
            fut: Some(fut),
            timer: Timer::new(limit),
        }
    }
}

impl<F: Future> Future for WithDeadline<F> {
    type Output = Outcome<F::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if let Some(fut) = this.fut.as_mut() {
            if let Poll::Ready(value) = fut.as_mut().poll(cx) {
                this.fut = None;
                return Poll::Ready(Outcome::Value(value));
            }
        }
        if this.timer.poll_ready(cx) {
            this.fut = None;
            return Poll::Ready(Outcome::Deadline);
        }
        Poll::Pending
    }
}

struct Timer {
    inner: Arc<TimerInner>,
}

struct TimerInner {
    fired: AtomicBool,
    cancelled: Mutex<bool>,
    cv: Condvar,
    waker: Mutex<Option<Waker>>,
}

impl Timer {
    fn new(limit: Duration) -> Timer {
        let inner = Arc::new(TimerInner {
            fired: AtomicBool::new(false),
            cancelled: Mutex::new(false),
            cv: Condvar::new(),
            waker: Mutex::new(None),
        });

        let worker = inner.clone();
        let _ = std::thread::Builder::new()
            .name("pipeline-timer".to_string())
            .spawn(move || {
                let started = Instant::now();
                let mut guard = match worker.cancelled.lock() {
                    Ok(guard) => guard,
                    Err(_) => return,
                };
                loop {
                    if *guard {
                        return;
                    }
                    let elapsed = started.elapsed();
                    if elapsed >= limit {
                        break;
                    }
                    let wait = limit - elapsed;
                    match worker.cv.wait_timeout(guard, wait) {
                        Ok((next, _)) => guard = next,
                        Err(_) => return,
                    }
                }
                drop(guard);

                worker.fired.store(true, Ordering::SeqCst);
                if let Ok(mut slot) = worker.waker.lock() {
                    if let Some(waker) = slot.take() {
                        waker.wake();
                    }
                }
            });

        Timer { inner }
    }

    fn poll_ready(&self, cx: &mut Context<'_>) -> bool {
        if self.inner.fired.load(Ordering::SeqCst) {
            return true;
        }
        if let Ok(mut slot) = self.inner.waker.lock() {
            *slot = Some(cx.waker().clone());
        }
        self.inner.fired.load(Ordering::SeqCst)
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        if self.inner.fired.load(Ordering::SeqCst) {
            return;
        }
        if let Ok(mut guard) = self.inner.cancelled.lock() {
            *guard = true;
            self.inner.cv.notify_all();
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let body = run_pipeline(&stage);
    match Timeout::new(Box::pin(body), deadline).await {
        Ok(result) => result,
        Err(Elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    let fetch_a = async { stage.run(StageName::FetchA).await.map_err(|_| StageName::FetchA) };
    let fetch_b = async { stage.run(StageName::FetchB).await.map_err(|_| StageName::FetchB) };

    let _ = Both::new(fetch_a, fetch_b)
        .await
        .map_err(|name| PipelineError::Stage { name })?;

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

struct Both<A, B>
where
    A: Future<Output = Result<Artifact, StageName>>,
    B: Future<Output = Result<Artifact, StageName>>,
{
    a: Option<A>,
    b: Option<B>,
    out_a: Option<Artifact>,
    out_b: Option<Artifact>,
}

impl<A, B> Both<A, B>
where
    A: Future<Output = Result<Artifact, StageName>>,
    B: Future<Output = Result<Artifact, StageName>>,
{
    fn new(a: A, b: B) -> Self {
        Self {
            a: Some(a),
            b: Some(b),
            out_a: None,
            out_b: None,
        }
    }
}

impl<A, B> Future for Both<A, B>
where
    A: Future<Output = Result<Artifact, StageName>>,
    B: Future<Output = Result<Artifact, StageName>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };

        if this.out_a.is_none() {
            let mut ready = None;
            if let Some(a) = this.a.as_mut() {
                let a = unsafe { Pin::new_unchecked(a) };
                if let Poll::Ready(value) = a.poll(cx) {
                    ready = Some(value);
                }
            }
            if let Some(value) = ready {
                this.a = None;
                match value {
                    Ok(value) => this.out_a = Some(value),
                    Err(error) => return Poll::Ready(Err(error)),
                }
            }
        }

        if this.out_b.is_none() {
            let mut ready = None;
            if let Some(b) = this.b.as_mut() {
                let b = unsafe { Pin::new_unchecked(b) };
                if let Poll::Ready(value) = b.poll(cx) {
                    ready = Some(value);
                }
            }
            if let Some(value) = ready {
                this.b = None;
                match value {
                    Ok(value) => this.out_b = Some(value),
                    Err(error) => return Poll::Ready(Err(error)),
                }
            }
        }

        if this.out_a.is_some() && this.out_b.is_some() {
            Poll::Ready(Ok((
                this.out_a.take().unwrap(),
                this.out_b.take().unwrap(),
            )))
        } else {
            Poll::Pending
        }
    }
}

struct Timeout<F> {
    body: Pin<Box<F>>,
    deadline: Option<Instant>,
    armed: bool,
}

impl<F> Timeout<F>
where
    F: Future,
{
    fn new(body: Pin<Box<F>>, limit: Duration) -> Self {
        Self {
            body,
            deadline: Instant::now().checked_add(limit),
            armed: false,
        }
    }
}

impl<F> Future for Timeout<F>
where
    F: Future,
{
    type Output = Result<F::Output, Elapsed>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Poll::Ready(value) = this.body.as_mut().poll(cx) {
            return Poll::Ready(Ok(value));
        }

        if let Some(deadline) = this.deadline {
            if Instant::now() >= deadline {
                return Poll::Ready(Err(Elapsed));
            }
            if !this.armed {
                this.armed = true;
                let waker = cx.waker().clone();
                std::thread::spawn(move || {
                    let now = Instant::now();
                    if deadline > now {
                        std::thread::sleep(deadline - now);
                    }
                    waker.wake();
                });
            }
        }

        Poll::Pending
    }
}

struct Elapsed;

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle, Thread};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let started = Instant::now();
    let end = started.checked_add(deadline);

    {
        let a = Box::pin(stage.run(StageName::FetchA));
        let b = Box::pin(stage.run(StageName::FetchB));
        let both = FetchJoin {
            a: Some(a),
            b: Some(b),
            done_a: false,
            done_b: false,
        };
        match Deadline::new(both, end).await {
            Ok(Ok(())) => {}
            Ok(Err(name)) => return Err(PipelineError::Stage { name }),
            Err(Elapsed) => return Err(PipelineError::Deadline),
        }
    }

    {
        let combined = Box::pin(stage.run(StageName::Combine));
        match Deadline::new(combined, end).await {
            Ok(Ok(_)) => {}
            Ok(Err(_)) => return Err(PipelineError::Stage { name: StageName::Combine }),
            Err(Elapsed) => return Err(PipelineError::Deadline),
        }
    }

    let published = Box::pin(stage.run(StageName::Publish));
    match Deadline::new(published, end).await {
        Ok(Ok(artifact)) => Ok(Published::from(artifact)),
        Ok(Err(_)) => Err(PipelineError::Stage { name: StageName::Publish }),
        Err(Elapsed) => Err(PipelineError::Deadline),
    }
}

struct FetchJoin<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    done_a: bool,
    done_b: bool,
}

impl<A, B> Future for FetchJoin<A, B>
where
    A: Future<Output = Result<Artifact, StageError>>,
    B: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.a.is_some() {
            let outcome = {
                let a = this.a.as_mut().unwrap();
                a.as_mut().poll(cx)
            };
            match outcome {
                Poll::Ready(Ok(_)) => {
                    this.a = None;
                    this.done_a = true;
                }
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchA)),
                Poll::Pending => {}
            }
        }

        if this.b.is_some() {
            let outcome = {
                let b = this.b.as_mut().unwrap();
                b.as_mut().poll(cx)
            };
            match outcome {
                Poll::Ready(Ok(_)) => {
                    this.b = None;
                    this.done_b = true;
                }
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchB)),
                Poll::Pending => {}
            }
        }

        if this.done_a && this.done_b {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    }
}

struct Elapsed;

struct Deadline<F> {
    future: F,
    timer: Timer,
}

impl<F> Deadline<F> {
    fn new(future: F, deadline: Option<Instant>) -> Self {
        Deadline {
            future,
            timer: Timer::new(deadline),
        }
    }
}

impl<F> Future for Deadline<F>
where
    F: Future + Unpin,
{
    type Output = Result<F::Output, Elapsed>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.timer.expired() {
            return Poll::Ready(Err(Elapsed));
        }

        {
            let future = Pin::new(&mut this.future);
            if let Poll::Ready(value) = future.poll(cx) {
                return Poll::Ready(Ok(value));
            }
        }

        let timer = Pin::new(&mut this.timer);
        match timer.poll(cx) {
            Poll::Ready(()) => Poll::Ready(Err(Elapsed)),
            Poll::Pending => Poll::Pending,
        }
    }
}

struct TimerState {
    waker: Mutex<Option<Waker>>,
    stop: AtomicBool,
}

fn store_waker(state: &TimerState, waker: Waker) {
    match state.waker.lock() {
        Ok(mut slot) => *slot = Some(waker),
        Err(poisoned) => *poisoned.into_inner() = Some(waker),
    }
}

fn take_waker(state: &TimerState) -> Option<Waker> {
    match state.waker.lock() {
        Ok(mut slot) => slot.take(),
        Err(poisoned) => poisoned.into_inner().take(),
    }
}

struct Timer {
    deadline: Option<Instant>,
    state: Arc<TimerState>,
    worker: Option<JoinHandle<()>>,
    thread: Option<Thread>,
    started: bool,
}

impl Timer {
    fn new(deadline: Option<Instant>) -> Self {
        Timer {
            deadline,
            state: Arc::new(TimerState {
                waker: Mutex::new(None),
                stop: AtomicBool::new(false),
            }),
            worker: None,
            thread: None,
            started: false,
        }
    }

    fn expired(&self) -> bool {
        match self.deadline {
            Some(at) => Instant::now() >= at,
            None => false,
        }
    }
}

impl Future for Timer {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();

        store_waker(&this.state, cx.waker().clone());

        let at = match this.deadline {
            Some(at) => at,
            None => return Poll::Pending,
        };

        if Instant::now() >= at {
            return Poll::Ready(());
        }

        if !this.started {
            this.started = true;
            let state = Arc::clone(&this.state);
            let spawned = thread::Builder::new()
                .name("pipeline-deadline".to_string())
                .spawn(move || loop {
                    if state.stop.load(Ordering::SeqCst) {
                        break;
                    }
                    let now = Instant::now();
                    if now >= at {
                        if let Some(waker) = take_waker(&state) {
                            waker.wake();
                        }
                        break;
                    }
                    thread::park_timeout(at - now);
                });
            if let Ok(handle) = spawned {
                this.thread = Some(handle.thread().clone());
                this.worker = Some(handle);
            }
        }

        Poll::Pending
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        self.state.stop.store(true, Ordering::SeqCst);
        if let Some(thread) = &self.thread {
            thread.unpark();
        }
        if let Some(handle) = self.worker.take() {
            let _ = handle.join();
        }
    }
}

use std::num::NonZeroUsize;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let outcome = within(&scope, "solve", deadline, async {
        Ok::<Result<Published, PipelineError>, FlowError>(run_pipeline(stage, &scope).await)
    })
    .await;

    match outcome {
        Ok(result) => result,
        Err(error) => {
            if error.is_cancelled() {
                Err(PipelineError::Cancelled)
            } else {
                Err(PipelineError::Deadline)
            }
        }
    }
}

async fn run_pipeline(stage: Stage, scope: &Scope) -> Result<Published, PipelineError> {
    let limit = NonZeroUsize::new(2).ok_or(PipelineError::Cancelled)?;

    let fetched: Vec<Result<Artifact, StageError>> = each(
        scope,
        "fetch",
        Some(limit),
        vec![StageName::FetchA, StageName::FetchB],
        |_step: Scope, name: StageName| {
            let stage = stage.clone();
            async move { Ok::<Result<Artifact, StageError>, FlowError>(stage.run(name).await) }
        },
    )
    .await
    .map_err(|_| PipelineError::Cancelled)?;

    let mut fetches = fetched.into_iter();
    match (fetches.next(), fetches.next()) {
        (Some(Ok(_)), Some(Ok(_))) => {}
        (Some(Err(_)), _) => return Err(PipelineError::Stage { name: StageName::FetchA }),
        (_, Some(Err(_))) => return Err(PipelineError::Stage { name: StageName::FetchB }),
        _ => return Err(PipelineError::Cancelled),
    }

    let _ = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let a = stage.run(StageName::FetchA);
        let b = stage.run(StageName::FetchB);
        let (_a, _b) = Join2::new(a, b)
            .await
            .map_err(|name| PipelineError::Stage { name })?;

        let _combined = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok(Published::from(published))
    };

    Timeout::new(work, deadline).await
}

struct Join2<F> {
    a: F,
    b: F,
    a_done: bool,
    b_done: bool,
    a_out: Option<Artifact>,
    b_out: Option<Artifact>,
}

impl<F> Join2<F> {
    fn new(a: F, b: F) -> Self {
        Self {
            a,
            b,
            a_done: false,
            b_done: false,
            a_out: None,
            b_out: None,
        }
    }
}

impl<F> Future for Join2<F>
where
    F: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };

        if !this.a_done {
            let fut = unsafe { Pin::new_unchecked(&mut this.a) };
            match fut.poll(cx) {
                Poll::Ready(Ok(art)) => {
                    this.a_out = Some(art);
                    this.a_done = true;
                }
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchA)),
                Poll::Pending => {}
            }
        }

        if !this.b_done {
            let fut = unsafe { Pin::new_unchecked(&mut this.b) };
            match fut.poll(cx) {
                Poll::Ready(Ok(art)) => {
                    this.b_out = Some(art);
                    this.b_done = true;
                }
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchB)),
                Poll::Pending => {}
            }
        }

        if this.a_done && this.b_done {
            let a = this.a_out.take().expect("fetch_a artifact");
            let b = this.b_out.take().expect("fetch_b artifact");
            Poll::Ready(Ok((a, b)))
        } else {
            Poll::Pending
        }
    }
}

struct Timeout<F> {
    inner: F,
    expired: Arc<AtomicBool>,
    waker: Arc<Mutex<Option<Waker>>>,
    _guard: mpsc::Sender<()>,
}

impl<F> Timeout<F> {
    fn new(inner: F, deadline: Duration) -> Self {
        let expired = Arc::new(AtomicBool::new(false));
        let waker: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
        let (tx, rx) = mpsc::channel::<()>();

        let expired_thread = Arc::clone(&expired);
        let waker_thread = Arc::clone(&waker);
        std::thread::spawn(move || match rx.recv_timeout(deadline) {
            Err(mpsc::RecvTimeoutError::Timeout) => {
                expired_thread.store(true, Ordering::SeqCst);
                let woken = waker_thread.lock().ok().and_then(|mut slot| slot.take());
                if let Some(w) = woken {
                    w.wake();
                }
            }
            _ => {}
        });

        Self {
            inner,
            expired,
            waker,
            _guard: tx,
        }
    }
}

impl<F> Future for Timeout<F>
where
    F: Future<Output = Result<Published, PipelineError>>,
{
    type Output = Result<Published, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };

        if this.expired.load(Ordering::SeqCst) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        if let Ok(mut slot) = this.waker.lock() {
            *slot = Some(cx.waker().clone());
        }

        let inner = unsafe { Pin::new_unchecked(&mut this.inner) };
        match inner.poll(cx) {
            Poll::Ready(result) => Poll::Ready(result),
            Poll::Pending => {
                if this.expired.load(Ordering::SeqCst) {
                    Poll::Ready(Err(PipelineError::Deadline))
                } else {
                    Poll::Pending
                }
            }
        }
    }
}

//! A tiny orchestration pipeline over `ai_task_support`.

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async {
        let (a, b) = Join::new(
            stage.run(StageName::FetchA),
            stage.run(StageName::FetchB),
        )
        .await
        .map_err(|name| PipelineError::Stage { name })?;
        drop((a, b));

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok::<Published, PipelineError>(Published::from(published))
    };

    match Timeout::new(deadline, pipeline).await {
        Ok(result) => result,
        Err(()) => Err(PipelineError::Deadline),
    }
}

struct Join<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    a_val: Option<Artifact>,
    b_val: Option<Artifact>,
}

impl<A, B> Unpin for Join<A, B> {}

impl<A, B> Join<A, B> {
    fn new(a: A, b: B) -> Self {
        Join {
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
            a_val: None,
            b_val: None,
        }
    }
}

impl<A, B> Future for Join<A, B>
where
    A: Future<Output = Result<Artifact, StageError>>,
    B: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Some(mut a) = this.a.take() {
            match a.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.a_val = Some(value),
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchA)),
                Poll::Pending => this.a = Some(a),
            }
        }

        if let Some(mut b) = this.b.take() {
            match b.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.b_val = Some(value),
                Poll::Ready(Err(_)) => return Poll::Ready(Err(StageName::FetchB)),
                Poll::Pending => this.b = Some(b),
            }
        }

        if this.a.is_none() && this.b.is_none() {
            if let (Some(a), Some(b)) = (this.a_val.take(), this.b_val.take()) {
                return Poll::Ready(Ok((a, b)));
            }
        }

        Poll::Pending
    }
}

struct Timeout<F> {
    fut: Option<Pin<Box<F>>>,
    sleep: Sleep,
}

impl<F> Unpin for Timeout<F> {}

impl<F: Future> Timeout<F> {
    fn new(limit: Duration, fut: F) -> Self {
        Timeout {
            fut: Some(Box::pin(fut)),
            sleep: Sleep::new(limit),
        }
    }
}

impl<F: Future> Future for Timeout<F> {
    type Output = Result<F::Output, ()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Some(mut fut) = this.fut.take() {
            match fut.as_mut().poll(cx) {
                Poll::Ready(value) => return Poll::Ready(Ok(value)),
                Poll::Pending => this.fut = Some(fut),
            }
        }

        match Pin::new(&mut this.sleep).poll(cx) {
            Poll::Ready(()) => Poll::Ready(Err(())),
            Poll::Pending => Poll::Pending,
        }
    }
}

struct Shared {
    state: Mutex<TimerState>,
    condvar: Condvar,
}

struct TimerState {
    done: bool,
    waker: Option<Waker>,
}

struct Sleep {
    shared: Arc<Shared>,
}

impl Sleep {
    fn new(limit: Duration) -> Self {
        let shared = Arc::new(Shared {
            state: Mutex::new(TimerState {
                done: false,
                waker: None,
            }),
            condvar: Condvar::new(),
        });

        let thread_shared = Arc::clone(&shared);
        std::thread::spawn(move || {
            let mut state = thread_shared.state.lock().unwrap();
            let deadline = Instant::now() + limit;

            loop {
                if state.done {
                    return;
                }

                let now = Instant::now();
                if now >= deadline {
                    state.done = true;
                    let waker = state.waker.take();
                    drop(state);
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }

                let (guard, _) = thread_shared
                    .condvar
                    .wait_timeout(state, deadline - now)
                    .unwrap();
                state = guard;
            }
        });

        Sleep { shared }
    }
}

impl Future for Sleep {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let mut state = self.shared.state.lock().unwrap();
        if state.done {
            Poll::Ready(())
        } else {
            state.waker = Some(cx.waker().clone());
            Poll::Pending
        }
    }
}

impl Drop for Sleep {
    fn drop(&mut self) {
        let mut state = self.shared.state.lock().unwrap();
        state.done = true;
        self.shared.condvar.notify_all();
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct TimerInner {
    fired: bool,
    cancelled: bool,
    waker: Option<Waker>,
}

struct Timer {
    inner: Arc<(Mutex<TimerInner>, Condvar)>,
    handle: Option<thread::JoinHandle<()>>,
}

impl Timer {
    fn new(at: Instant) -> Timer {
        let inner = Arc::new((
            Mutex::new(TimerInner {
                fired: false,
                cancelled: false,
                waker: None,
            }),
            Condvar::new(),
        ));
        let worker = Arc::clone(&inner);
        let handle = thread::spawn(move || {
            let (lock, condvar) = &*worker;
            let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            loop {
                if guard.cancelled {
                    return;
                }
                let now = Instant::now();
                if now >= at {
                    break;
                }
                let wait = at - now;
                let (next, _) = condvar
                    .wait_timeout(guard, wait)
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                guard = next;
            }
            if guard.cancelled {
                return;
            }
            guard.fired = true;
            if let Some(waker) = guard.waker.take() {
                waker.wake();
            }
        });
        Timer {
            inner,
            handle: Some(handle),
        }
    }

    fn register_and_check(&self, cx: &mut Context<'_>) -> bool {
        let (lock, _) = &*self.inner;
        let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if guard.fired {
            true
        } else {
            guard.waker = Some(cx.waker().clone());
            false
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        {
            let (lock, condvar) = &*self.inner;
            let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            guard.cancelled = true;
            condvar.notify_all();
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

struct Timeout<F> {
    fut: Pin<Box<F>>,
    timer: Timer,
}

impl<F> Unpin for Timeout<F> {}

impl<F: Future> Future for Timeout<F> {
    type Output = Result<F::Output, ()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        let fired = this.timer.register_and_check(cx);
        match this.fut.as_mut().poll(cx) {
            Poll::Ready(value) => Poll::Ready(Ok(value)),
            Poll::Pending => {
                if fired {
                    Poll::Ready(Err(()))
                } else {
                    Poll::Pending
                }
            }
        }
    }
}

async fn guarded<T, F>(
    name: StageName,
    deadline_at: Option<Instant>,
    fut: F,
) -> Result<T, PipelineError>
where
    F: Future<Output = Result<T, StageError>>,
{
    match deadline_at {
        Some(at) => {
            if Instant::now() >= at {
                return Err(PipelineError::Deadline);
            }
            let outcome = Timeout {
                fut: Box::pin(fut),
                timer: Timer::new(at),
            }
            .await;
            match outcome {
                Ok(Ok(value)) => Ok(value),
                Ok(Err(_)) => Err(PipelineError::Stage { name }),
                Err(()) => Err(PipelineError::Deadline),
            }
        }
        None => match fut.await {
            Ok(value) => Ok(value),
            Err(_) => Err(PipelineError::Stage { name }),
        },
    }
}

struct Both<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    done_a: Option<Artifact>,
    done_b: Option<Artifact>,
}

impl<A, B> Unpin for Both<A, B> {}

impl<A, B> Both<A, B>
where
    A: Future<Output = Result<Artifact, PipelineError>>,
    B: Future<Output = Result<Artifact, PipelineError>>,
{
    fn new(a: A, b: B) -> Self {
        Both {
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
            done_a: None,
            done_b: None,
        }
    }
}

impl<A, B> Future for Both<A, B>
where
    A: Future<Output = Result<Artifact, PipelineError>>,
    B: Future<Output = Result<Artifact, PipelineError>>,
{
    type Output = Result<(Artifact, Artifact), PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.done_a.is_none() {
            if let Some(mut fut) = this.a.take() {
                match fut.as_mut().poll(cx) {
                    Poll::Ready(Ok(artifact)) => this.done_a = Some(artifact),
                    Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                    Poll::Pending => this.a = Some(fut),
                }
            }
        }

        if this.done_b.is_none() {
            if let Some(mut fut) = this.b.take() {
                match fut.as_mut().poll(cx) {
                    Poll::Ready(Ok(artifact)) => this.done_b = Some(artifact),
                    Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                    Poll::Pending => this.b = Some(fut),
                }
            }
        }

        match (this.done_a.take(), this.done_b.take()) {
            (Some(a), Some(b)) => Poll::Ready(Ok((a, b))),
            (a, b) => {
                this.done_a = a;
                this.done_b = b;
                Poll::Pending
            }
        }
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let deadline_at = Instant::now().checked_add(deadline);

    {
        let fut_a = guarded(StageName::FetchA, deadline_at, stage.run(StageName::FetchA));
        let fut_b = guarded(StageName::FetchB, deadline_at, stage.run(StageName::FetchB));
        Both::new(fut_a, fut_b).await?;
    }

    let _ = guarded(
        StageName::Combine,
        deadline_at,
        stage.run(StageName::Combine),
    )
    .await?;

    let artifact = guarded(
        StageName::Publish,
        deadline_at,
        stage.run(StageName::Publish),
    )
    .await?;

    Ok(Published::from(artifact))
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

enum Outcome {
    Done(Published),
    Failed(StageName),
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").ok().expect("valid tenant name");
    let scope = Scope::root(tenant);
    let scope_ref = &scope;

    let outcome = within(scope_ref, "pipeline", deadline, async move {
        let fetched = each(
            scope_ref,
            "fetch",
            None,
            [StageName::FetchA, StageName::FetchB],
            |_scope, name| {
                let stage = stage.clone();
                async move {
                    let ok = stage.run(name).await.is_ok();
                    Ok::<(StageName, bool), FlowError>((name, ok))
                }
            },
        )
        .await?;

        if let Some((name, _)) = fetched.into_iter().find(|(_, ok)| !*ok) {
            return Ok(Outcome::Failed(name));
        }

        if stage.run(StageName::Combine).await.is_err() {
            return Ok(Outcome::Failed(StageName::Combine));
        }

        match stage.run(StageName::Publish).await {
            Ok(artifact) => Ok(Outcome::Done(Published::from(artifact))),
            Err(_) => Ok(Outcome::Failed(StageName::Publish)),
        }
    })
    .await;

    match outcome {
        Ok(Outcome::Done(published)) => Ok(published),
        Ok(Outcome::Failed(name)) => Err(PipelineError::Stage { name }),
        Err(error) if error.is_cancelled() => Err(PipelineError::Cancelled),
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let scope = match Tenant::new("pipeline") {
        Ok(tenant) => Scope::root(tenant),
        Err(_) => return Err(PipelineError::Cancelled),
    };

    let outcome = within(&scope, "solve", deadline, async {
        let failed: Arc<Mutex<Option<usize>>> = Arc::new(Mutex::new(None));
        let limit = Some(at_most(2)?);

        let fetched = each(
            &scope,
            "fetch",
            limit,
            [(StageName::FetchA, 0usize), (StageName::FetchB, 1usize)],
            |_step, (name, index)| {
                let stage = stage.clone();
                let failed = Arc::clone(&failed);
                async move {
                    match stage.run(name).await {
                        Ok(artifact) => Ok(artifact),
                        Err(_) => {
                            if let Ok(mut slot) = failed.lock() {
                                *slot = Some(index);
                            }
                            Err(FlowError::failed("fetch stage failed"))
                        }
                    }
                }
            },
        )
        .await;

        if let Err(error) = fetched {
            return match failed.lock().ok().and_then(|mut slot| slot.take()) {
                Some(index) => Ok(Err(PipelineError::Stage {
                    name: if index == 0 {
                        StageName::FetchA
                    } else {
                        StageName::FetchB
                    },
                })),
                None => Err(error),
            };
        }

        if stage.run(StageName::Combine).await.is_err() {
            return Ok(Err(PipelineError::Stage {
                name: StageName::Combine,
            }));
        }

        match stage.run(StageName::Publish).await {
            Ok(published) => Ok(Ok(Published::from(published))),
            Err(_) => Ok(Err(PipelineError::Stage {
                name: StageName::Publish,
            })),
        }
    })
    .await;

    match outcome {
        Ok(Ok(published)) => Ok(published),
        Ok(Err(error)) => Err(error),
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(PipelineError::Cancelled),
        Err(_) => Err(PipelineError::Cancelled),
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));

    // The whole pipeline runs inside one `within`, so the overall deadline and any
    // cancellation race the entire run and drop every body the future owns.
    let body = {
        let scope_ref: &Scope = &scope;
        let stage_ref: &Stage = &stage;
        let failed_ref = Arc::clone(&failed);
        async move {
            let failed_for_fetch = Arc::clone(&failed_ref);

            // fetch_a and fetch_b are independent, so drive them concurrently
            // (bounded fan-out) and keep both values until both succeed.
            let fetched = each(
                scope_ref,
                "fetch",
                NonZeroUsize::new(2),
                [0usize, 1usize],
                move |_step, index| {
                    let failed = Arc::clone(&failed_for_fetch);
                    async move {
                        let name = match index {
                            0 => StageName::FetchA,
                            _ => StageName::FetchB,
                        };
                        match stage_ref.run(name).await {
                            Ok(artifact) => Ok(artifact),
                            Err(_) => {
                                let name = match index {
                                    0 => StageName::FetchA,
                                    _ => StageName::FetchB,
                                };
                                *failed.lock().expect("pipeline lock") = Some(name);
                                Err(FlowError::failed("fetch stage failed"))
                            }
                        }
                    }
                },
            )
            .await?;

            // Both fetches succeeded; only now may combine run.
            drop(fetched);

            let _combined = match stage_ref.run(StageName::Combine).await {
                Ok(artifact) => artifact,
                Err(_) => {
                    *failed_ref.lock().expect("pipeline lock") = Some(StageName::Combine);
                    return Err(FlowError::failed("combine stage failed"));
                }
            };

            let published: Published = match stage_ref.run(StageName::Publish).await {
                Ok(artifact) => artifact.into(),
                Err(_) => {
                    *failed_ref.lock().expect("pipeline lock") = Some(StageName::Publish);
                    return Err(FlowError::failed("publish stage failed"));
                }
            };

            Ok(published)
        }
    };

    let outcome = within(&scope, "solve", deadline, body).await;
    let failed = failed.lock().expect("pipeline lock").take();

    match outcome {
        Ok(published) => Ok(published),
        Err(error) => {
            if matches!(error, FlowError::TimedOut { .. }) {
                return Err(PipelineError::Deadline);
            }
            if error.is_cancelled() {
                return Err(PipelineError::Cancelled);
            }
            match failed {
                Some(name) => Err(PipelineError::Stage { name }),
                None => Err(PipelineError::Deadline),
            }
        }
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let work = async move {
        let mut sum: u64 = 0;
        let mut pending = ids.into_iter();

        loop {
            let wave: Vec<u32> = pending.by_ref().take(4).collect();
            if wave.is_empty() {
                break;
            }

            let mut futures = Vec::with_capacity(wave.len());
            for id in wave {
                let fetch = fetch.clone();
                futures.push(async move { (id, fetch.fetch(id).await) });
            }

            for (id, result) in join_all_bounded(4, futures).await {
                match result {
                    Ok(value) => sum += value,
                    Err(_) => return Err(SolveError::Fetch { id }),
                }
            }
        }

        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(outcome) => outcome,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const LIMIT: usize = 4;

async fn fetch_one(
    fetch: ai_task_support::Fetcher,
    stop: Arc<AtomicBool>,
    id: u32,
) -> Result<u64, u32> {
    if stop.load(Ordering::SeqCst) {
        return Ok(0);
    }
    match fetch.fetch(id).await {
        Ok(value) => Ok(value),
        Err(_) => {
            stop.store(true, Ordering::SeqCst);
            Err(id)
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let stop = Arc::new(AtomicBool::new(false));

    let work = async move {
        let mut pending = ids.into_iter();
        let mut set: JoinSet<Result<u64, u32>> = JoinSet::new();
        let mut sum: u64 = 0;

        for _ in 0..LIMIT {
            match pending.next() {
                Some(id) => {
                    let _ = set.spawn(fetch_one(fetch.clone(), Arc::clone(&stop), id));
                }
                None => break,
            }
        }

        while let Some(joined) = set.join_next().await {
            match joined {
                Ok(Ok(value)) => {
                    sum = sum.wrapping_add(value);
                    if !stop.load(Ordering::SeqCst) {
                        if let Some(id) = pending.next() {
                            let _ =
                                set.spawn(fetch_one(fetch.clone(), Arc::clone(&stop), id));
                        }
                    }
                }
                Ok(Err(id)) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id });
                }
                Err(_) => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::cancel::CancellationToken;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::sleep;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchOutcome = Result<u64, u32>;

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let deadline_root = CancellationToken::new();
    let work_token = deadline_root.child_token();

    let mut timers: JoinSet<()> = JoinSet::new();
    let _ = timers.spawn(async move {
        sleep(deadline).await;
        deadline_root.cancel();
    });

    let outcome = work_token
        .run_until_cancelled(run_fetches(ids, fetch))
        .await;

    timers.abort_all();
    while timers.join_next().await.is_some() {}

    match outcome {
        Some(result) => result,
        None => Err(SolveError::Deadline),
    }
}

async fn run_fetches(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let stop = Arc::new(AtomicBool::new(false));
    let mut tasks: JoinSet<FetchOutcome> = JoinSet::new();
    let mut remaining = ids.into_iter();
    let mut sum: u64 = 0;

    for _ in 0..MAX_IN_FLIGHT {
        match remaining.next() {
            Some(id) => spawn_fetch(&mut tasks, &fetch, &stop, id),
            None => break,
        }
    }

    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(value)) => {
                sum += value;
                if let Some(id) = remaining.next() {
                    spawn_fetch(&mut tasks, &fetch, &stop, id);
                }
            }
            Ok(Err(id)) => {
                stop.store(true, Ordering::SeqCst);
                abort_and_drain(&mut tasks).await;
                return Err(SolveError::Fetch { id });
            }
            Err(_join_error) => {
                stop.store(true, Ordering::SeqCst);
                abort_and_drain(&mut tasks).await;
                return Err(SolveError::Cancelled);
            }
        }
    }

    Ok(sum)
}

fn spawn_fetch(
    tasks: &mut JoinSet<FetchOutcome>,
    fetch: &Fetcher,
    stop: &Arc<AtomicBool>,
    id: u32,
) {
    let fetch = fetch.clone();
    let stop = Arc::clone(stop);
    let _ = tasks.spawn(async move {
        if stop.load(Ordering::SeqCst) {
            return Ok(0);
        }
        fetch.fetch(id).await.map_err(|_error| id)
    });
}

async fn abort_and_drain(tasks: &mut JoinSet<FetchOutcome>) {
    tasks.abort_all();
    while tasks.join_next().await.is_some() {}
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

type FetchOutcome = (u32, Result<u64, ai_task_support::FetchError>);

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut pending = ids.into_iter();
    let mut tasks: JoinSet<FetchOutcome> = JoinSet::new();
    let mut sum: u64 = 0;

    for _ in 0..MAX_IN_FLIGHT {
        match pending.next() {
            Some(id) => spawn_fetch(&mut tasks, &fetch, id),
            None => break,
        }
    }

    while !tasks.is_empty() {
        match tasks.join_next().await {
            Some(Ok((id, Ok(value)))) => {
                sum = sum.wrapping_add(value);
            }
            Some(Ok((id, Err(_fetch_error)))) => {
                tasks.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Some(Err(_join_error)) => {
                tasks.abort_all();
                return Err(SolveError::Cancelled);
            }
            None => break,
        }

        if let Some(id) = pending.next() {
            spawn_fetch(&mut tasks, &fetch, id);
        }
    }

    Ok(sum)
}

fn spawn_fetch(tasks: &mut JoinSet<FetchOutcome>, fetch: &Fetcher, id: u32) {
    let fetch = fetch.clone();
    let _ = tasks.spawn(async move {
        let outcome = fetch.fetch(id).await;
        (id, outcome)
    });
}

