use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const LIMIT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(outcome) => outcome,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<(u32, Result<u64, ()>)> = JoinSet::new();
    let mut pending = ids.into_iter();
    let mut sum: u64 = 0;

    loop {
        while let Some(joined) = set.try_join_next() {
            match joined {
                Ok((id, Ok(value))) => sum += value,
                Ok((id, Err(()))) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id });
                }
                Err(_) => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        while set.len() < LIMIT {
            match pending.next() {
                Some(id) => {
                    let fetcher = fetch.clone();
                    set.spawn(async move { (id, fetcher.fetch(id).await.map_err(|_| ())) });
                }
                None => break,
            }
        }

        if set.is_empty() {
            return Ok(sum);
        }

        match set.join_next().await {
            Some(Ok((id, Ok(value)))) => sum += value,
            Some(Ok((id, Err(())))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Some(Err(_)) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
            None => {}
        }
    }
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    use lgwks_bot::rt::task::join_all_bounded;
    use lgwks_bot::rt::time::{timeout, Instant};

    let work = async move {
        let deadline_at = Instant::now() + deadline;
        let mut sum: u64 = 0;
        let mut start = 0usize;

        while start < ids.len() {
            if Instant::now() >= deadline_at {
                return Err(SolveError::Deadline);
            }

            let end = (start + 4).min(ids.len());
            let futures = ids[start..end].iter().map(|&id| {
                let fetch = fetch.clone();
                async move {
                    let value = fetch.fetch(id).await.map_err(|_| ());
                    (id, value)
                }
            });

            let results = join_all_bounded(4, futures).await;
            for (id, value) in results {
                match value {
                    Ok(v) => sum += v,
                    Err(()) => return Err(SolveError::Fetch { id }),
                }
            }

            start = end;
        }

        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::{join_all_bounded, JoinSet};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, drive(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn drive(stage: Stage) -> Result<Published, PipelineError> {
    let mut fetches = JoinSet::new();
    let mut fetch_handles = Vec::new();
    for (idx, name) in [StageName::FetchA, StageName::FetchB]
        .into_iter()
        .enumerate()
    {
        let stage = stage.clone();
        fetch_handles.push(fetches.spawn(async move { (idx, stage.run(name).await) }));
    }

    while let Some(joined) = fetches.join_next().await {
        match joined {
            Ok((_, Ok(_))) => {}
            Ok((idx, Err(_))) => {
                let name = if idx == 0 {
                    StageName::FetchA
                } else {
                    StageName::FetchB
                };
                return Err(PipelineError::Stage { name });
            }
            Err(_) => return Err(PipelineError::Cancelled),
        }
    }

    if run_stage(stage.clone(), StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    let artifact = match run_stage(stage, StageName::Publish).await {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Publish,
            })
        }
    };

    Ok(Published::from(artifact))
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    let mut results =
        join_all_bounded(1, std::iter::once(async move { stage.run(name).await })).await;
    results
        .pop()
        .expect("join_all_bounded yields one result per future")
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout_at, Instant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let deadline_at = Instant::now() + deadline;

    let mut fetches: JoinSet<(StageName, bool)> = JoinSet::new();

    {
        let stage = stage.clone();
        fetches.spawn(async move {
            let succeeded = stage.run(StageName::FetchA).await.is_ok();
            (StageName::FetchA, succeeded)
        });
    }

    {
        let stage = stage.clone();
        fetches.spawn(async move {
            let succeeded = stage.run(StageName::FetchB).await.is_ok();
            (StageName::FetchB, succeeded)
        });
    }

    let mut fetch_a_seen = false;
    let mut fetch_b_seen = false;
    let mut failed: Option<StageName> = None;

    let drain = async {
        while let Some(joined) = fetches.join_next().await {
            let (name, succeeded) = match joined {
                Ok(pair) => pair,
                Err(_) => continue,
            };

            if !succeeded {
                failed = Some(name);
                break;
            }

            match name {
                StageName::FetchA => fetch_a_seen = true,
                StageName::FetchB => fetch_b_seen = true,
                _ => {}
            }
        }
    };

    let outcome = timeout_at(deadline_at, drain).await;
    fetches.abort_all();

    if outcome.is_err() {
        return Err(PipelineError::Deadline);
    }

    if let Some(name) = failed {
        return Err(PipelineError::Stage { name });
    }

    if !fetch_a_seen {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }

    if !fetch_b_seen {
        return Err(PipelineError::Stage {
            name: StageName::FetchB,
        });
    }

    let combined = timeout_at(deadline_at, stage.run(StageName::Combine)).await;
    let combined = match combined {
        Ok(result) => result,
        Err(_) => return Err(PipelineError::Deadline),
    };
    if combined.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    let published = timeout_at(deadline_at, stage.run(StageName::Publish)).await;
    let published = match published {
        Ok(result) => result,
        Err(_) => return Err(PipelineError::Deadline),
    };
    let published = match published {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Publish,
            })
        }
    };

    Ok(Published::from(published))
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let (_a, _b) = fetch_both(&stage).await?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

#[derive(Clone, Copy)]
enum Fetch {
    A,
    B,
}

impl Fetch {
    fn name(self) -> StageName {
        match self {
            Fetch::A => StageName::FetchA,
            Fetch::B => StageName::FetchB,
        }
    }
}

type Fetched = (Fetch, Result<Artifact, StageError>);

async fn fetch_both(stage: &Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut tasks: JoinSet<Fetched> = JoinSet::new();

    {
        let runner = stage.clone();
        let _ = tasks.spawn(async move { (Fetch::A, runner.run(StageName::FetchA).await) });
    }
    {
        let runner = stage.clone();
        let _ = tasks.spawn(async move { (Fetch::B, runner.run(StageName::FetchB).await) });
    }

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok((Fetch::A, Ok(artifact))) => a = Some(artifact),
            Ok((Fetch::B, Ok(artifact))) => b = Some(artifact),
            Ok((tag, Err(_))) => {
                drain(&mut tasks).await;
                return Err(PipelineError::Stage { name: tag.name() });
            }
            Err(_) => {
                drain(&mut tasks).await;
                return Err(PipelineError::Cancelled);
            }
        }
    }

    match (a, b) {
        (Some(a), Some(b)) => Ok((a, b)),
        _ => Err(PipelineError::Cancelled),
    }
}

async fn drain(tasks: &mut JoinSet<Fetched>) {
    tasks.abort_all();
    while tasks.join_next().await.is_some() {}
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn fetch(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    stage.run(name).await
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let fetches = [
        fetch(stage.clone(), StageName::FetchA),
        fetch(stage.clone(), StageName::FetchB),
    ];

    let mut results = join_all_bounded(2, fetches).await;

    let fetch_b = match results.pop() {
        Some(result) => result,
        None => return Err(PipelineError::Cancelled),
    };
    let fetch_a = match results.pop() {
        Some(result) => result,
        None => return Err(PipelineError::Cancelled),
    };

    if let Err(_error) = fetch_a {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }
    if let Err(_error) = fetch_b {
        return Err(PipelineError::Stage {
            name: StageName::FetchB,
        });
    }

    match stage.run(StageName::Combine).await {
        Ok(_combined) => {}
        Err(_error) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            })
        }
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_error) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    run_fetches(&stage).await?;

    let mut combine: JoinSet<Result<(), StageName>> = JoinSet::new();
    let s = stage.clone();
    combine.spawn(async move {
        s.run(StageName::Combine)
            .await
            .map(|_| ())
            .map_err(|_| StageName::Combine)
    });
    match combine.join_next().await {
        Some(Ok(Ok(()))) => {}
        Some(Ok(Err(name))) => return Err(PipelineError::Stage { name }),
        _ => return Err(PipelineError::Cancelled),
    }

    let mut publish: JoinSet<Result<Published, StageName>> = JoinSet::new();
    let s = stage.clone();
    publish.spawn(async move {
        s.run(StageName::Publish)
            .await
            .map(|artifact| Published::from(artifact))
            .map_err(|_| StageName::Publish)
    });
    match publish.join_next().await {
        Some(Ok(Ok(published))) => Ok(published),
        Some(Ok(Err(name))) => Err(PipelineError::Stage { name }),
        _ => Err(PipelineError::Cancelled),
    }
}

async fn run_fetches(stage: &Stage) -> Result<(), PipelineError> {
    let mut set: JoinSet<Result<(), StageName>> = JoinSet::new();

    let a = Stage::clone(stage);
    set.spawn(async move {
        a.run(StageName::FetchA)
            .await
            .map(|_| ())
            .map_err(|_| StageName::FetchA)
    });

    let b = Stage::clone(stage);
    set.spawn(async move {
        b.run(StageName::FetchB)
            .await
            .map(|_| ())
            .map_err(|_| StageName::FetchB)
    });

    while let Some(outcome) = set.join_next().await {
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(name)) => return Err(PipelineError::Stage { name }),
            Err(_) => return Err(PipelineError::Cancelled),
        }
    }

    Ok(())
}

use std::future::{poll_fn, Future};
use std::task::Poll;
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let (fetch_a, fetch_b) =
        join2(stage.run(StageName::FetchA), stage.run(StageName::FetchB)).await;

    fetch_a.map_err(|_| PipelineError::Stage { name: StageName::FetchA })?;
    fetch_b.map_err(|_| PipelineError::Stage { name: StageName::FetchB })?;

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

async fn join2<A, B>(fa: impl Future<Output = A>, fb: impl Future<Output = B>) -> (A, B) {
    let mut fa = Box::pin(fa);
    let mut fb = Box::pin(fb);
    let mut ra: Option<A> = None;
    let mut rb: Option<B> = None;

    poll_fn(|cx| {
        if ra.is_none() {
            if let Poll::Ready(value) = fa.as_mut().poll(cx) {
                ra = Some(value);
            }
        }
        if rb.is_none() {
            if let Poll::Ready(value) = fb.as_mut().poll(cx) {
                rb = Some(value);
            }
        }

        if ra.is_some() && rb.is_some() {
            return Poll::Ready((ra.take().unwrap(), rb.take().unwrap()));
        }
        Poll::Pending
    })
    .await
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn fetch(stage: Stage, name: StageName, label: StageName) -> Result<(), StageName> {
    match stage.run(name).await {
        Ok(_) => Ok(()),
        Err(_) => Err(label),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let futures = [
        fetch(stage.clone(), StageName::FetchA, StageName::FetchA),
        fetch(stage.clone(), StageName::FetchB, StageName::FetchB),
    ];
    let mut results = join_all_bounded(2, futures).await.into_iter();

    if let Some(Err(name)) = results.next() {
        return Err(PipelineError::Stage { name });
    }
    if let Some(Err(name)) = results.next() {
        return Err(PipelineError::Stage { name });
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

