use std::future::poll_fn;
use std::task::Poll;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    stage.run(name).await
}

async fn fetch_both(stage: Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut fetch_a = Box::pin(run_stage(stage.clone(), StageName::FetchA));
    let mut fetch_b = Box::pin(run_stage(stage, StageName::FetchB));

    let mut a_done = false;
    let mut b_done = false;
    let mut a_failed = false;
    let mut b_failed = false;
    let mut a_value: Option<Artifact> = None;
    let mut b_value: Option<Artifact> = None;

    let pair: Result<(Artifact, Artifact), PipelineError> = poll_fn(move |cx| {
        if !a_done {
            if let Poll::Ready(result) = fetch_a.as_mut().poll(cx) {
                a_done = true;
                match result {
                    Ok(value) => a_value = Some(value),
                    Err(_) => a_failed = true,
                }
            }
        }

        if !b_done {
            if let Poll::Ready(result) = fetch_b.as_mut().poll(cx) {
                b_done = true;
                match result {
                    Ok(value) => b_value = Some(value),
                    Err(_) => b_failed = true,
                }
            }
        }

        if a_failed {
            return Poll::Ready(Err(PipelineError::Stage {
                name: StageName::FetchA,
            }));
        }
        if b_failed {
            return Poll::Ready(Err(PipelineError::Stage {
                name: StageName::FetchB,
            }));
        }
        if a_done && b_done {
            Poll::Ready(Ok((a_value.take().unwrap(), b_value.take().unwrap())))
        } else {
            Poll::Pending
        }
    })
    .await;

    pair
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let _ = fetch_both(stage.clone()).await?;

    match stage.run(StageName::Combine).await {
        Ok(_) => {}
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            })
        }
    }

    match stage.run(StageName::Publish).await {
        Ok(published) => Ok(Published::from(published)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

enum Fetched {
    A(Artifact),
    B(Artifact),
    Failed(StageName),
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let mut set: JoinSet<Fetched> = JoinSet::new();

    let fetch_a = stage.clone();
    set.spawn(async move {
        match fetch_a.run(StageName::FetchA).await {
            Ok(artifact) => Fetched::A(artifact),
            Err(_) => Fetched::Failed(StageName::FetchA),
        }
    });

    let fetch_b = stage.clone();
    set.spawn(async move {
        match fetch_b.run(StageName::FetchB).await {
            Ok(artifact) => Fetched::B(artifact),
            Err(_) => Fetched::Failed(StageName::FetchB),
        }
    });

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while let Some(outcome) = set.join_next().await {
        match outcome {
            Ok(Fetched::A(artifact)) => a = Some(artifact),
            Ok(Fetched::B(artifact)) => b = Some(artifact),
            Ok(Fetched::Failed(name)) => {
                set.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Err(_) => {
                set.abort_all();
                return Err(PipelineError::Cancelled);
            }
        }
    }

    if a.is_none() || b.is_none() {
        return Err(PipelineError::Cancelled);
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

use std::time::Duration;

use lgwks_bot::script::{FanOut, FanOutError};

/// The ways a fan-out over `fetch` can end without producing a total.
#[derive(Debug)]
pub enum SolveError {
    /// One of the fetches failed; `id` names the item that failed.
    Fetch { id: u32 },
    /// The overall deadline passed before every fetch had answered.
    Deadline,
    /// The work was cancelled.
    Cancelled,
}

/// Fetch every id, at most four at a time, and sum the values.
///
/// The fan-out is owned by this future: dropping it drops every running
/// `fetch`, so nothing outlives the call. The first failure stops the run and
/// starts no further fetch, and the deadline does the same on expiry.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let outcome = FanOut::new(ids)
        .at_most(4)
        .within(deadline)
        .run(|id| {
            let fetch = fetch.clone();
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => Err(SolveError::Fetch { id }),
                }
            }
        })
        .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error, .. }) => match error {
            SolveError::Fetch { id } => Err(SolveError::Fetch { id }),
            SolveError::Deadline => Err(SolveError::Deadline),
            SolveError::Cancelled => Err(SolveError::Cancelled),
        },
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(err)) => {
            if err.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
        Err(_) => Err(SolveError::Deadline),
    }
}

//! Bounded, ordered, fail-fast aggregation of fetched values.

use std::time::Duration;

use ai_task_support::script::{FanOut, FanOutError};

/// Why an aggregation run did not produce a sum.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` for this id failed.
    Fetch { id: u32 },
    /// The overall deadline passed.
    Deadline,
    /// The run was cancelled or otherwise aborted by the flow.
    Cancelled,
}

/// Fetch every id, with at most four fetches in flight, and sum the values.
///
/// Resolves with the sum on success, or with the first observed failure, the
/// deadline, or cancellation. Dropping the returned future drops every running
/// fetch, and no new fetch starts after a failure has been observed.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let values = FanOut::new(ids)
        .at_most(4)
        .within(deadline)
        .run(move |id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|_| SolveError::Fetch { id }) }
        })
        .await;

    match values {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error, .. }) => Err(error),
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(_)) => Err(SolveError::Cancelled),
    }
}

//! Bounded, fail-fast aggregation of `fetch` results.
//!
//! Every fan-out body is owned by the `solve` future: the concurrency ceiling
//! is `4`, the first failure stops the run, the deadline is absolute, and
//! dropping the future drops every in-flight `fetch`.

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FanOut, FanOutError};

/// Ceiling on simultaneously running `fetch` calls.
const CONCURRENCY: usize = 4;

/// Every way `solve` can fail.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` returned an error; `id` is the item that failed.
    Fetch { id: u32 },
    /// The overall deadline passed first.
    Deadline,
    /// The fan-out was cancelled before every item completed.
    Cancelled,
}

/// Sum the values returned by `fetch` for every `id`, at most [`CONCURRENCY`]
/// calls at a time, stopping at the first failure or at `deadline`.
pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    // The body carries the failing id as the error payload, so no separate
    // index-to-id lookup is needed and the error type stays trivially `Send`.
    let outcome = FanOut::new(ids)
        .at_most(CONCURRENCY)
        .within(deadline)
        .run(move |id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|_| id) }
        })
        .await;

    match outcome {
        // Fail-fast: no body was left running and none was started afterwards.
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error, .. }) => Err(SolveError::Fetch { id: error }),
        // The deadline won the race against the remaining bodies.
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        // `at_most(4)` is in range, so a flow error can only be the deadline or
        // a cancellation tearing the remaining bodies down.
        Err(FanOutError::Flow(flow)) => {
            if flow.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
        // `FanOutError` is `#[non_exhaustive]`: any other variant means the
        // fan-out was torn down by the host rather than by an item.
        Err(_) => Err(SolveError::Cancelled),
    }
}

//! Bounded, fail-fast aggregation of `Fetcher` results with an overall deadline.
//!
//! All concurrency is delegated to `lgwks_bot::script::FanOut`, which is
//! owning: dropping the `solve` future drops every body it started, so no
//! `fetch` call can outlive this call. Every error path is matched explicitly
//! here rather than being collapsed into an implicit default.

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FanOut, FanOutError, FlowError};

/// Number of `fetch` calls allowed in flight at once.
const MAX_IN_FLIGHT: usize = 4;

/// Why `solve` could not produce a sum.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` failed; `id` is the item that failed.
    Fetch { id: u32 },
    /// The overall `deadline` passed.
    Deadline,
    /// The work was cancelled.
    Cancelled,
}

/// Sum the values `fetch` returns for every id in `ids`.
///
/// - At most 4 fetches are in flight at any time.
/// - The first observed failure stops the run, starts no further fetch, drops
///   every running fetch, and is reported as `SolveError::Fetch { id }`.
/// - If `deadline` passes, no further fetch is started, running fetches are
///   dropped, and the result is `SolveError::Deadline`.
/// - Dropping the returned future drops every fetch it owns.
/// - An empty `ids` resolves with `Ok(0)`.
pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let outcome = FanOut::new(ids.clone())
        .at_most(MAX_IN_FLIGHT)
        .within(deadline)
        .run(move |id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await }
        })
        .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        // The first failing item's position is reported in input order.
        Err(FanOutError::Item { index, .. }) => {
            let id = ids.get(index).copied().unwrap_or(0);
            Err(SolveError::Fetch { id })
        }
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(flow)) => match flow {
            FlowError::TimedOut { .. } => Err(SolveError::Deadline),
            FlowError::Cancelled { .. } => Err(SolveError::Cancelled),
            // Any other flow-level stop is a cancellation of the owned work:
            // no other `SolveError` variant describes it.
            _ => Err(SolveError::Cancelled),
        },
        // `FanOutError` is `#[non_exhaustive]`; any further variant is treated
        // as a stop of the owned work rather than a value.
        Err(_) => Err(SolveError::Cancelled),
    }
}

