use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FanOut, FanOutError};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let outcome = FanOut::new(ids.into_iter())
        .at_most(MAX_IN_FLIGHT)
        .within(deadline)
        .run(|id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|_| id) }
        })
        .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error: id, .. }) => Err(SolveError::Fetch { id }),
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(_)) => Err(SolveError::Cancelled),
        Err(_) => Err(SolveError::Cancelled),
    }
}

use std::time::Duration;

use lgwks_bot::script::{FanOut, FanOutError};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let outcome = FanOut::new(ids)
        .at_most(MAX_IN_FLIGHT)
        .within(deadline)
        .run(|id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|_| id) }
        })
        .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error: id, .. }) => Err(SolveError::Fetch { id }),
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(flow)) => {
            if flow.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FanOut, FanOutError};

/// At most this many `fetch` calls may be in flight at once.
const CONCURRENCY: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Sum every fetched value, bounded to `CONCURRENCY` bodies at a time, with
/// one deadline for the whole fan-out.
///
/// The fan-out owns every body it starts: a failing item starts no further
/// item and drops the bodies still running, the deadline drops them all, and
/// dropping this future drops them too, so no fetch outlives the call.
pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let outcome = FanOut::new(ids)
        .at_most(CONCURRENCY)
        .within(deadline)
        .run(|id| {
            let fetch = fetch.clone();
            // The body's own error carries the failing id, so the reported
            // failure survives the fan-out consuming the input order.
            async move { fetch.fetch(id).await.map_err(|_| id) }
        })
        .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FanOutError::Item { error, .. }) => Err(SolveError::Fetch { id: error }),
        Err(FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FanOutError::Flow(flow)) if flow.is_cancelled() => Err(SolveError::Cancelled),
        // `FanOutError` is `#[non_exhaustive]`; a flow error we cannot classify
        // is treated as the deadline stopping the fan-out.
        Err(_) => Err(SolveError::Deadline),
    }
}

//! A four-stage pipeline: two independent fetches, a join, then a publish.
//!
//! Every stage future is polled directly from the caller's task and lives in
//! `solve`'s own frame, so dropping the returned future drops all in-flight
//! stages at once: nothing outlives the call.

use std::future::{poll_fn, Future};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

/// Every way the pipeline can stop.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error; `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline passed before the pipeline finished.
    Deadline,
    /// The caller stopped the pipeline.
    Cancelled,
}

/// The one overall deadline, shared by every stage of the run.
struct Budget {
    start: Instant,
    limit: Duration,
    spent: Arc<AtomicBool>,
    waker: Arc<Mutex<Option<Waker>>>,
}

impl Budget {
    fn new(limit: Duration) -> Self {
        let start = Instant::now();
        let spent = Arc::new(AtomicBool::new(false));
        let waker: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));

        // The clock thread exists only to wake the task once the budget is
        // spent: a stage that parks must not pin the deadline check.
        let flag = Arc::clone(&spent);
        let slot = Arc::clone(&waker);
        let _ = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || {
                let remaining = limit.checked_sub(start.elapsed()).unwrap_or(Duration::ZERO);
                std::thread::sleep(remaining);
                flag.store(true, Ordering::SeqCst);
                let woken = slot.lock().unwrap_or_else(|e| e.into_inner()).take();
                if let Some(waker) = woken {
                    waker.wake();
                }
            });

        Budget { start, limit, spent, waker }
    }

    fn expired(&self) -> bool {
        self.spent.load(Ordering::SeqCst) || self.start.elapsed() >= self.limit
    }

    /// Remember who to wake when the budget runs out.
    fn arm(&self, waker: &Waker) {
        let mut slot = self.waker.lock().unwrap_or_else(|e| e.into_inner());
        let held = match slot.as_ref() {
            Some(held) => held.will_wake(waker),
            None => false,
        };
        if !held {
            *slot = Some(waker.clone());
        }
    }
}

/// How one stage ended.
enum Step<T> {
    Value(T),
    Failed,
    Late,
}

/// How the pair of independent fetches ended.
enum Pair<T> {
    Both(T, T),
    Failed(StageName),
    Late,
}

/// Poll one stage future until it answers or the budget is spent. The future is
/// owned by this frame, so dropping the caller drops it.
async fn step<T, E, F>(future: F, budget: &Budget) -> Step<T>
where
    F: Future<Output = Result<T, E>>,
{
    let mut future = Box::pin(future);
    poll_fn(|cx| {
        if budget.expired() {
            return Poll::Ready(Step::Late);
        }
        budget.arm(cx.waker());
        match future.as_mut().poll(cx) {
            Poll::Ready(Ok(value)) => Poll::Ready(Step::Value(value)),
            Poll::Ready(Err(_error)) => Poll::Ready(Step::Failed),
            Poll::Pending => Poll::Pending,
        }
    })
    .await
}

/// Run two independent stage futures together under the one budget. The first
/// failure wins and stops the other immediately; both futures are dropped when
/// this function returns either way.
async fn both<T, E, F, G>(first: F, second: G, budget: &Budget) -> Pair<T>
where
    F: Future<Output = Result<T, E>>,
    G: Future<Output = Result<T, E>>,
{
    let mut first = Box::pin(first);
    let mut second = Box::pin(second);
    let mut left: Option<T> = None;
    let mut right: Option<T> = None;

    poll_fn(|cx| {
        if left.is_some() && right.is_some() {
            let a = left.take().expect("left is set");
            let b = right.take().expect("right is set");
            return Poll::Ready(Pair::Both(a, b));
        }
        if budget.expired() {
            return Poll::Ready(Pair::Late);
        }
        budget.arm(cx.waker());
        if left.is_none() {
            if let Poll::Ready(result) = first.as_mut().poll(cx) {
                match result {
                    Ok(value) => left = Some(value),
                    Err(_error) => return Poll::Ready(Pair::Failed(StageName::FetchA)),
                }
            }
        }
        if right.is_none() {
            if let Poll::Ready(result) = second.as_mut().poll(cx) {
                match result {
                    Ok(value) => right = Some(value),
                    Err(_error) => return Poll::Ready(Pair::Failed(StageName::FetchB)),
                }
            }
        }
        if left.is_some() && right.is_some() {
            let a = left.take().expect("left is set");
            let b = right.take().expect("right is set");
            return Poll::Ready(Pair::Both(a, b));
        }
        Poll::Pending
    })
    .await
}

/// Run the pipeline under one overall deadline.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let budget = Budget::new(deadline);

    let (_a, _b) = match both(
        stage.run(StageName::FetchA),
        stage.run(StageName::FetchB),
        &budget,
    )
    .await
    {
        Pair::Both(a, b) => (a, b),
        Pair::Failed(name) => return Err(PipelineError::Stage { name }),
        Pair::Late => return Err(PipelineError::Deadline),
    };

    match step(stage.run(StageName::Combine), &budget).await {
        Step::Value(_combined) => {}
        Step::Failed => return Err(PipelineError::Stage { name: StageName::Combine }),
        Step::Late => return Err(PipelineError::Deadline),
    }

    match step(stage.run(StageName::Publish), &budget).await {
        Step::Value(artifact) => Ok(Published::from(artifact)),
        Step::Failed => Err(PipelineError::Stage { name: StageName::Publish }),
        Step::Late => Err(PipelineError::Deadline),
    }
}

//! A four-stage pipeline: two independent fetches, a combine, and a publish.
//!
//! The whole run shares one overall `deadline`, and the returned future owns
//! every stage body, so dropping it stops the work it started.

use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

/// Everything that can stop a pipeline run.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error; `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline passed; no later stage was run.
    Deadline,
    /// The run was cancelled.
    Cancelled,
}

/// Run `fetch_a` and `fetch_b`, then `combine`, then `publish`.
///
/// `fetch_a` and `fetch_b` run concurrently and share the overall deadline.
/// `combine` only runs if both fetches succeeded, and `publish` only if
/// `combine` succeeded. Dropping the future drops every stage still running.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let start = Instant::now();
    let stage = &stage;

    // `fetch_a` and `fetch_b` are independent: one bounded fan-out, one clock.
    let fetched = match FanOut::new([StageName::FetchA, StageName::FetchB])
        .at_most(2)
        .within(deadline)
        .run(|name| stage.run(name))
        .await
    {
        Ok(artifacts) => artifacts,
        Err(FanOutError::Item { index, .. }) => {
            return Err(PipelineError::Stage { name: fetch_name(index) })
        }
        Err(FanOutError::TimedOut { .. }) => return Err(PipelineError::Deadline),
        Err(FanOutError::Flow(flow)) => {
            return Err(if flow.is_cancelled() {
                PipelineError::Cancelled
            } else {
                PipelineError::Deadline
            })
        }
        Err(_) => return Err(PipelineError::Deadline),
    };
    drop(fetched);

    // `combine` needs both fetches, `publish` needs `combine`: strictly
    // sequential, each racing the deadline that is left.
    let combined = run_one(stage, StageName::Combine, remaining(deadline, start)).await?;
    drop(combined);

    let published = run_one(stage, StageName::Publish, remaining(deadline, start)).await?;

    Ok(Published::from(published))
}

/// Run a single stage under the slice of the overall deadline still left.
async fn run_one(
    stage: &Stage,
    name: StageName,
    left: Duration,
) -> Result<ai_task_support::Artifact, PipelineError> {
    match timeout(left, stage.run(name)).await {
        Ok(Ok(artifact)) => Ok(artifact),
        Ok(Err(_error)) => Err(PipelineError::Stage { name }),
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

/// The stage named by a fetcher's position in the fan-out.
fn fetch_name(index: usize) -> StageName {
    match index {
        0 => StageName::FetchA,
        _ => StageName::FetchB,
    }
}

/// The part of the overall deadline not yet spent.
fn remaining(deadline: Duration, start: Instant) -> Duration {
    deadline.saturating_sub(start.elapsed())
}

//! `pipeline` — a std-only fan-out/fan-in pipeline over `ai_task_support`.
//!
//! Two facts shape this implementation:
//!
//! * Nothing is ever detached. Every stage future lives inside the future
//!   returned by [`solve`], so dropping that future drops every stage that was
//!   still in flight. There are no threads of our own, no background tasks and
//!   nothing left running after a cancellation.
//! * Every fallible call is handled explicitly. A stage error is turned into
//!   [`PipelineError::Stage`] by the caller that knows which stage it started;
//!   the shared driver only reports *which slot* failed. The deadline is
//!   checked by the driver before every poll, so on expiry it drops the
//!   in-flight stage futures before returning, and no later stage is started.

use std::fmt;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

/// Every way this pipeline can end badly.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error. `name` is the stage that was running.
    Stage { name: StageName },
    /// The overall deadline elapsed; nothing later was started.
    Deadline,
    /// The caller cancelled the run. Reserved for a cancellation source.
    Cancelled,
}

impl fmt::Display for PipelineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PipelineError::Stage { name } => write!(f, "stage {name:?} failed"),
            PipelineError::Deadline => f.write_str("deadline exceeded"),
            PipelineError::Cancelled => f.write_str("cancelled"),
        }
    }
}

impl std::error::Error for PipelineError {}

/// How long a stage may sit `Pending` before we re-poll it anyway. A wakeup
/// short-circuits this; it only bounds the damage of a stage that goes quiet.
const POLL_GRANULARITY: Duration = Duration::from_millis(1);

/// Waker side of the polling loop: remembers a wakeup that arrived while we
/// were busy so it cannot be lost across a park.
struct Signal {
    woken: AtomicBool,
}

impl Signal {
    fn new() -> Signal {
        Signal {
            woken: AtomicBool::new(false),
        }
    }

    /// Returns `true` (clearing the flag) if a wakeup is pending.
    fn take(&self) -> bool {
        self.woken.swap(false, Ordering::SeqCst)
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.woken.store(true, Ordering::SeqCst);
        std::thread::current().unpark();
    }
}

/// One overall budget, started when `solve` is entered.
struct Clock {
    start: Instant,
    limit: Duration,
}

impl Clock {
    fn new(limit: Duration) -> Clock {
        Clock {
            start: Instant::now(),
            limit,
        }
    }

    fn expired(&self) -> bool {
        self.start.elapsed() >= self.limit
    }
}

/// A stage future plus, once it has finished, the value it produced.
struct Slot<T, F> {
    fut: Option<Pin<Box<F>>>,
    value: Option<T>,
}

impl<T, F> Slot<T, F> {
    fn new(fut: Pin<Box<F>>) -> Slot<T, F> {
        Slot {
            fut: Some(fut),
            value: None,
        }
    }

    fn into_value(self) -> Option<T> {
        self.value
    }
}

/// How a drive ended. `Failed` carries the index of the failing slot.
enum Drive {
    Done,
    Deadline,
    Failed(usize),
}

/// Polls every slot to completion, fail-fast, against the shared deadline.
///
/// Stops at the first slot that errors (dropping the others), returns
/// [`Drive::Deadline`] as soon as the budget is gone, and drops every in-flight
/// stage future before returning in either case. Returning here — rather than
/// cancelling a task we do not own — is what guarantees that nothing outlives
/// the future being dropped.
async fn drive<T, E, F>(slots: &mut [Slot<T, F>], clock: &Clock, signal: &Arc<Signal>) -> Drive
where
    F: Future<Output = Result<T, E>>,
{
    let waker = Waker::from(Arc::clone(signal));
    let mut cx = Context::from_waker(&waker);

    loop {
        if clock.expired() {
            for slot in slots.iter_mut() {
                slot.fut = None;
            }
            return Drive::Deadline;
        }

        let mut pending = false;
        let mut failure: Option<usize> = None;

        for (index, slot) in slots.iter_mut().enumerate() {
            if slot.value.is_some() {
                continue;
            }
            let polled = match slot.fut.as_mut() {
                Some(fut) => fut.as_mut().poll(&mut cx),
                None => continue,
            };
            match polled {
                Poll::Pending => pending = true,
                Poll::Ready(Ok(value)) => {
                    slot.value = Some(value);
                    slot.fut = None;
                }
                Poll::Ready(Err(_)) => {
                    failure = Some(index);
                    break;
                }
            }
        }

        if let Some(index) = failure {
            for slot in slots.iter_mut() {
                slot.fut = None;
            }
            return Drive::Failed(index);
        }

        if !pending {
            return Drive::Done;
        }

        if !signal.take() {
            std::thread::park_timeout(POLL_GRANULARITY);
        }
    }
}

/// Runs the pipeline: `fetch_a` and `fetch_b` concurrently, then `combine`,
/// then `publish`, all under one deadline.
///
/// * A `fetch_*` failure stops everything and is reported by name.
/// * `combine` is only started once both fetches succeeded.
/// * Exceeding the deadline resolves with [`PipelineError::Deadline`] and
///   starts no later stage.
/// * Dropping the returned future drops every stage still in flight.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let clock = Clock::new(deadline);
    let signal = Arc::new(Signal::new());

    let mut fetches = [
        Slot::new(Box::pin(stage.run(StageName::FetchA))),
        Slot::new(Box::pin(stage.run(StageName::FetchB))),
    ];
    match drive(&mut fetches, &clock, &signal).await {
        Drive::Done => {}
        Drive::Deadline => return Err(PipelineError::Deadline),
        Drive::Failed(0) => return Err(PipelineError::Stage { name: StageName::FetchA }),
        Drive::Failed(_) => return Err(PipelineError::Stage { name: StageName::FetchB }),
    }
    drop(fetches);

    let mut combine = [Slot::new(Box::pin(stage.run(StageName::Combine)))];
    match drive(&mut combine, &clock, &signal).await {
        Drive::Done => {}
        Drive::Deadline => return Err(PipelineError::Deadline),
        Drive::Failed(_) => return Err(PipelineError::Stage { name: StageName::Combine }),
    }
    drop(combine);

    let publish = [Slot::new(Box::pin(stage.run(StageName::Publish)))];
    let mut publish = publish;
    match drive(&mut publish, &clock, &signal).await {
        Drive::Done => {}
        Drive::Deadline => return Err(PipelineError::Deadline),
        Drive::Failed(_) => return Err(PipelineError::Stage { name: StageName::Publish }),
    }

    match publish.into_iter().next().and_then(|slot| slot.into_value()) {
        Some(artifact) => Ok(Published::from(artifact)),
        // Unreachable: `Drive::Done` means every slot carries a value.
        None => Err(PipelineError::Deadline),
    }
}

//! A two-legged fetch pipeline: `fetch_a` and `fetch_b` run concurrently under
//! a single overall deadline, `combine` needs both legs, `publish` needs the
//! combined artifact.
//!
//! Cleanup discipline: every stage future this module starts is owned by
//! something the caller's future owns. The concurrent fetch legs are owned by
//! the fan-out, and each later stage is owned by the timeout race that guards
//! it. Dropping the future returned by `solve` therefore drops every running
//! stage rather than leaving it live.

use std::future::Future;
use std::pin::Pin;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

/// Everything that can go wrong while draining the pipeline.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage reported failure; `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline elapsed; no later stage was started.
    Deadline,
    /// The pipeline was cancelled rather than failing or timing out.
    Cancelled,
}

/// The two independent legs, in the order the fan-out reports their values.
const FETCHES: [StageName; 2] = [StageName::FetchA, StageName::FetchB];

/// A single `Stage::run` call, erased so the fan-out body has one future type.
/// The clone of the stage is owned by the future itself, so nothing borrows a
/// temporary from the closure's stack frame.
type BoxedStageRun = Pin<Box<dyn Future<Output = Result<Artifact, ai_task_support::StageError>> + Send>>;

/// Budget left against the one overall `deadline`, or `None` once it is spent.
fn remaining(start: Instant, deadline: Duration) -> Option<Duration> {
    deadline
        .checked_sub(start.elapsed())
        .filter(|left| !left.is_zero())
}

/// Run one stage under what is left of the overall deadline.
///
/// On timeout the raced future is dropped, so the stage does not outlive this
/// call; on failure the exact stage that failed is named.
async fn run_stage(
    stage: &Stage,
    name: StageName,
    start: Instant,
    deadline: Duration,
) -> Result<Artifact, PipelineError> {
    let budget = remaining(start, deadline).ok_or(PipelineError::Deadline)?;
    timeout(budget, stage.run(name))
        .await
        .map_err(|_| PipelineError::Deadline)?
        .map_err(|_| PipelineError::Stage { name })
}

/// Drain the pipeline: fetch both legs concurrently, then combine, then publish.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let start = Instant::now();

    // Both legs start together under one deadline. The fan-out is fail-fast and
    // owning, so a failing leg stops the other, the reported index names the leg
    // that failed, and dropping `solve` drops every leg still in flight.
    let legs = stage.clone();
    let fetched = FanOut::new(FETCHES)
        .at_most(2)
        .within(deadline)
        .run(move |name| -> BoxedStageRun {
            let owner = legs.clone();
            Box::pin(async move { owner.run(name).await })
        })
        .await
        .map_err(|err| match err {
            FanOutError::Item { index, .. } => PipelineError::Stage {
                name: FETCHES
                    .get(index)
                    .copied()
                    .unwrap_or(StageName::FetchA),
            },
            FanOutError::TimedOut { .. } => PipelineError::Deadline,
            FanOutError::Flow(flow) => {
                if flow.is_cancelled() {
                    PipelineError::Cancelled
                } else {
                    PipelineError::Deadline
                }
            }
            _ => PipelineError::Deadline,
        })?;

    // Both legs succeeded. Their artifacts are the stage's own record, so they
    // are kept alive here and dropped only once the pipeline is finished.
    let _fetched = fetched;

    // `stage` itself was never moved into the fan-out, only a clone was.
    let _combined = run_stage(&stage, StageName::Combine, start, deadline).await?;
    let published = run_stage(&stage, StageName::Publish, start, deadline).await?;

    Ok(Published::from(published))
}

//! Two-branch fan-in pipeline over `ai_task_support` stages.

use std::future::Future;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

/// Why the pipeline did not produce a `Published`.
#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Slot {
    Waiting,
    Done,
    Failed,
    Expired,
}

struct State {
    a: Slot,
    b: Slot,
    cancel: bool,
    expired: bool,
    waker: Option<Waker>,
}

struct Shared {
    state: Mutex<State>,
    cv: Condvar,
    deadline: Instant,
}

impl Shared {
    fn new(deadline: Duration) -> Self {
        Shared {
            state: Mutex::new(State {
                a: Slot::Waiting,
                b: Slot::Waiting,
                cancel: false,
                expired: false,
                waker: None,
            }),
            cv: Condvar::new(),
            deadline: Instant::now() + deadline,
        }
    }
}

fn lock(shared: &Shared) -> MutexGuard<'_, State> {
    shared.state.lock().unwrap_or_else(|e| e.into_inner())
}

struct CvWaker(Arc<Shared>);

impl Wake for CvWaker {
    fn wake(self: Arc<Self>) {
        self.0.cv.notify_all();
    }
    fn wake_by_ref(self: &Arc<Self>) {
        self.0.cv.notify_all();
    }
}

/// Fires once the overall deadline passes (or as soon as the pipeline is dropped).
struct CancelGuard(Arc<Shared>);

impl Drop for CancelGuard {
    fn drop(&mut self) {
        let waker = {
            let mut g = lock(&self.0);
            g.cancel = true;
            g.waker.take()
        };
        self.0.cv.notify_all();
        drop(waker);
    }
}

fn spawn_timer(shared: Arc<Shared>) {
    thread::spawn(move || {
        let mut g = lock(&shared);
        loop {
            if g.cancel {
                return;
            }
            let now = Instant::now();
            if now >= shared.deadline {
                g.expired = true;
                let waker = g.waker.take();
                drop(g);
                if let Some(w) = waker {
                    w.wake();
                }
                return;
            }
            let (ng, _) = shared
                .cv
                .wait_timeout(g, shared.deadline - now)
                .unwrap_or_else(|e| e.into_inner());
            g = ng;
        }
    });
}

fn spawn_worker(shared: Arc<Shared>, stage: Stage, name: StageName, is_a: bool) {
    thread::spawn(move || {
        let fut = stage.run(name);
        let slot = match drive(shared.clone(), fut) {
            Some(Ok(_)) => Slot::Done,
            Some(Err(_)) => Slot::Failed,
            None => Slot::Expired,
        };
        let waker = {
            let mut g = lock(&shared);
            if is_a {
                g.a = slot;
            } else {
                g.b = slot;
            }
            g.waker.take()
        };
        if let Some(w) = waker {
            w.wake();
        }
    });
}

/// Polls `fut` on this thread until it settles, the deadline passes, or the
/// pipeline is dropped. Returning `None` means the stage did not finish.
fn drive<F>(shared: Arc<Shared>, fut: F) -> Option<Result<Artifact, StageError>>
where
    F: Future<Output = Result<Artifact, StageError>>,
{
    let mut fut = Box::pin(fut);
    let waker = Waker::from(Arc::new(CvWaker(shared.clone())));
    let mut cx = Context::from_waker(&waker);
    loop {
        {
            let g = lock(&shared);
            if g.cancel || g.expired || Instant::now() >= shared.deadline {
                return None;
            }
        }
        if let Poll::Ready(out) = fut.as_mut().poll(&mut cx) {
            return Some(out);
        }
        let mut g = lock(&shared);
        if g.cancel || g.expired || Instant::now() >= shared.deadline {
            return None;
        }
        g = shared.cv.wait(g).unwrap_or_else(|e| e.into_inner());
        drop(g);
    }
}

fn evaluate(g: &mut State) -> Option<Result<(), PipelineError>> {
    let outcome = if matches!(g.a, Slot::Failed) {
        Some(Err(PipelineError::Stage {
            name: StageName::FetchA,
        }))
    } else if matches!(g.b, Slot::Failed) {
        Some(Err(PipelineError::Stage {
            name: StageName::FetchB,
        }))
    } else if g.expired || matches!(g.a, Slot::Expired) || matches!(g.b, Slot::Expired) {
        Some(Err(PipelineError::Deadline))
    } else if matches!(g.a, Slot::Done) && matches!(g.b, Slot::Done) {
        Some(Ok(()))
    } else {
        None
    };
    if outcome.is_some() {
        g.waker = None;
    }
    outcome
}

async fn wait_both(shared: &Arc<Shared>) -> Result<(), PipelineError> {
    let shared = Arc::clone(shared);
    std::future::poll_fn(move |cx| {
        let mut g = lock(&shared);
        if let Some(out) = evaluate(&mut g) {
            return Poll::Ready(out);
        }
        g.waker = Some(cx.waker().clone());
        match evaluate(&mut g) {
            Some(out) => Poll::Ready(out),
            None => Poll::Pending,
        }
    })
    .await
}

/// Runs one stage inline on the caller's task, under the overall deadline.
async fn run_stage(
    shared: &Arc<Shared>,
    stage: &Stage,
    name: StageName,
) -> Result<Artifact, PipelineError> {
    let fut = stage.run(name);
    let mut fut = std::pin::pin!(fut);
    let shared = Arc::clone(shared);
    std::future::poll_fn(move |cx| {
        {
            let mut g = lock(&shared);
            if g.expired || Instant::now() >= shared.deadline {
                g.waker = None;
                return Poll::Ready(Err(PipelineError::Deadline));
            }
            g.waker = Some(cx.waker().clone());
        }
        match fut.as_mut().poll(cx) {
            Poll::Ready(Ok(artifact)) => {
                lock(&shared).waker = None;
                Poll::Ready(Ok(artifact))
            }
            Poll::Ready(Err(_)) => {
                lock(&shared).waker = None;
                Poll::Ready(Err(PipelineError::Stage { name }))
            }
            Poll::Pending => Poll::Pending,
        }
    })
    .await
}

/// Runs `fetch_a` and `fetch_b` concurrently, then `combine`, then `publish`.
pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let shared = Arc::new(Shared::new(deadline));
    let _cancel = CancelGuard(Arc::clone(&shared));
    spawn_worker(Arc::clone(&shared), stage.clone(), StageName::FetchA, true);
    spawn_worker(Arc::clone(&shared), stage.clone(), StageName::FetchB, false);
    spawn_timer(Arc::clone(&shared));

    wait_both(&shared).await?;
    let _combined = run_stage(&shared, &stage, StageName::Combine).await?;
    let published = run_stage(&shared, &stage, StageName::Publish).await?;
    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use lgwks_bot::rt::time::timeout;

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Polls two futures on the same task; dropping it drops both.
struct Both<A: Future, B: Future> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    out_a: Option<A::Output>,
    out_b: Option<B::Output>,
}

impl<A: Future, B: Future> Future for Both<A, B> {
    type Output = (A::Output, B::Output);

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // SAFETY: the pinned boxes are never moved, only replaced/dropped in place.
        let this = unsafe { self.get_unchecked_mut() };
        if this.out_a.is_none() {
            if let Poll::Ready(v) = this.a.as_mut().unwrap().as_mut().poll(cx) {
                this.out_a = Some(v);
                this.a = None;
            }
        }
        if this.out_b.is_none() {
            if let Poll::Ready(v) = this.b.as_mut().unwrap().as_mut().poll(cx) {
                this.out_b = Some(v);
                this.b = None;
            }
        }
        match (this.out_a.take(), this.out_b.take()) {
            (Some(x), Some(y)) => Poll::Ready((x, y)),
            (x, y) => {
                this.out_a = x;
                this.out_b = y;
                Poll::Pending
            }
        }
    }
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let run = async move {
        let (a, b) = Both {
            a: Some(Box::pin(stage.run(StageName::FetchA))),
            b: Some(Box::pin(stage.run(StageName::FetchB))),
            out_a: None,
            out_b: None,
        }
        .await;

        let _a = a.map_err(|_| PipelineError::Stage {
            name: StageName::FetchA,
        })?;
        let _b = b.map_err(|_| PipelineError::Stage {
            name: StageName::FetchB,
        })?;

        let _c = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok::<Published, PipelineError>(Published::from(published))
    };

    timeout(deadline, run).await.map_err(|_| PipelineError::Deadline)?
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // fetch_a and fetch_b are independent: one fan-out owns both bodies, so
    // dropping this future drops them, and the first failure stops the pair.
    let _fetched = match FanOut::new(vec![StageName::FetchA, StageName::FetchB])
        .at_most(2)
        .run(|name| {
            let stage = stage.clone();
            async move { stage.run(name).await }
        })
        .await
    {
        Ok(artifacts) => artifacts,
        Err(FanOutError::Item { index, .. }) => {
            let name = if index == 0 {
                StageName::FetchA
            } else {
                StageName::FetchB
            };
            return Err(PipelineError::Stage { name });
        }
        Err(FanOutError::TimedOut { .. }) => return Err(PipelineError::Deadline),
        Err(FanOutError::Flow(_)) => return Err(PipelineError::Cancelled),
        Err(_) => return Err(PipelineError::Cancelled),
    };

    // combine runs only once both fetches succeeded.
    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

//! A four-stage pipeline over an `ai_task_support::Stage`.
//!
//! `fetch_a` and `fetch_b` are driven concurrently inside the caller's own
//! future, `combine` runs only after both have succeeded, and `publish` runs
//! only after `combine` has succeeded. Every stage future is owned by
//! `solve`'s future, so dropping it drops the in-flight stage, and the whole
//! run is raced against a single deadline.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageFuture<'a> = Pin<Box<dyn Future<Output = Result<Artifact, StageError>> + 'a>>;

enum Phase<'a> {
    Fetch {
        a: StageFuture<'a>,
        b: StageFuture<'a>,
        a_out: Option<Result<Artifact, StageError>>,
        b_out: Option<Result<Artifact, StageError>>,
    },
    Single {
        name: StageName,
        fut: StageFuture<'a>,
    },
}

enum Step {
    Wait,
    Advance(StageName),
    Finish(Result<Published, PipelineError>),
}

fn name_of(name: &StageName) -> StageName {
    match name {
        StageName::FetchA => StageName::FetchA,
        StageName::FetchB => StageName::FetchB,
        StageName::Combine => StageName::Combine,
        StageName::Publish => StageName::Publish,
    }
}

fn advance(phase: &mut Phase<'_>, cx: &mut Context<'_>) -> Step {
    match phase {
        Phase::Fetch {
            a,
            b,
            a_out,
            b_out,
        } => {
            if a_out.is_none() {
                if let Poll::Ready(out) = a.as_mut().poll(cx) {
                    *a_out = Some(out);
                }
            }
            if b_out.is_none() {
                if let Poll::Ready(out) = b.as_mut().poll(cx) {
                    *b_out = Some(out);
                }
            }
            match (a_out.as_ref(), b_out.as_ref()) {
                (Some(Err(_)), _) => Step::Finish(Err(PipelineError::Stage {
                    name: StageName::FetchA,
                })),
                (_, Some(Err(_))) => Step::Finish(Err(PipelineError::Stage {
                    name: StageName::FetchB,
                })),
                (Some(Ok(_)), Some(Ok(_))) => Step::Advance(StageName::Combine),
                _ => Step::Wait,
            }
        }
        Phase::Single { name, fut } => match fut.as_mut().poll(cx) {
            Poll::Ready(Ok(artifact)) => match name {
                StageName::Combine => Step::Advance(StageName::Publish),
                _ => Step::Finish(Ok(Published::from(artifact))),
            },
            Poll::Ready(Err(_)) => {
                Step::Finish(Err(PipelineError::Stage { name: name_of(name) }))
            }
            Poll::Pending => Step::Wait,
        },
    }
}

struct TimerShared {
    stop: bool,
    waker: Option<Waker>,
}

struct Timer {
    shared: Arc<Mutex<TimerShared>>,
    signal: Arc<Condvar>,
    join: Option<JoinHandle<()>>,
}

impl Timer {
    fn spawn(started: Instant, limit: Duration, waker: &Waker) -> Option<Timer> {
        let end = started.checked_add(limit)?;
        let shared = Arc::new(Mutex::new(TimerShared {
            stop: false,
            waker: Some(waker.clone()),
        }));
        let signal = Arc::new(Condvar::new());
        let thread_shared = Arc::clone(&shared);
        let thread_signal = Arc::clone(&signal);
        let join = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || loop {
                let mut guard = match thread_shared.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };
                if guard.stop {
                    return;
                }
                let now = Instant::now();
                if now >= end {
                    let waker = guard.waker.take();
                    drop(guard);
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }
                let remaining = end - now;
                let guard = match thread_signal.wait_timeout(guard, remaining) {
                    Ok((guard, _)) => guard,
                    Err(poisoned) => poisoned.into_inner().0,
                };
                drop(guard);
            })
            .ok()?;
        Some(Timer {
            shared,
            signal,
            join: Some(join),
        })
    }

    fn refresh(&self, waker: &Waker) {
        let mut guard = match self.shared.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        if guard.waker.is_some() {
            guard.waker = Some(waker.clone());
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        {
            let mut guard = match self.shared.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            guard.stop = true;
        }
        self.signal.notify_all();
        if let Some(join) = self.join.take() {
            let _ = join.join();
        }
    }
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let started = Instant::now();
    let limit = deadline;
    let mut phase: Phase<'_> = Phase::Fetch {
        a: Box::pin(stage.run(StageName::FetchA)),
        b: Box::pin(stage.run(StageName::FetchB)),
        a_out: None,
        b_out: None,
    };
    let mut timer: Option<Timer> = None;

    poll_fn(|cx| {
        match timer.as_mut() {
            Some(timer) => timer.refresh(cx.waker()),
            None => timer = Timer::spawn(started, limit, cx.waker()),
        }
        loop {
            if started.elapsed() >= limit {
                return Poll::Ready(Err(PipelineError::Deadline));
            }
            match advance(&mut phase, cx) {
                Step::Wait => return Poll::Pending,
                Step::Finish(result) => return Poll::Ready(result),
                Step::Advance(name) => {
                    phase = Phase::Single {
                        name,
                        fut: Box::pin(stage.run(name)),
                    };
                }
            }
        }
    })
    .await
}

use std::future::Future;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn left(deadline: Duration, started: Instant) -> Duration {
    deadline.saturating_sub(started.elapsed())
}

fn fanout(error: FanOutError<PipelineError>) -> PipelineError {
    match error {
        FanOutError::Item { error, .. } => error,
        _ => PipelineError::Deadline,
    }
}

async fn stage_step(stage: &Stage, name: StageName) -> Result<Artifact, PipelineError> {
    match stage.run(name).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage { name }),
    }
}

async fn race<T, F>(budget: Duration, body: F) -> Result<T, PipelineError>
where
    F: Future<Output = Result<T, PipelineError>>,
{
    match timeout(budget, body).await {
        Ok(outcome) => outcome,
        Err(_) => Err(PipelineError::Deadline),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let started = Instant::now();

    let _fetched = race(left(deadline, started), async {
        FanOut::new([StageName::FetchA, StageName::FetchB])
            .at_most(2)
            .run(|name| stage_step(&stage, name))
            .await
            .map_err(fanout)
    })
    .await?;

    let combined = race(
        left(deadline, started),
        stage_step(&stage, StageName::Combine),
    )
    .await?;

    let published = race(
        left(deadline, started),
        stage_step(&stage, StageName::Publish),
    )
    .await?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

// ---------------------------------------------------------------------------
// Minimal future plumbing: a `poll_fn` combinator, so the whole pipeline can be
// written as one `async fn` that owns every stage future directly.
// ---------------------------------------------------------------------------

struct PollFn<F>(F);

impl<F, T> Future for PollFn<F>
where
    F: FnMut(&mut Context<'_>) -> Poll<T> + Unpin,
{
    type Output = T;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<T> {
        (self.get_mut().0)(cx)
    }
}

fn poll_fn<T, F>(f: F) -> PollFn<F>
where
    F: FnMut(&mut Context<'_>) -> Poll<T> + Unpin,
{
    PollFn(f)
}

// ---------------------------------------------------------------------------
// Overall deadline. A single sleeper thread arms the caller's waker when the
// budget runs out. Dropping the `Alarm` (i.e. dropping the `solve` future)
// wakes and joins the sleeper, so nothing survives the call.
// ---------------------------------------------------------------------------

struct AlarmState {
    inner: Mutex<AlarmInner>,
    cv: Condvar,
}

struct AlarmInner {
    waker: Option<Waker>,
    fired: bool,
    aborted: bool,
}

struct Alarm {
    state: Arc<AlarmState>,
    handle: Option<JoinHandle<()>>,
}

impl Alarm {
    fn start(limit: Duration) -> Alarm {
        let state = Arc::new(AlarmState {
            inner: Mutex::new(AlarmInner {
                waker: None,
                fired: false,
                aborted: false,
            }),
            cv: Condvar::new(),
        });
        let worker = Arc::clone(&state);
        let handle = thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || {
                let mut guard = match worker.inner.lock() {
                    Ok(guard) => guard,
                    Err(_) => return,
                };
                loop {
                    let (next, outcome) = match worker.cv.wait_timeout(guard, limit) {
                        Ok(pair) => pair,
                        Err(_) => return,
                    };
                    guard = next;
                    if guard.aborted {
                        return;
                    }
                    if outcome.timed_out() {
                        guard.fired = true;
                        let waker = guard.waker.take();
                        drop(guard);
                        if let Some(waker) = waker {
                            waker.wake();
                        }
                        return;
                    }
                }
            })
            .ok();
        Alarm { state, handle }
    }

    fn arm(&self, waker: &Waker) {
        if let Ok(mut guard) = self.state.inner.lock() {
            if !guard.fired && !guard.aborted {
                guard.waker = Some(waker.clone());
            }
        }
    }

    fn fired(&self) -> bool {
        match self.state.inner.lock() {
            Ok(guard) => guard.fired,
            Err(_) => false,
        }
    }
}

impl Drop for Alarm {
    fn drop(&mut self) {
        if let Ok(mut guard) = self.state.inner.lock() {
            guard.aborted = true;
            guard.waker = None;
        }
        self.state.cv.notify_all();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

// ---------------------------------------------------------------------------
// The pipeline.
// ---------------------------------------------------------------------------

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let alarm = Alarm::start(deadline);

    // `fetch_a` and `fetch_b` are independent: both futures are created up
    // front and are polled on every wake-up, so they make progress together.
    let mut fetch_a = Box::pin(stage.run(StageName::FetchA));
    let mut fetch_b = Box::pin(stage.run(StageName::FetchB));
    let mut artifact_a: Option<Artifact> = None;
    let mut artifact_b: Option<Artifact> = None;
    let mut failure: Option<StageName> = None;

    let (a, b) = poll_fn(|cx: &mut Context<'_>| {
        if alarm.fired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        if artifact_a.is_none() && failure.is_none() {
            if let Poll::Ready(outcome) = fetch_a.as_mut().poll(cx) {
                match outcome {
                    Ok(artifact) => artifact_a = Some(artifact),
                    Err(_) => failure = Some(StageName::FetchA),
                }
            }
        }

        if artifact_b.is_none() && failure.is_none() {
            if let Poll::Ready(outcome) = fetch_b.as_mut().poll(cx) {
                match outcome {
                    Ok(artifact) => artifact_b = Some(artifact),
                    Err(_) => failure = Some(StageName::FetchB),
                }
            }
        }

        // A failed fetch short-circuits everything: the other future is
        // dropped right here and neither `combine` nor `publish` is ever built.
        if let Some(name) = failure {
            return Poll::Ready(Err(PipelineError::Stage { name }));
        }

        if let (Some(a), Some(b)) = (artifact_a.take(), artifact_b.take()) {
            return Poll::Ready(Ok((a, b)));
        }

        alarm.arm(cx.waker());
        Poll::Pending
    })
    .await?;

    drop(fetch_a);
    drop(fetch_b);

    // `combine` needs both inputs; it runs only once both fetches succeeded.
    let combined = {
        let mut combine = Box::pin(stage.run(StageName::Combine));
        let alarm = &alarm;
        poll_fn(move |cx: &mut Context<'_>| {
            if alarm.fired() {
                return Poll::Ready(Err(PipelineError::Deadline));
            }
            match combine.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => Poll::Ready(Ok(artifact)),
                Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage {
                    name: StageName::Combine,
                })),
                Poll::Pending => {
                    alarm.arm(cx.waker());
                    Poll::Pending
                }
            }
        })
        .await?
    };

    let _ = (a.value(), b.value());

    // `publish` needs `combine`.
    let mut publish = Box::pin(stage.run(StageName::Publish));
    let alarm = &alarm;
    let published = poll_fn(move |cx: &mut Context<'_>| {
        if alarm.fired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match publish.as_mut().poll(cx) {
            Poll::Ready(Ok(artifact)) => Poll::Ready(Ok(Published::from(artifact))),
            Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage {
                name: StageName::Publish,
            })),
            Poll::Pending => {
                alarm.arm(cx.waker());
                Poll::Pending
            }
        }
    })
    .await?;

    Ok(published)
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

/// The widest fan-out `solve` is ever allowed to open.
const CONCURRENCY: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let scope =
        Scope::root(Tenant::new("aggregate").expect("\"aggregate\" is a valid tenant name"));

    // The first id whose fetch is observed to fail. Kept outside the fan-out so
    // the failure can be named after `each` has torn the fan-out down.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let observed = Arc::clone(&failed);

    let limit = NonZeroUsize::new(CONCURRENCY).expect("4 is non-zero");
    let first_failure = Arc::clone(&failed);
    let inner = scope.clone();

    let outcome = within(&scope, "deadline", deadline, async move {
        // `each` is bounded, ordered, fail-fast and owning: at most `limit`
        // bodies run at once, no body starts once one has failed, and dropping
        // this future drops every body still in flight.
        let values = each(&inner, "fetch", Some(limit), ids, move |_step, id| {
            let fetch = fetch.clone();
            let failed = Arc::clone(&first_failure);
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        let mut slot = failed
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner());
                        if slot.is_none() {
                            *slot = Some(id);
                        }
                        Err(FlowError::failed("fetch failed"))
                    }
                }
            }
        })
        .await?;

        Ok::<u64, FlowError>(values.into_iter().sum())
    })
    .await;

    match outcome {
        Ok(sum) => Ok(sum),
        Err(err) => {
            if err.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            let recorded = observed
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            match *recorded {
                Some(id) => Err(SolveError::Fetch { id }),
                None => Err(SolveError::Deadline),
            }
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Wakes the task that drives the solve whenever one of the fetches it owns
/// becomes ready, so inner progress always reaches the outer executor.
struct Forward {
    waker: Mutex<Waker>,
}

impl Wake for Forward {
    fn wake(self: Arc<Self>) {
        Forward::wake_by_ref(&self);
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Ok(waker) = self.waker.lock() {
            waker.wake_by_ref();
        }
    }
}

/// A single sleeping helper that wakes the driver when the deadline passes, so
/// a deadline is observed even when no fetch ever completes. It parks on a
/// condvar so it costs nothing once the solve is over.
struct Timer {
    finished: AtomicBool,
    lock: Mutex<()>,
    signal: Condvar,
}

impl Timer {
    fn spawn(limit: Duration, forward: Arc<Forward>) -> Arc<Timer> {
        let timer = Arc::new(Timer {
            finished: AtomicBool::new(false),
            lock: Mutex::new(()),
            signal: Condvar::new(),
        });
        let owned = Arc::clone(&timer);
        let spawned = std::thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || {
                let Ok(guard) = owned.lock.lock() else { return };
                let _ = owned.signal.wait_timeout(guard, limit);
                if !owned.finished.load(Ordering::SeqCst) {
                    Forward::wake_by_ref(&forward);
                }
            });
        if spawned.is_err() {
            timer.stop();
        }
        timer
    }

    fn stop(&self) {
        self.finished.store(true, Ordering::SeqCst);
        if let Ok(guard) = self.lock.lock() {
            drop(guard);
        }
        self.signal.notify_all();
    }
}

struct Active {
    id: u32,
    fut: Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send + 'static>>,
}

struct Solver {
    ids: std::vec::IntoIter<u32>,
    fetch: Fetcher,
    limit: Duration,
    start: Instant,
    forward: Option<Arc<Forward>>,
    timer: Option<Arc<Timer>>,
    active: Vec<Active>,
    sum: u64,
    failure: Option<u32>,
    timed_out: bool,
    done: bool,
}

// Every future the solver owns is pinned inside its own box, so moving the
// solver around never moves a running fetch.
impl Unpin for Solver {}

impl Solver {
    fn new(ids: Vec<u32>, fetch: Fetcher, limit: Duration) -> Self {
        Solver {
            ids: ids.into_iter(),
            fetch,
            limit,
            start: Instant::now(),
            forward: None,
            timer: None,
            active: Vec::new(),
            sum: 0,
            failure: None,
            timed_out: false,
            done: false,
        }
    }

    fn outcome(&self) -> Result<u64, SolveError> {
        if let Some(id) = self.failure {
            Err(SolveError::Fetch { id })
        } else if self.timed_out {
            Err(SolveError::Deadline)
        } else {
            Ok(self.sum)
        }
    }

    /// Dropping every running fetch here is what makes the work stop with the
    /// future, whether the future is dropped by its owner or resolved here.
    fn finish(&mut self) -> Poll<Result<u64, SolveError>> {
        self.active.clear();
        if let Some(timer) = &self.timer {
            timer.stop();
        }
        self.done = true;
        Poll::Ready(self.outcome())
    }
}

impl Future for Solver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        if me.done {
            return Poll::Ready(me.outcome());
        }

        match &me.forward {
            Some(forward) => {
                if let Ok(mut slot) = forward.waker.lock() {
                    *slot = cx.waker().clone();
                }
            }
            None => {
                let forward = Arc::new(Forward {
                    waker: Mutex::new(cx.waker().clone()),
                });
                let timer = Timer::spawn(me.limit, Arc::clone(&forward));
                me.forward = Some(forward);
                me.timer = Some(timer);
            }
        }

        let forward = match &me.forward {
            Some(forward) => Arc::clone(forward),
            None => return Poll::Pending,
        };
        let waker = Waker::from(Arc::clone(&forward));
        let mut inner = Context::from_waker(&waker);

        loop {
            // Start work only while there is room, nothing has failed, and the
            // deadline has not already passed.
            while me.failure.is_none()
                && !me.timed_out
                && me.active.len() < MAX_IN_FLIGHT
                && me.ids.len() > 0
            {
                if me.start.elapsed() >= me.limit {
                    me.timed_out = true;
                    break;
                }
                let id = me.ids.next().expect("ids checked non-empty");
                let fetch = me.fetch.clone();
                me.active.push(Active {
                    id,
                    fut: Box::pin(async move { fetch.fetch(id).await }),
                });
            }

            if me.timed_out {
                return me.finish();
            }

            if me.active.is_empty() {
                return me.finish();
            }

            let mut progressed = false;
            let mut index = 0;
            while index < me.active.len() {
                match me.active[index].fut.as_mut().poll(&mut inner) {
                    Poll::Ready(Ok(value)) => {
                        me.sum = me.sum.saturating_add(value);
                        me.active.swap_remove(index);
                        progressed = true;
                    }
                    Poll::Ready(Err(_)) => {
                        me.failure = Some(me.active[index].id);
                        return me.finish();
                    }
                    Poll::Pending => index += 1,
                }
            }

            if !progressed {
                return Poll::Pending;
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solver::new(ids, fetch, deadline).await
}

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::task::Poll;
use std::time::{Duration, Instant};

/// At most this many `fetch` calls are ever in flight at once.
const MAX_IN_FLIGHT: usize = 4;

/// Every way `solve` can fail.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` call for `id` returned an error.
    Fetch { id: u32 },
    /// The overall `deadline` elapsed before every id was resolved.
    Deadline,
    /// The work was cancelled before every id was resolved.
    Cancelled,
}

/// Sum the values fetched for `ids`, with at most [`MAX_IN_FLIGHT`] fetches in
/// flight, failing fast on the first fetch error and giving up at `deadline`.
///
/// Every in-flight fetch future is owned by the returned future's own frame: it
/// is polled in place, never handed to a runtime or spawned, so dropping the
/// `solve` future drops the still-pending fetches with it and leaves nothing
/// running behind.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    type Fetched = Result<u64, ai_task_support::FetchError>;

    struct Running<'f> {
        id: u32,
        call: Pin<Box<dyn Future<Output = Fetched> + Send + 'f>>,
    }

    let start = Instant::now();
    let mut queue: VecDeque<u32> = ids.into_iter().collect();
    let mut in_flight: Vec<Running<'_>> = Vec::with_capacity(MAX_IN_FLIGHT);
    let mut total: u64 = 0;

    let outcome = std::future::poll_fn(|cx| loop {
        // 1. Poll every in-flight fetch; collect the finished ones.
        let mut index = 0;
        while index < in_flight.len() {
            let id = in_flight[index].id;
            let finished = match in_flight[index].call.as_mut().poll(cx) {
                Poll::Pending => None,
                Poll::Ready(result) => Some(result),
            };
            match finished {
                None => index += 1,
                Some(Ok(value)) => {
                    total = total.saturating_add(value);
                    in_flight.swap_remove(index);
                }
                Some(Err(_)) => {
                    // Failure observed: stop everything still running and
                    // start nothing new.
                    in_flight.clear();
                    return Poll::Ready(Err(SolveError::Fetch { id }));
                }
            }
        }

        // 2. Every id is resolved.
        if queue.is_empty() && in_flight.is_empty() {
            return Poll::Ready(Ok(total));
        }

        // 3. Out of time: drop the in-flight fetches and start nothing more.
        if start.elapsed() >= deadline {
            in_flight.clear();
            return Poll::Ready(Err(SolveError::Deadline));
        }

        // 4. Refill the window, never beyond MAX_IN_FLIGHT.
        let before = in_flight.len();
        while in_flight.len() < MAX_IN_FLIGHT {
            let Some(id) = queue.pop_front() else { break };
            in_flight.push(Running {
                id,
                call: Box::pin(fetch.fetch(id)),
            });
        }

        if in_flight.len() == before {
            // Nothing new to start; the pending fetches have armed the waker.
            return Poll::Pending;
        }
        // Newly started calls get polled in this same pass.
    })
    .await;

    // Anything still owned here is dropped before we return, so no fetch
    // outlives the call that started it.
    in_flight.clear();
    outcome
}

#![forbid(unsafe_code)]

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

/// Hard ceiling on concurrent `fetch` calls owned by one `solve` call.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

// ---------------------------------------------------------------------------
// Deadline helper
// ---------------------------------------------------------------------------

struct TimerState {
    armed: bool,
    fired: bool,
    waker: Option<Waker>,
}

/// A one-shot deadline that owns its wakeup path.
///
/// The elapsed check is purely clock based; a helper thread exists only so that a
/// pending `solve` still gets woken up when the deadline lands while every
/// `fetch` future is idle. Dropping the timer disarms the helper so it never
/// touches a waker belonging to a future that no longer exists.
struct DeadlineTimer {
    state: Arc<Mutex<TimerState>>,
    expires: Instant,
}

impl DeadlineTimer {
    fn start(limit: Duration) -> Self {
        let state = Arc::new(Mutex::new(TimerState {
            armed: true,
            fired: false,
            waker: None,
        }));

        let worker = Arc::clone(&state);
        let spawned = std::thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || {
                std::thread::sleep(limit);
                let waker = {
                    let mut guard = lock(&worker);
                    guard.fired = true;
                    if guard.armed {
                        guard.waker.take()
                    } else {
                        None
                    }
                };
                if let Some(waker) = waker {
                    waker.wake();
                }
            });

        if spawned.is_err() {
            // No helper thread available: the clock check alone still enforces
            // the deadline on the next wakeup.
            let mut guard = lock(&state);
            guard.armed = false;
        }

        DeadlineTimer {
            state,
            expires: Instant::now() + limit,
        }
    }

    /// True once the deadline has passed. Otherwise the caller's waker is
    /// registered so the helper thread can wake it.
    fn elapsed(&self, cx: &Context<'_>) -> bool {
        if Instant::now() >= self.expires {
            return true;
        }
        let mut guard = lock(&self.state);
        if guard.fired {
            return true;
        }
        guard.waker = Some(cx.waker().clone());
        false
    }
}

impl Drop for DeadlineTimer {
    fn drop(&mut self) {
        let mut guard = lock(&self.state);
        guard.armed = false;
        guard.waker = None;
    }
}

fn lock(state: &Mutex<TimerState>) -> MutexGuard<'_, TimerState> {
    match state.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

// ---------------------------------------------------------------------------
// Driver
// ---------------------------------------------------------------------------

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send>>;

struct InFlight {
    id: u32,
    future: FetchFuture,
}

struct Driver {
    fetch: Arc<Fetcher>,
    queue: VecDeque<u32>,
    in_flight: Vec<Option<InFlight>>,
    limit: Duration,
    timer: Option<DeadlineTimer>,
    sum: u64,
    started: bool,
    done: bool,
}

impl Driver {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Self {
        Driver {
            fetch: Arc::new(fetch),
            queue: ids.into_iter().collect(),
            in_flight: Vec::new(),
            limit: deadline,
            timer: None,
            sum: 0,
            started: false,
            done: false,
        }
    }

    fn all_finished(&self) -> bool {
        self.queue.is_empty() && self.in_flight.iter().all(|entry| entry.is_none())
    }

    fn fill(&mut self) {
        self.in_flight.retain(|entry| entry.is_some());
        while self.in_flight.len() < MAX_IN_FLIGHT {
            let id = match self.queue.pop_front() {
                Some(id) => id,
                None => break,
            };
            let fetch = Arc::clone(&self.fetch);
            let future: FetchFuture = Box::pin(async move { fetch.fetch(id).await });
            self.in_flight.push(Some(InFlight { id, future }));
        }
    }

    /// Drop everything this future owns: queued ids and running fetches.
    fn abort(&mut self) {
        self.queue.clear();
        self.in_flight.clear();
        self.timer = None;
    }
}

impl Future for Driver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.done {
            panic!("aggregate::solve polled after completion");
        }

        if !this.started {
            this.started = true;
            if this.queue.is_empty() {
                this.done = true;
                return Poll::Ready(Ok(0));
            }
            this.timer = Some(DeadlineTimer::start(this.limit));
        }

        loop {
            // Every requested id has completed: report the sum, whatever the
            // clock says at this instant.
            if this.all_finished() {
                this.done = true;
                let sum = this.sum;
                this.abort();
                return Poll::Ready(Ok(sum));
            }

            if this.timer.as_ref().is_some_and(|timer| timer.elapsed(cx)) {
                this.done = true;
                this.abort();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            this.fill();

            if this.in_flight.is_empty() {
                // Nothing running and nothing left to start; the next turn of
                // the loop reports completion.
                continue;
            }

            let mut polled: Vec<Option<Result<u64, FetchError>>> =
                Vec::with_capacity(this.in_flight.len());
            for entry in this.in_flight.iter_mut() {
                let owned = entry
                    .as_mut()
                    .expect("in-flight slots are compacted before polling");
                polled.push(match owned.future.as_mut().poll(cx) {
                    Poll::Ready(result) => Some(result),
                    Poll::Pending => None,
                });
            }

            let mut settled = 0usize;
            let mut failure: Option<u32> = None;

            for (index, result) in polled.into_iter().enumerate() {
                match result {
                    None => {}
                    Some(Ok(value)) => {
                        this.sum = this.sum.wrapping_add(value);
                        // Drop the finished fetch before anything new starts.
                        this.in_flight[index] = None;
                        settled += 1;
                    }
                    Some(Err(_)) => {
                        let owned = this.in_flight[index].take();
                        failure = Some(owned.map(|entry| entry.id).unwrap_or(0));
                        break;
                    }
                }
            }

            if let Some(id) = failure {
                // No further fetch is started, and everything still running is
                // dropped on the way out.
                this.done = true;
                this.abort();
                return Poll::Ready(Err(SolveError::Fetch { id }));
            }

            if settled == 0 {
                // All fetches are idle; the harness or the deadline helper owns
                // the wakeup.
                return Poll::Pending;
            }

            this.in_flight.retain(|entry| entry.is_some());
        }
    }
}

// ---------------------------------------------------------------------------
// Public surface
// ---------------------------------------------------------------------------

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Driver::new(ids, fetch, deadline).await
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{mpsc, Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::Duration;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

struct Join<F>
where
    F: Future<Output = Result<u64, ai_task_support::FetchError>>,
{
    items: Vec<(u32, Pin<Box<F>>)>,
    done: Vec<(u32, Result<u64, ai_task_support::FetchError>)>,
}

impl<F> Future for Join<F>
where
    F: Future<Output = Result<u64, ai_task_support::FetchError>>,
{
    type Output = Vec<(u32, Result<u64, ai_task_support::FetchError>)>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        let mut i = 0;
        while i < this.items.len() {
            match this.items[i].1.as_mut().poll(cx) {
                Poll::Ready(value) => {
                    let (id, _) = this.items.swap_remove(i);
                    this.done.push((id, value));
                }
                Poll::Pending => i += 1,
            }
        }
        if this.items.is_empty() {
            Poll::Ready(std::mem::take(&mut this.done))
        } else {
            Poll::Pending
        }
    }
}

struct Deadline {
    rx: mpsc::Receiver<()>,
    waker: Arc<Mutex<Option<Waker>>>,
}

impl Deadline {
    fn after(d: Duration) -> Deadline {
        let (tx, rx) = mpsc::channel();
        let waker = Arc::new(Mutex::new(None::<Waker>));
        let shared = Arc::clone(&waker);
        thread::spawn(move || {
            thread::sleep(d);
            let _ = tx.send(());
            if let Ok(mut slot) = shared.lock() {
                if let Some(w) = slot.take() {
                    w.wake();
                }
            }
        });
        Deadline { rx, waker }
    }
}

impl Future for Deadline {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if let Ok(mut slot) = this.waker.lock() {
            *slot = Some(cx.waker().clone());
        }
        match this.rx.try_recv() {
            Ok(()) => Poll::Ready(()),
            Err(mpsc::TryRecvError::Disconnected) => Poll::Ready(()),
            Err(mpsc::TryRecvError::Empty) => Poll::Pending,
        }
    }
}

enum Done<T> {
    Work(T),
    Time,
}

async fn run_all(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut sum: u64 = 0;
    let mut rest = ids.into_iter();
    loop {
        let batch: Vec<u32> = rest.by_ref().take(MAX_IN_FLIGHT).collect();
        if batch.is_empty() {
            return Ok(sum);
        }
        let mut items = Vec::with_capacity(batch.len());
        for id in batch {
            items.push((id, Box::pin(fetch.fetch(id))));
        }
        let results = Join { items, done: Vec::new() }.await;
        for (id, value) in results {
            match value {
                Ok(v) => sum = sum.wrapping_add(v),
                Err(_) => return Err(SolveError::Fetch { id }),
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let mut work = Box::pin(run_all(ids, fetch));
    let mut clock = Box::pin(Deadline::after(deadline));
    poll_fn(move |cx| {
        if let Poll::Ready(value) = work.as_mut().poll(cx) {
            return Poll::Ready(Done::Work(value));
        }
        if clock.as_mut().poll(cx).is_ready() {
            return Poll::Ready(Done::Time);
        }
        Poll::Pending
    })
    .await
    .into_result()
}

impl Done<Result<u64, SolveError>> {
    fn into_result(self) -> Result<u64, SolveError> {
        match self {
            Done::Work(r) => r,
            Done::Time => Err(SolveError::Deadline),
        }
    }
}

//! Bounded-concurrency aggregation over `ai_task_support::Fetcher`.

use std::future::Future;
use std::pin::Pin;
use std::sync::mpsc::{self, Sender};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, JoinHandle, Thread};
use std::time::Duration;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// At most 4 concurrent fetches; fails fast, honours the deadline, and owns its
/// work: dropping this future stops and joins everything it started.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let shared = Arc::new(Mutex::new(State {
        queue: ids,
        sum: 0,
        failure: None,
        timed_out: false,
        stop: false,
        active: 0,
        waker: None,
    }));
    Job {
        shared,
        fetch,
        deadline,
        workers: Vec::new(),
        timer: None,
        timer_tx: None,
        joined: false,
    }
    .await
}

struct State {
    queue: Vec<u32>,
    sum: u64,
    failure: Option<u32>,
    timed_out: bool,
    stop: bool,
    active: usize,
    waker: Option<Waker>,
}

fn notify(state: &Arc<Mutex<State>>) {
    let waker = state.lock().expect("state poisoned").waker.take();
    if let Some(waker) = waker {
        waker.wake();
    }
}

fn sweep(state: &Arc<Mutex<State>>) -> Option<Result<u64, SolveError>> {
    let g = state.lock().expect("state poisoned");
    if let Some(id) = g.failure {
        Some(Err(SolveError::Fetch { id }))
    } else if g.timed_out {
        Some(Err(SolveError::Deadline))
    } else if g.active == 0 && g.queue.is_empty() {
        Some(Ok(g.sum))
    } else {
        None
    }
}

struct Parker(Thread);

impl Wake for Parker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }
    fn wake_by_ref(self: &Arc<Self>) {
        self.0.unpark();
    }
}

/// Minimal executor for the single fetch future a worker thread drives.
fn block_on<F: Future>(fut: F) -> F::Output {
    let mut fut = Box::pin(fut);
    let waker = Waker::from(Arc::new(Parker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(value) => return value,
            Poll::Pending => thread::park(),
        }
    }
}

fn worker(state: Arc<Mutex<State>>, fetch: ai_task_support::Fetcher) {
    loop {
        let id = {
            let mut g = state.lock().expect("state poisoned");
            if g.stop {
                return;
            }
            match g.queue.pop() {
                Some(id) => {
                    g.active += 1;
                    id
                }
                None => return,
            }
        };
        let result = block_on(fetch.fetch(id));
        let settled = {
            let mut g = state.lock().expect("state poisoned");
            g.active -= 1;
            match result {
                Ok(value) => {
                    g.sum += value;
                    g.queue.is_empty() && g.active == 0
                }
                Err(_) => {
                    g.stop = true;
                    g.failure = Some(id);
                    true
                }
            }
        };
        if settled {
            notify(&state);
        }
    }
}

struct Job {
    shared: Arc<Mutex<State>>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
    workers: Vec<JoinHandle<()>>,
    timer: Option<JoinHandle<()>>,
    timer_tx: Option<Sender<()>>,
    joined: bool,
}

impl Job {
    fn spawn(&mut self) {
        let queued = {
            let g = self.shared.lock().expect("state poisoned");
            g.queue.len()
        };
        for _ in 0..queued.min(4) {
            let state = Arc::clone(&self.shared);
            let fetch = self.fetch.clone();
            self.workers.push(thread::spawn(move || worker(state, fetch)));
        }
        let state = Arc::clone(&self.shared);
        let deadline = self.deadline;
        let (tx, rx) = mpsc::channel();
        self.timer_tx = Some(tx);
        self.timer = Some(thread::spawn(move || {
            if rx.recv_timeout(deadline).is_err() {
                {
                    let mut g = state.lock().expect("state poisoned");
                    g.timed_out = true;
                    g.stop = true;
                }
                notify(&state);
            }
        }));
    }
}

impl Future for Job {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        if me.workers.is_empty() && me.timer.is_none() {
            me.spawn();
        }
        if let Some(result) = sweep(&me.shared) {
            me.joined = true;
            if result.is_ok() {
                for handle in me.workers.drain(..) {
                    let _ = handle.join();
                }
            }
            return Poll::Ready(result);
        }
        me.shared.lock().expect("state poisoned").waker = Some(cx.waker().clone());
        match sweep(&me.shared) {
            Some(result) => {
                me.joined = true;
                if result.is_ok() {
                    for handle in me.workers.drain(..) {
                        let _ = handle.join();
                    }
                }
                Poll::Ready(result)
            }
            None => Poll::Pending,
        }
    }
}

impl Drop for Job {
    fn drop(&mut self) {
        if !self.joined {
            {
                let mut g = self.shared.lock().expect("state poisoned");
                g.stop = true;
                g.queue.clear();
                g.waker = None;
            }
            for handle in self.workers.drain(..) {
                let _ = handle.join();
            }
        }
        if let Some(tx) = self.timer_tx.take() {
            let _ = tx.send(());
        }
        if let Some(timer) = self.timer.take() {
            let _ = timer.join();
        }
    }
}

//! Bounded, fail-fast, deadline-aware aggregation over an `ai_task_support::Fetcher`.
//!
//! The fan-out is owned by `solve` itself: a small std-only executor polls at
//! most [`LIMIT`] fetch futures at a time, and dropping `solve`'s future drops
//! every fetch that is still in flight.

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

/// Upper bound on fetches that may be in flight at the same time.
const LIMIT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let start = Instant::now();
    let at = start
        .checked_add(deadline)
        .unwrap_or_else(|| start + Duration::from_secs(86_400));

    let width = LIMIT.min(ids.len());
    let work = Arc::new(Work {
        ids,
        next: AtomicUsize::new(0),
        sum: Mutex::new(0),
        failed: Mutex::new(None),
        stopped: AtomicBool::new(false),
        at,
    });

    let mut children = Vec::with_capacity(width);
    for _ in 0..width {
        let child: Pin<Box<dyn Future<Output = Outcome>>> =
            Box::pin(worker(Arc::clone(&work), fetch.clone()));
        children.push(Some(child));
    }

    let signal = Arc::new(Signal::new());
    block_on(
        Driver {
            children,
            work,
            at,
            live: width,
            failure: None,
        },
        &signal,
        at,
    )
}

// ---------------------------------------------------------------------------
// shared state of the fan-out
// ---------------------------------------------------------------------------

/// State every worker reads and writes.
struct Work {
    /// Ids still to be handed out, consumed in input order.
    ids: Vec<u32>,
    /// Index of the next id to hand out.
    next: AtomicUsize,
    /// Running total of the values returned so far.
    sum: Mutex<u64>,
    /// The first id whose fetch failed, if any.
    failed: Mutex<Option<u32>>,
    /// Set as soon as a failure is observed: no further fetch may start.
    stopped: AtomicBool,
    /// The overall deadline.
    at: Instant,
}

impl Work {
    /// Take the next id, or `None` when every id has been handed out.
    fn take(&self) -> Option<u32> {
        let index = self.next.fetch_add(1, Ordering::Relaxed);
        self.ids.get(index).copied()
    }

    /// True once a failure has been observed or the deadline has passed.
    fn halted(&self) -> bool {
        self.stopped.load(Ordering::Acquire) || Instant::now() >= self.at
    }
}

enum Outcome {
    /// This worker has taken every id there is.
    Drained,
    /// Another worker failed, or the deadline passed: stop without fetching.
    Stopped,
    /// This worker's fetch failed.
    Failed(u32),
}

async fn worker(work: Arc<Work>, fetch: Fetcher) -> Outcome {
    loop {
        if work.halted() {
            return Outcome::Stopped;
        }
        let id = match work.take() {
            Some(id) => id,
            None => return Outcome::Drained,
        };
        match fetch.fetch(id).await {
            Ok(value) => {
                *lock(&work.sum) += value;
            }
            Err(_) => {
                let mut failed = lock(&work.failed);
                if failed.is_none() {
                    *failed = Some(id);
                }
                work.stopped.store(true, Ordering::Release);
                return Outcome::Failed(id);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// the driver: polls every worker, owns them, and decides the result
// ---------------------------------------------------------------------------

struct Driver {
    children: Vec<Option<Pin<Box<dyn Future<Output = Outcome>>>>>,
    work: Arc<Work>,
    at: Instant,
    /// Workers that have not finished yet.
    live: usize,
    /// The first failing id seen so far.
    failure: Option<u32>,
}

impl Driver {
    /// Drop every worker, cancelling the fetches still in flight.
    fn abort(&mut self) {
        for slot in self.children.iter_mut() {
            *slot = None;
        }
        self.live = 0;
    }
}

impl Future for Driver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if Instant::now() >= this.at {
            this.abort();
            return Poll::Ready(Err(SolveError::Deadline));
        }

        let mut finished = 0;
        for index in 0..this.children.len() {
            let polled = match this.children[index].as_mut() {
                Some(child) => child.as_mut().poll(cx),
                None => continue,
            };
            if let Poll::Ready(outcome) = polled {
                this.children[index] = None;
                finished += 1;
                if let Outcome::Failed(id) = outcome {
                    if this.failure.is_none() {
                        this.failure = Some(id);
                    }
                }
            }
        }
        this.live -= finished;

        if let Some(id) = this.failure {
            this.abort();
            return Poll::Ready(Err(SolveError::Fetch { id }));
        }
        if this.live == 0 {
            return Poll::Ready(Ok(*lock(&this.work.sum)));
        }
        Poll::Pending
    }
}

// ---------------------------------------------------------------------------
// a minimal single-threaded executor
// ---------------------------------------------------------------------------

/// Wakes the thread driving the fan-out, so a pending fetch is polled again.
struct Signal {
    woken: Mutex<bool>,
    thread: thread::Thread,
}

impl Signal {
    fn new() -> Self {
        Signal {
            woken: Mutex::new(false),
            thread: thread::current(),
        }
    }

    fn ping(&self) {
        *lock(&self.woken) = true;
        self.thread.unpark();
    }

    fn reset(&self) {
        *lock(&self.woken) = false;
    }

    fn was_woken(&self) -> bool {
        *lock(&self.woken)
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.ping();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.ping();
    }
}

/// Drives `fut` to completion on the current thread, parking between polls so
/// a woken fetch is picked up, and giving up at `at`. Everything `fut` owns is
/// dropped when this returns, which is what cancels the fetches in flight.
fn block_on(mut fut: Driver, signal: &Arc<Signal>, at: Instant) -> Result<u64, SolveError> {
    let waker = Waker::from(Arc::clone(signal));
    let mut cx = Context::from_waker(&waker);
    let mut fut = Box::pin(fut);
    loop {
        signal.reset();
        if let Poll::Ready(value) = fut.as_mut().poll(&mut cx) {
            return value;
        }
        let now = Instant::now();
        if now >= at {
            return match fut.as_mut().poll(&mut cx) {
                Poll::Ready(value) => value,
                Poll::Pending => Err(SolveError::Deadline),
            };
        }
        if signal.was_woken() {
            continue;
        }
        // A wake racing with this park leaves an unpark token behind, so the
        // park returns immediately instead of sleeping through it.
        thread::park_timeout(at - now);
    }
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use lgwks_bot::script::{FlowError, Scope, Tenant, at_most, each, within};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let tenant = Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?;
    let scope = Scope::root(tenant);
    let limit = at_most(4).map_err(|_| SolveError::Cancelled)?;

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let outcome = within(&scope, "solve", deadline, async {
        each(&scope, "fetch", Some(limit), ids, |_step, id| {
            let fetcher = fetch.clone();
            let slot = Arc::clone(&failed);
            async move {
                match fetcher.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        {
                            let mut guard = slot.lock().unwrap_or_else(|e| e.into_inner());
                            if guard.is_none() {
                                *guard = Some(id);
                            }
                        }
                        Err(FlowError::failed("fetch failed"))
                    }
                }
            }
        })
        .await
    })
    .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(err) => {
            let recorded = failed.lock().unwrap_or_else(|e| e.into_inner()).take();
            match err {
                FlowError::TimedOut { .. } => Err(SolveError::Deadline),
                FlowError::Cancelled { .. } => Err(SolveError::Cancelled),
                _ => Err(SolveError::Fetch {
                    id: recorded.unwrap_or(0),
                }),
            }
        }
    }
}

use std::collections::VecDeque;
use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

/// Never more than this many `fetch` calls are alive at once.
const MAX_IN_FLIGHT: usize = 4;

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>> + Send>>;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// The caller's waker, plus the flag the deadline watcher raises.
struct Wake {
    waker: Mutex<Option<Waker>>,
    expired: AtomicBool,
}

impl Wake {
    fn new() -> Wake {
        Wake {
            waker: Mutex::new(None),
            expired: AtomicBool::new(false),
        }
    }

    fn lock(&self) -> MutexGuard<'_, Option<Waker>> {
        self.waker
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    fn arm(&self, cx: &Context<'_>) {
        let mut slot = self.lock();
        let stale = match slot.as_ref() {
            None => true,
            Some(w) => !w.will_wake(cx.waker()),
        };
        if stale {
            *slot = Some(cx.waker().clone());
        }
    }

    fn wake(&self) {
        let waker = self.lock().take();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn expired(&self) -> bool {
        self.expired.load(Ordering::SeqCst)
    }
}

/// A latch the timer thread sleeps on, so that dropping `solve` can stop it.
struct Stop {
    flag: Mutex<bool>,
    cv: Condvar,
}

impl Stop {
    fn new() -> Stop {
        Stop {
            flag: Mutex::new(false),
            cv: Condvar::new(),
        }
    }

    fn lock(&self) -> MutexGuard<'_, bool> {
        self.flag
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    fn set(&self) {
        *self.lock() = true;
        self.cv.notify_all();
    }

    /// Sleep until `end`, or until somebody sets the flag, or until a spurious
    /// wake-up we cannot see.
    fn wait_until<'a>(&self, guard: MutexGuard<'a, bool>, end: Instant) -> MutexGuard<'a, bool> {
        let now = Instant::now();
        if now >= end {
            return guard;
        }
        match self.cv.wait_timeout(guard, end - now) {
            Ok((guard, _)) => guard,
            Err(poisoned) => poisoned.into_inner().0,
        }
    }
}

fn watch_deadline(wake: Arc<Wake>, stop: Arc<Stop>, end: Instant) {
    let mut flag = stop.lock();
    while !*flag {
        if Instant::now() >= end {
            break;
        }
        flag = stop.wait_until(flag, end);
    }
    if *flag {
        return;
    }
    drop(flag);
    wake.expired.store(true, Ordering::SeqCst);
    wake.wake();
}

/// Owns the deadline thread: dropping it stops the thread and joins it, so a
/// dropped `solve` leaves nothing of its own running.
struct Deadline {
    stop: Arc<Stop>,
    handle: Option<JoinHandle<()>>,
}

impl Deadline {
    fn start(wake: Arc<Wake>, end: Instant) -> Deadline {
        let stop = Arc::new(Stop::new());
        let inner = Arc::clone(&stop);
        let handle = std::thread::spawn(move || watch_deadline(wake, inner, end));
        Deadline {
            stop,
            handle: Some(handle),
        }
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        self.stop.set();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let end = Instant::now()
        .checked_add(deadline)
        .unwrap_or_else(Instant::now);
    let wake = Arc::new(Wake::new());
    let timer = Deadline::start(Arc::clone(&wake), end);

    // Each `fetch` future borrows the handle, and every such future must be
    // `'static`, so it is driven through a shared clone rather than a borrow of
    // the binding above.
    let fetch = Arc::new(fetch);

    let mut queue: VecDeque<u32> = ids.into_iter().collect();
    let mut sum: u64 = 0;
    // Each entry is one in-flight `fetch` future; the futures are owned here,
    // so dropping `solve` drops every one of them.
    let mut live: Vec<(u32, FetchFuture)> = Vec::new();

    let outcome = poll_fn(|cx: &mut Context<'_>| {
        wake.arm(cx);

        // Take every answer that is already waiting.
        let mut i = 0;
        while i < live.len() {
            match live[i].1.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => {
                    sum += value;
                    live.swap_remove(i);
                }
                Poll::Ready(Err(_)) => {
                    let id = live[i].0;
                    // A failure is observed: resolve, and start nothing more.
                    return Poll::Ready(Err(SolveError::Fetch { id }));
                }
                Poll::Pending => i += 1,
            }
        }

        if live.is_empty() && queue.is_empty() {
            return Poll::Ready(Ok(std::mem::take(&mut sum)));
        }

        if wake.expired() || Instant::now() >= end {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        // Top the fan-out back up to the bound.
        while live.len() < MAX_IN_FLIGHT {
            match queue.pop_front() {
                Some(id) => {
                    let handle = Arc::clone(&fetch);
                    let fut: FetchFuture = Box::pin(async move { handle.fetch(id).await });
                    live.push((id, fut));
                }
                None => break,
            }
        }

        Poll::Pending
    })
    .await;

    drop(timer);
    outcome
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// The pipeline is a fan-out of two independent fetches, a combine that needs
/// both of them, and a publish that needs the combine.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").map_err(|_| PipelineError::Cancelled)?;
    let scope = Scope::root(tenant);

    // Records the first stage that failed, so a failed run can name it without
    // depending on where `each` located the error.
    let failure: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));

    let inner = scope.clone();

    let body = {
        let stage = stage.clone();
        let failure = Arc::clone(&failure);
        async move {
            let fan_stage = stage.clone();
            let fan_failure = Arc::clone(&failure);
            let scope = inner;

            let fetched = each(
                &scope,
                "fetch",
                None,
                [(0usize, StageName::FetchA), (1usize, StageName::FetchB)],
                move |_child, (index, name)| {
                    let stage = fan_stage.clone();
                    let failure = Arc::clone(&fan_failure);
                    async move {
                        stage
                            .run(name)
                            .await
                            .map_err(|_| {
                                let mut guard = failure
                                    .lock()
                                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                                if guard.is_none() {
                                    *guard = Some(name);
                                }
                                FlowError::failed("fetch stage failed")
                            })
                    }
                },
            )
            .await;

            fetched?;

            let _combined = stage.run(StageName::Combine).await.map_err(|_| {
                let mut guard = failure
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                if guard.is_none() {
                    *guard = Some(StageName::Combine);
                }
                FlowError::failed("combine stage failed")
            })?;

            stage
                .run(StageName::Publish)
                .await
                .map_err(|_| {
                    let mut guard = failure
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner());
                    if guard.is_none() {
                        *guard = Some(StageName::Publish);
                    }
                    FlowError::failed("publish stage failed")
                })
                .map(Published::from)
        }
    };

    match within(&scope, "run", deadline, body).await {
        Ok(published) => Ok(published),
        Err(error) => {
            if matches!(error, FlowError::TimedOut { .. }) {
                return Err(PipelineError::Deadline);
            }
            if error.is_cancelled() {
                return Err(PipelineError::Cancelled);
            }
            let name = {
                let mut guard = failure
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                guard.take()
            };
            match name {
                Some(name) => Err(PipelineError::Stage { name }),
                None => Err(PipelineError::Cancelled),
            }
        }
    }
}

use std::future::Future;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

/// How long the deadline thread sleeps between stop/expiry checks. Small enough
/// that a dropped `solve` tears the timer down promptly, large enough that the
/// thread costs nothing measurable.
const TIMER_SLICE: Duration = Duration::from_micros(200);
/// Used only if a `Duration` cannot be added to the current instant at all.
const FAR_FUTURE: Duration = Duration::from_secs(31_536_000);

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// An owned absolute deadline.
///
/// The timer thread is started lazily, only once something is actually pending,
/// and it is joined in `Drop`, so a `solve` future that is dropped mid-run takes
/// every thread it created down with it and leaves nothing running.
struct Deadline {
    target: Instant,
    stop: Arc<AtomicBool>,
    fired: Arc<AtomicBool>,
    waker: Arc<Mutex<Option<Waker>>>,
    worker: Mutex<Option<JoinHandle<()>>>,
}

impl Deadline {
    fn new(limit: Duration) -> Self {
        let now = Instant::now();
        let target = now
            .checked_add(limit)
            .unwrap_or_else(|| now + FAR_FUTURE);
        Deadline {
            target,
            stop: Arc::new(AtomicBool::new(false)),
            fired: Arc::new(AtomicBool::new(false)),
            waker: Arc::new(Mutex::new(None)),
            worker: Mutex::new(None),
        }
    }

    fn expired(&self) -> bool {
        self.fired.load(Ordering::SeqCst) || Instant::now() >= self.target
    }

    fn has_worker(&self) -> bool {
        lock(&self.worker).is_some()
    }

    fn ensure_worker(&self) {
        let mut slot = lock(&self.worker);
        if slot.is_some() {
            return;
        }
        let stop = Arc::clone(&self.stop);
        let fired = Arc::clone(&self.fired);
        let waker = Arc::clone(&self.waker);
        let target = self.target;
        let spawned = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || loop {
                if stop.load(Ordering::SeqCst) {
                    return;
                }
                let now = Instant::now();
                if now >= target {
                    fired.store(true, Ordering::SeqCst);
                    if let Some(waker) = lock(&waker).take() {
                        waker.wake();
                    }
                    return;
                }
                let left = target - now;
                std::thread::sleep(if left < TIMER_SLICE { left } else { TIMER_SLICE });
            });
        if let Ok(handle) = spawned {
            *slot = Some(handle);
        }
    }

    /// Arrange to be polled again when the deadline passes.
    fn arm(&self, cx: &Context<'_>) {
        if self.expired() {
            cx.waker().wake_by_ref();
            return;
        }
        self.ensure_worker();
        if !self.has_worker() {
            // No timer thread available: re-poll ourselves so the deadline is
            // still observed rather than stalling forever.
            cx.waker().wake_by_ref();
            return;
        }
        *lock(&self.waker) = Some(cx.waker().clone());
        if self.expired() {
            // The timer may have fired before the waker was recorded.
            cx.waker().wake_by_ref();
        }
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(handle) = lock(&self.worker).take() {
            let _ = handle.join();
        }
    }
}

/// Await one stage under the overall deadline.
///
/// The stage future is owned by this future: dropping it drops the stage.
async fn guarded<T, F>(deadline: &Deadline, stage: F) -> Result<T, PipelineError>
where
    F: Future<Output = T>,
{
    let mut stage = Box::pin(stage);
    std::future::poll_fn(move |cx| {
        if deadline.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match stage.as_mut().poll(cx) {
            Poll::Ready(value) => Poll::Ready(Ok(value)),
            Poll::Pending => {
                deadline.arm(cx);
                if deadline.expired() {
                    Poll::Ready(Err(PipelineError::Deadline))
                } else {
                    Poll::Pending
                }
            }
        }
    })
    .await
}

/// Drive `a` and `b` concurrently until both have produced a value.
///
/// Either side finishing is not success: the caller passes `a_ok`/`b_ok` to say
/// which completion counts. The first side that is not ok ends the pair, and the
/// other future is dropped on the spot.
async fn pair<A, B, FA, FB>(
    deadline: &Deadline,
    a: A,
    b: B,
    a_ok: FA,
    b_ok: FB,
) -> Result<(A::Output, B::Output), PipelineError>
where
    A: Future,
    B: Future,
    FA: Fn(&A::Output) -> bool,
    FB: Fn(&B::Output) -> bool,
{
    let mut a = Box::pin(a);
    let mut b = Box::pin(b);
    let mut left: Option<A::Output> = None;
    let mut right: Option<B::Output> = None;
    std::future::poll_fn(move |cx| {
        if deadline.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if left.is_none() {
            if let Poll::Ready(value) = a.as_mut().poll(cx) {
                if !a_ok(&value) {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchA,
                    }));
                }
                left = Some(value);
            } else {
                deadline.arm(cx);
            }
        }
        if right.is_none() {
            if let Poll::Ready(value) = b.as_mut().poll(cx) {
                if !b_ok(&value) {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchB,
                    }));
                }
                right = Some(value);
            } else {
                deadline.arm(cx);
            }
        }
        if left.is_some() && right.is_some() {
            return Poll::Ready(Ok((
                left.take().expect("left is present"),
                right.take().expect("right is present"),
            )));
        }
        if deadline.expired() {
            Poll::Ready(Err(PipelineError::Deadline))
        } else {
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let limit = Deadline::new(deadline);

    let (a, b) = pair(
        &limit,
        stage.run(StageName::FetchA),
        stage.run(StageName::FetchB),
        |value| value.is_ok(),
        |value| value.is_ok(),
    )
    .await?;
    a.map_err(|_| PipelineError::Stage {
        name: StageName::FetchA,
    })?;
    b.map_err(|_| PipelineError::Stage {
        name: StageName::FetchB,
    })?;

    let combined = guarded(&limit, stage.run(StageName::Combine)).await?;
    let combined = combined.map_err(|_| PipelineError::Stage {
        name: StageName::Combine,
    })?;

    let published = guarded(&limit, stage.run(StageName::Publish)).await?;
    let published = published.map_err(|_| PipelineError::Stage {
        name: StageName::Publish,
    })?;

    Ok(Published::from(published))
}

//! A fan-in pipeline over a harness [`Stage`]: `fetch_a` and `fetch_b` run
//! concurrently, `combine` needs both, `publish` needs `combine`, and the whole
//! thing is bounded by one overall deadline.
//!
//! Every resource the pipeline owns is the caller's: the stage futures live in
//! the future returned by [`solve`], and the deadline timer's thread is joined
//! by that future's `Drop`. Dropping the future mid-run therefore cancels the
//! in-flight stages and leaves no thread behind.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

/// Why the pipeline did not produce a [`Published`].
#[derive(Debug)]
pub enum PipelineError {
    /// A stage failed; `name` is the stage that failed and no later stage ran.
    Stage { name: StageName },
    /// The overall deadline elapsed; no later stage was started.
    Deadline,
    /// The run was cancelled.
    Cancelled,
}

/// Run `stage` through the pipeline, bounded by `deadline`.
///
/// On success the artifact returned by `publish` is handed back as a
/// [`Published`]. A failing fetch stops the pipeline and names itself. Passing
/// the deadline stops the pipeline and drops whatever stage was in flight.
pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let at = Instant::now().checked_add(deadline);

    let body = async {
        check(at)?;
        let (_a, _b) = both(
            async {
                stage
                    .run(StageName::FetchA)
                    .await
                    .map_err(|_| PipelineError::Stage { name: StageName::FetchA })
            },
            async {
                stage
                    .run(StageName::FetchB)
                    .await
                    .map_err(|_| PipelineError::Stage { name: StageName::FetchB })
            },
        )
        .await?;
        check(at)?;
        let _combined = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;
        check(at)?;
        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;
        Ok(Published::from(published))
    };

    match at {
        Some(at) => match race(body, Deadline::new(at)).await {
            Either::Left(result) => result,
            Either::Right(()) => Err(PipelineError::Deadline),
        },
        // The deadline is so far out that the clock cannot hold it; run bare.
        None => body.await,
    }
}

/// Refuse to start the next stage once the overall deadline has passed.
fn check(at: Option<Instant>) -> Result<(), PipelineError> {
    match at {
        Some(at) if Instant::now() >= at => Err(PipelineError::Deadline),
        _ => Ok(()),
    }
}

/// Drive both fetches at once, failing fast on whichever fails first.
///
/// The loser's future is dropped as this call returns, so a failed fetch leaves
/// no other fetch running and starts nothing downstream.
async fn both<A, B, FA, FB>(fa: FA, fb: FB) -> Result<(A, B), PipelineError>
where
    FA: Future<Output = Result<A, PipelineError>>,
    FB: Future<Output = Result<B, PipelineError>>,
{
    let mut fa = Box::pin(fa);
    let mut fb = Box::pin(fb);
    let mut a: Option<A> = None;
    let mut b: Option<B> = None;

    poll_fn(move |cx| {
        if a.is_none() {
            match fa.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => a = Some(value),
                Poll::Ready(Err(err)) => return Poll::Ready(Err(err)),
                Poll::Pending => {}
            }
        }
        if b.is_none() {
            match fb.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => b = Some(value),
                Poll::Ready(Err(err)) => return Poll::Ready(Err(err)),
                Poll::Pending => {}
            }
        }
        if a.is_some() && b.is_some() {
            return Poll::Ready(Ok((
                a.take().expect("a is set"),
                b.take().expect("b is set"),
            )));
        }
        Poll::Pending
    })
    .await
}

enum Either<A, B> {
    Left(A),
    Right(B),
}

/// Poll both futures until one finishes; dropping the result drops both.
async fn race<A: Future, B: Future>(left: A, right: B) -> Either<A::Output, B::Output> {
    let mut left = Box::pin(left);
    let mut right = Box::pin(right);

    poll_fn(move |cx| {
        if let Poll::Ready(value) = left.as_mut().poll(cx) {
            return Poll::Ready(Either::Left(value));
        }
        if let Poll::Ready(value) = right.as_mut().poll(cx) {
            return Poll::Ready(Either::Right(value));
        }
        Poll::Pending
    })
    .await
}

struct TimerState {
    at: Instant,
    fired: AtomicBool,
    stopped: AtomicBool,
    waker: Mutex<Option<Waker>>,
    gate: Mutex<()>,
    cv: Condvar,
}

impl TimerState {
    /// Sleep until `at`, or until stopped, then publish a wake.
    fn run(self: Arc<Self>) {
        let mut gate = lock(&self.gate);
        loop {
            if self.stopped.load(Ordering::SeqCst) {
                return;
            }
            let remaining = match self.at.checked_duration_since(Instant::now()) {
                Some(remaining) if !remaining.is_zero() => remaining,
                _ => break,
            };
            let waited = match self.cv.wait_timeout(gate, remaining) {
                Ok(waited) => waited,
                Err(poisoned) => poisoned.into_inner(),
            };
            gate = waited.0;
            if waited.1.timed_out() {
                break;
            }
        }
        drop(gate);
        self.fired.store(true, Ordering::SeqCst);
        if let Some(waker) = lock(&self.waker).take() {
            waker.wake();
        }
    }
}

/// A future that becomes ready at `at`, backed by a thread that owns nothing
/// but the wait. `Drop` stops the thread and joins it, so a dropped deadline
/// leaves no live resource behind.
struct Deadline {
    state: Arc<TimerState>,
    handle: Option<JoinHandle<()>>,
}

impl Deadline {
    fn new(at: Instant) -> Self {
        Deadline {
            state: Arc::new(TimerState {
                at,
                fired: AtomicBool::new(false),
                stopped: AtomicBool::new(false),
                waker: Mutex::new(None),
                gate: Mutex::new(()),
                cv: Condvar::new(),
            }),
            handle: None,
        }
    }
}

impl Future for Deadline {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if this.state.fired.load(Ordering::SeqCst) || Instant::now() >= this.state.at {
            this.state.fired.store(true, Ordering::SeqCst);
            return Poll::Ready(());
        }
        if this.handle.is_none() {
            let worker = Arc::clone(&this.state);
            this.handle = Some(
                thread::Builder::new()
                    .name("pipeline-deadline".to_owned())
                    .spawn(move || worker.run())
                    .expect("spawn the pipeline deadline timer"),
            );
        }
        *lock(&this.state.waker) = Some(cx.waker().clone());
        if this.state.fired.load(Ordering::SeqCst) {
            return Poll::Ready(());
        }
        Poll::Pending
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        self.state.stopped.store(true, Ordering::SeqCst);
        self.state.cv.notify_all();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

//! Explicit-ownership pipeline: every stage the future owns is dropped with it,
//! every fallible call is handled here, and the deadline is enforced by a
//! watchdog thread that wakes this task when the deadline elapses.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Polls two independent futures on the task that awaits them and owns both.
/// Dropping the `Join` drops both in-flight stage futures, so no stage work
/// outlives the call.
struct Join<A: Future, B: Future> {
    left: Option<Pin<Box<A>>>,
    right: Option<Pin<Box<B>>>,
    left_out: Option<A::Output>,
    right_out: Option<B::Output>,
}

impl<A: Future, B: Future> Join<A, B> {
    fn new(left: A, right: B) -> Self {
        Join {
            left: Some(Box::pin(left)),
            right: Some(Box::pin(right)),
            left_out: None,
            right_out: None,
        }
    }
}

// Every pinned future lives behind its own `Box`, so moving the `Join` never
// moves pinned data.
impl<A: Future, B: Future> Unpin for Join<A, B> {}

impl<A: Future, B: Future> Future for Join<A, B> {
    type Output = (A::Output, B::Output);

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.left_out.is_none() {
            if let Some(mut left) = this.left.take() {
                if let Poll::Ready(out) = left.as_mut().poll(cx) {
                    this.left_out = Some(out);
                } else {
                    this.left = Some(left);
                }
            }
        }

        if this.right_out.is_none() {
            if let Some(mut right) = this.right.take() {
                if let Poll::Ready(out) = right.as_mut().poll(cx) {
                    this.right_out = Some(out);
                } else {
                    this.right = Some(right);
                }
            }
        }

        match (this.left_out.take(), this.right_out.take()) {
            (Some(left), Some(right)) => Poll::Ready((left, right)),
            (Some(left), None) => {
                this.left_out = Some(left);
                Poll::Pending
            }
            (None, Some(right)) => {
                this.right_out = Some(right);
                Poll::Pending
            }
            (None, None) => Poll::Pending,
        }
    }
}

struct TimerState {
    waker: Option<Waker>,
}

struct TimerInner {
    state: Mutex<TimerState>,
    signal: Condvar,
}

impl TimerInner {
    fn lock(&self) -> MutexGuard<'_, TimerState> {
        self.state.lock().unwrap_or_else(|err| err.into_inner())
    }
}

/// Deadline watch owned by the `solve` future. Its watchdog thread sleeps until
/// the deadline and wakes the task's waker; dropping the watch stops the thread.
struct Deadline {
    at: Instant,
    inner: Arc<TimerInner>,
    stop: Arc<AtomicBool>,
}

impl Deadline {
    fn start(at: Instant) -> Deadline {
        let inner = Arc::new(TimerInner {
            state: Mutex::new(TimerState { waker: None }),
            signal: Condvar::new(),
        });
        let stop = Arc::new(AtomicBool::new(false));

        let worker_inner = Arc::clone(&inner);
        let worker_stop = Arc::clone(&stop);
        // If the OS refuses the thread, the deadline is still enforced by the
        // `expired()` checks on this task; there is no error to recover from.
        let _ = std::thread::Builder::new()
            .name(String::from("pipeline-deadline"))
            .spawn(move || watchdog(&worker_inner, &worker_stop, at));

        Deadline { at, inner, stop }
    }

    fn expired(&self) -> bool {
        Instant::now() >= self.at
    }

    fn prime(&self, waker: &Waker) {
        let mut state = self.inner.lock();
        state.waker = Some(waker.clone());
        self.inner.signal.notify_all();
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        let mut state = self.inner.lock();
        state.waker = None;
        self.inner.signal.notify_all();
    }
}

fn watchdog(inner: &TimerInner, stop: &AtomicBool, at: Instant) {
    loop {
        if stop.load(Ordering::SeqCst) {
            return;
        }
        let state = inner.lock();
        if stop.load(Ordering::SeqCst) {
            return;
        }
        let now = Instant::now();
        if now >= at {
            let waker = state.waker.clone();
            drop(state);
            if let Some(waker) = waker {
                waker.wake();
            }
            return;
        }
        if state.waker.is_none() {
            let (state, _) = inner
                .signal
                .wait_timeout(state, Duration::from_millis(1))
                .unwrap_or_else(|err| err.into_inner());
            drop(state);
            continue;
        }
        let (state, _) = inner
            .signal
            .wait_timeout(state, at - now)
            .unwrap_or_else(|err| err.into_inner());
        drop(state);
    }
}

/// Primes the watchdog with the current task waker (so the deadline can wake
/// this task) and fails if the deadline has already passed. Ready immediately.
async fn checkpoint(watch: &Deadline) -> Result<(), PipelineError> {
    poll_fn(|cx| {
        watch.prime(cx.waker());
        Poll::Ready(())
    })
    .await;
    if watch.expired() {
        return Err(PipelineError::Deadline);
    }
    Ok(())
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let watch = Deadline::start(Instant::now() + deadline);
    checkpoint(&watch).await?;

    let (fetch_a, fetch_b) = Join::new(
        stage.run(StageName::FetchA),
        stage.run(StageName::FetchB),
    )
    .await;
    checkpoint(&watch).await?;

    let _artifact_a = match fetch_a {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::FetchA,
            })
        }
    };
    let _artifact_b = match fetch_b {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::FetchB,
            })
        }
    };

    let combined = stage.run(StageName::Combine).await;
    checkpoint(&watch).await?;
    let _combined = match combined {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            })
        }
    };

    let published = stage.run(StageName::Publish).await;
    checkpoint(&watch).await?;
    match published {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

use std::future::{poll_fn, Future};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct Signal {
    ready: Mutex<bool>,
    cv: Condvar,
}

impl Signal {
    fn new() -> Self {
        Signal { ready: Mutex::new(false), cv: Condvar::new() }
    }

    fn signal(self: &Arc<Self>) {
        if let Ok(mut g) = self.ready.lock() {
            *g = true;
            self.cv.notify_one();
        }
    }

    fn park(&self) {
        if let Ok(mut g) = self.ready.lock() {
            while !*g {
                g = self.cv.wait(g).unwrap();
            }
            *g = false;
        }
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        Signal::signal(&self);
    }
    fn wake_by_ref(self: &Arc<Self>) {
        Signal::signal(self);
    }
}

/// Poll `fut` to completion on this thread, giving up at `end`.
/// `None` means the deadline passed; the future (and everything it owns) is
/// dropped before returning, so nothing survives the call.
fn drive<F: Future>(fut: F, end: Instant) -> Option<F::Output> {
    let mut fut = Box::pin(fut);
    let sig = Arc::new(Signal::new());
    let waker = Waker::from(sig.clone());
    let mut cx = Context::from_waker(&waker);
    loop {
        if Instant::now() >= end {
            return None;
        }
        if let Poll::Ready(v) = fut.as_mut().poll(&mut cx) {
            return Some(v);
        }
        if Instant::now() >= end {
            return None;
        }
        sig.park();
    }
}

/// Poll two futures to completion concurrently; both are dropped with us.
async fn join<A: Future, B: Future>(a: A, b: B) -> (A::Output, B::Output) {
    let mut a = Box::pin(a);
    let mut b = Box::pin(b);
    let mut a_out: Option<A::Output> = None;
    let mut b_out: Option<B::Output> = None;
    poll_fn(move |cx| {
        if a_out.is_none() {
            if let Poll::Ready(v) = a.as_mut().poll(cx) {
                a_out = Some(v);
            }
        }
        if b_out.is_none() {
            if let Poll::Ready(v) = b.as_mut().poll(cx) {
                b_out = Some(v);
            }
        }
        let (x, y) = (a_out.take(), b_out.take());
        match (x, y) {
            (Some(x), Some(y)) => Poll::Ready((x, y)),
            (x, y) => {
                a_out = x;
                b_out = y;
                Poll::Pending
            }
        }
    })
    .await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let end = Instant::now() + deadline;
    let stage = Arc::new(stage);

    drive(
        async move {
            let s1 = stage.clone();
            let fetch_a = async move {
                s1.run(StageName::FetchA)
                    .await
                    .map_err(|_| PipelineError::Stage { name: StageName::FetchA })
            };
            let s2 = stage.clone();
            let fetch_b = async move {
                s2.run(StageName::FetchB)
                    .await
                    .map_err(|_| PipelineError::Stage { name: StageName::FetchB })
            };
            let (a, b) = join(fetch_a, fetch_b).await;
            let (_a, _b) = (a?, b?);

            let _combined = stage
                .run(StageName::Combine)
                .await
                .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

            stage
                .run(StageName::Publish)
                .await
                .map(Published::from)
                .map_err(|_| PipelineError::Stage { name: StageName::Publish })
        },
        end,
    )
    .unwrap_or(Err(PipelineError::Deadline))
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct Signal {
    woken: Mutex<bool>,
    cv: Condvar,
}

impl Signal {
    fn new() -> Arc<Signal> {
        Arc::new(Signal {
            woken: Mutex::new(false),
            cv: Condvar::new(),
        })
    }

    fn fire(&self) {
        if let Ok(mut g) = self.woken.lock() {
            *g = true;
            self.cv.notify_all();
        }
    }

    fn clear(&self) {
        if let Ok(mut g) = self.woken.lock() {
            *g = false;
        }
    }

    fn wait_until(&self, end: Instant) {
        let mut g = match self.woken.lock() {
            Ok(g) => g,
            Err(_) => return,
        };
        loop {
            if *g {
                return;
            }
            let now = Instant::now();
            if now >= end {
                return;
            }
            match self.cv.wait_timeout(g, end - now) {
                Ok((ng, _)) => g = ng,
                Err(_) => return,
            }
        }
    }
}

struct Flag(Arc<Signal>);

impl Wake for Flag {
    fn wake(self: Arc<Self>) {
        self.0.fire();
    }
    fn wake_by_ref(self: &Arc<Self>) {
        self.0.fire();
    }
}

fn run_all<'a, T>(
    mut futs: Vec<Pin<Box<dyn Future<Output = T> + 'a>>>,
    end: Instant,
) -> Result<Vec<T>, PipelineError> {
    let mut left = futs.len();
    if left == 0 {
        return Ok(Vec::new());
    }
    let sig = Signal::new();
    let waker = Waker::from(Arc::new(Flag(sig.clone())));
    let mut cx = Context::from_waker(&waker);
    let mut outs: Vec<Option<T>> = (0..futs.len()).map(|_| None).collect();

    while left > 0 {
        sig.clear();
        for (i, f) in futs.iter_mut().enumerate() {
            if outs[i].is_some() {
                continue;
            }
            if let Poll::Ready(v) = f.as_mut().poll(&mut cx) {
                outs[i] = Some(v);
                left -= 1;
            }
        }
        if left == 0 {
            break;
        }
        if Instant::now() >= end {
            return Err(PipelineError::Deadline);
        }
        sig.wait_until(end);
    }

    Ok(outs.into_iter().filter_map(|o| o).collect())
}

fn fetch<'a>(
    stage: &'a Stage,
    name: StageName,
) -> Pin<Box<dyn Future<Output = Result<Artifact, PipelineError>> + 'a>> {
    Box::pin(async move {
        match stage.run(name).await {
            Ok(a) => Ok(a),
            Err(_) => Err(PipelineError::Stage { name }),
        }
    })
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let end = Instant::now() + deadline;

    let fetches = run_all(
        vec![
            fetch(&stage, StageName::FetchA),
            fetch(&stage, StageName::FetchB),
        ],
        end,
    )?;
    for f in fetches {
        f?;
    }

    let mut combined = run_all(vec![fetch(&stage, StageName::Combine)], end)?;
    let _ = combined.remove(0)?;

    let mut published = run_all(vec![fetch(&stage, StageName::Publish)], end)?;
    Ok(Published::from(published.remove(0)?))
}

//! A four-stage pipeline: `fetch_a` and `fetch_b` concurrently, then
//! `combine`, then `publish` -- all under one overall deadline, and owned by
//! the future returned from `solve` so that dropping it stops the work.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

/// Why a pipeline did not produce a [`Published`] value.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error; `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline elapsed before the pipeline finished.
    Deadline,
    /// The pipeline stopped without a stage result.
    Cancelled,
}

/// Run the pipeline for `stage` under `deadline`.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match until(deadline, pipeline(&stage)).await {
        // The stages settled in time: their own verdict is the answer.
        Ok(settled) => settled,
        // The deadline fired first, and dropped the pipeline.
        Err(blown) => Err(blown),
    }
}

/// The stages themselves, in order.
async fn pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    {
        // `combine` may only start once both fetches have succeeded; the
        // fetch futures are dropped at the end of this block.
        let (_a, _b) = fetch_both(stage).await?;
    }
    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;
    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;
    Ok(Published::from(published))
}

/// Drive both fetches in the same task, failing fast on the first error.
async fn fetch_both(stage: &Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut fetch_a = Box::pin(stage.run(StageName::FetchA));
    let mut fetch_b = Box::pin(stage.run(StageName::FetchB));
    let mut a: Option<Result<Artifact, StageError>> = None;
    let mut b: Option<Result<Artifact, StageError>> = None;
    let mut failed: Option<StageName> = None;

    poll_fn(|cx| {
        if failed.is_none() {
            if a.is_none() {
                if let Poll::Ready(value) = fetch_a.as_mut().poll(cx) {
                    if value.is_err() {
                        failed = Some(StageName::FetchA);
                    }
                    a = Some(value);
                }
            }
            if b.is_none() && failed.is_none() {
                if let Poll::Ready(value) = fetch_b.as_mut().poll(cx) {
                    if value.is_err() {
                        failed = Some(StageName::FetchB);
                    }
                    b = Some(value);
                }
            }
        }
        if failed.is_some() || (a.is_some() && b.is_some()) {
            Poll::Ready(())
        } else {
            Poll::Pending
        }
    })
    .await;

    // A fetch that has not settled stops here rather than outliving us.
    drop(fetch_a);
    drop(fetch_b);

    match failed {
        Some(name) => Err(PipelineError::Stage { name }),
        None => match (a, b) {
            (Some(Ok(a)), Some(Ok(b))) => Ok((a, b)),
            _ => Err(PipelineError::Cancelled),
        },
    }
}

/// Race `work` against a wall-clock deadline.
///
/// The deadline wins ties, and when it wins, `work` is dropped before this
/// returns, so no stage is still running once `solve` has answered.
async fn until<F: Future>(limit: Duration, work: F) -> Result<F::Output, PipelineError> {
    let mut timer = Box::pin(Deadline::after(limit));
    let mut work = Box::pin(work);
    poll_fn(move |cx| {
        if timer.as_mut().poll(cx).is_ready() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match work.as_mut().poll(cx) {
            Poll::Ready(value) => Poll::Ready(Ok(value)),
            Poll::Pending => Poll::Pending,
        }
    })
    .await
}

struct TimerState {
    at: Instant,
    fired: bool,
    stop: bool,
    waker: Option<Waker>,
}

/// A future that completes once the deadline passes.
///
/// A helper thread parks on a condvar until the deadline (or an early stop)
/// and wakes the task; the timer itself is dropped, and its thread released,
/// as soon as the pipeline settles or its owner goes away.
struct Deadline {
    shared: Arc<(Mutex<TimerState>, Condvar)>,
}

impl Deadline {
    fn after(limit: Duration) -> Self {
        let now = Instant::now();
        let shared = Arc::new((
            Mutex::new(TimerState {
                at: now.checked_add(limit).unwrap_or(now),
                fired: false,
                stop: false,
                waker: None,
            }),
            Condvar::new(),
        ));

        let worker = Arc::clone(&shared);
        std::thread::spawn(move || {
            let (lock, cv) = &*worker;
            let waker = {
                let mut state = lock.lock().unwrap_or_else(|error| error.into_inner());
                loop {
                    if state.stop || state.fired {
                        break None;
                    }
                    let now = Instant::now();
                    if now >= state.at {
                        state.fired = true;
                        break state.waker.take();
                    }
                    let remaining = state.at - now;
                    let (next, _) = cv
                        .wait_timeout(state, remaining)
                        .unwrap_or_else(|error| error.into_inner());
                    state = next;
                }
            };
            // Wake outside the lock so the task may re-poll and lock again.
            if let Some(waker) = waker {
                waker.wake();
            }
        });

        Deadline { shared }
    }
}

impl Future for Deadline {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let (lock, _) = &*self.shared;
        let mut state = lock.lock().unwrap_or_else(|error| error.into_inner());
        if state.fired || state.stop || Instant::now() >= state.at {
            state.fired = true;
            state.waker = None;
            return Poll::Ready(());
        }
        let replace = match &state.waker {
            Some(waker) => !waker.will_wake(cx.waker()),
            None => true,
        };
        if replace {
            state.waker = Some(cx.waker().clone());
        }
        Poll::Pending
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        let (lock, cv) = &*self.shared;
        let mut state = lock.lock().unwrap_or_else(|error| error.into_inner());
        state.stop = true;
        state.waker = None;
        cv.notify_all();
    }
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageFuture<'a> = Pin<Box<dyn Future<Output = Result<Artifact, StageError>> + 'a>>;

struct Budget {
    at: Instant,
    fired: Arc<AtomicBool>,
    stop: Arc<(Mutex<bool>, Condvar)>,
    slot: Arc<Mutex<Option<Waker>>>,
}

impl Budget {
    fn new(limit: Duration) -> Budget {
        let fired = Arc::new(AtomicBool::new(false));
        let stop = Arc::new((Mutex::new(false), Condvar::new()));
        let slot: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
        let start = Instant::now();
        let at = start
            .checked_add(limit)
            .unwrap_or_else(|| start + Duration::from_secs(86_400));

        let thread_fired = Arc::clone(&fired);
        let thread_stop = Arc::clone(&stop);
        let thread_slot = Arc::clone(&slot);
        let thread_at = at;

        let _ = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || {
                let (lock, cv) = &*thread_stop;
                let mut stopped = match lock.lock() {
                    Ok(g) => g,
                    Err(e) => e.into_inner(),
                };
                loop {
                    if *stopped {
                        return;
                    }
                    let now = Instant::now();
                    if now >= thread_at {
                        break;
                    }
                    let (guard, _timed_out) = match cv.wait_timeout(stopped, thread_at - now) {
                        Ok(pair) => pair,
                        Err(e) => e.into_inner(),
                    };
                    stopped = guard;
                }
                if *stopped {
                    return;
                }
                thread_fired.store(true, Ordering::SeqCst);
                let waker = match thread_slot.lock() {
                    Ok(mut guard) => guard.take(),
                    Err(e) => e.into_inner().take(),
                };
                if let Some(waker) = waker {
                    waker.wake();
                }
            });

        Budget {
            at,
            fired,
            stop,
            slot,
        }
    }

    fn expired(&self) -> bool {
        self.fired.load(Ordering::SeqCst) || Instant::now() >= self.at
    }

    fn arm(&self, waker: &Waker) {
        match self.slot.lock() {
            Ok(mut guard) => *guard = Some(waker.clone()),
            Err(e) => *e.into_inner() = Some(waker.clone()),
        }
    }
}

impl Drop for Budget {
    fn drop(&mut self) {
        if let Ok(mut guard) = self.stop.0.lock() {
            *guard = true;
        }
        self.stop.1.notify_all();
    }
}

async fn fetch_both(
    stage: &Stage,
    budget: &Budget,
) -> Result<(Artifact, Artifact), PipelineError> {
    let mut a: StageFuture<'_> = Box::pin(stage.run(StageName::FetchA));
    let mut b: StageFuture<'_> = Box::pin(stage.run(StageName::FetchB));
    let mut ra: Option<Result<Artifact, StageError>> = None;
    let mut rb: Option<Result<Artifact, StageError>> = None;

    poll_fn(|cx| {
        budget.arm(cx.waker());
        if budget.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if ra.is_none() {
            if let Poll::Ready(result) = a.as_mut().poll(cx) {
                ra = Some(result);
            }
        }
        if rb.is_none() {
            if let Poll::Ready(result) = b.as_mut().poll(cx) {
                rb = Some(result);
            }
        }
        if ra.is_some() && rb.is_some() {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    })
    .await?;

    let a = ra.expect("fetch_a settled");
    let b = rb.expect("fetch_b settled");
    match (a, b) {
        (Ok(a), Ok(b)) => Ok((a, b)),
        (Err(_), Ok(_)) => Err(PipelineError::Stage {
            name: StageName::FetchA,
        }),
        (_, Err(_)) => Err(PipelineError::Stage {
            name: StageName::FetchB,
        }),
    }
}

async fn run_stage(
    stage: &Stage,
    name: StageName,
    budget: &Budget,
) -> Result<Artifact, PipelineError> {
    let mut fut: StageFuture<'_> = Box::pin(stage.run(name));
    poll_fn(|cx| {
        budget.arm(cx.waker());
        if budget.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match fut.as_mut().poll(cx) {
            Poll::Pending => Poll::Pending,
            Poll::Ready(Ok(artifact)) => Poll::Ready(Ok(artifact)),
            Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage { name })),
        }
    })
    .await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let budget = Budget::new(deadline);

    let (_a, _b) = fetch_both(&stage, &budget).await?;
    let _combined = run_stage(&stage, StageName::Combine, &budget).await?;
    let published = run_stage(&stage, StageName::Publish, &budget).await?;

    Ok(Published::from(published))
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

/// Why the pipeline stopped without a published artifact.
#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type Outcome = Result<Published, PipelineError>;

/// Runs the pipeline under `deadline`.
///
/// The stages are driven on the caller's task: the returned future owns every
/// stage future it creates, so dropping it drops the in-flight stage futures on
/// the spot and no stage is left running. The deadline is enforced by a timer
/// thread that never touches the stage futures, only flips a flag and wakes
/// this future, which then drops the work and reports the expiry.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    Driver::start(stage, deadline).await
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

/// `Instant` addition can overflow; fall back to a far-future instant instead
/// of panicking.
fn expiry(limit: Duration) -> Instant {
    let now = Instant::now();
    now.checked_add(limit)
        .unwrap_or_else(|| now + Duration::from_secs(100 * 365 * 24 * 60 * 60))
}

struct Stop {
    stopped: Mutex<bool>,
    signal: Condvar,
}

/// A one-shot deadline timer. It owns no stage work: on expiry it only records
/// the fact and wakes the waiting task.
struct Timer {
    expired: Arc<AtomicBool>,
    wake: Arc<Mutex<Option<Waker>>>,
    stop: Arc<Stop>,
    handle: Option<JoinHandle<()>>,
}

impl Timer {
    fn start(limit: Duration) -> Timer {
        let deadline = expiry(limit);
        let expired = Arc::new(AtomicBool::new(false));
        let wake: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
        let stop = Arc::new(Stop {
            stopped: Mutex::new(false),
            signal: Condvar::new(),
        });

        let thread_expired = Arc::clone(&expired);
        let thread_wake = Arc::clone(&wake);
        let thread_stop = Arc::clone(&stop);
        let handle = thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || {
                loop {
                    let stopped = lock(&thread_stop.stopped);
                    if *stopped {
                        return;
                    }
                    let now = Instant::now();
                    if now >= deadline {
                        break;
                    }
                    // Spurious wake-ups just re-check the clock.
                    if let Ok((_guard, _timeout)) =
                        thread_stop.signal.wait_timeout(stopped, deadline - now)
                    {
                        // Re-loop and re-read the clock.
                    }
                }
                thread_expired.store(true, Ordering::Release);
                let waker = lock(&thread_wake).take();
                if let Some(waker) = waker {
                    waker.wake();
                }
            })
            .expect("spawn pipeline deadline thread");

        Timer {
            expired,
            wake,
            stop,
            handle: Some(handle),
        }
    }

    fn is_expired(&self) -> bool {
        self.expired.load(Ordering::Acquire)
    }

    fn set_waker(&self, waker: &Waker) {
        *lock(&self.wake) = Some(waker.clone());
    }

    fn clear_waker(&self) {
        *lock(&self.wake) = None;
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        *lock(&self.stop.stopped) = true;
        self.stop.signal.notify_all();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

struct Driver {
    work: Option<Pin<Box<dyn Future<Output = Outcome>>>>,
    timer: Option<Timer>,
}

impl Driver {
    fn start(stage: Stage, deadline: Duration) -> Driver {
        let stage = Arc::new(stage);
        let owned = Arc::clone(&stage);
        let work: Pin<Box<dyn Future<Output = Outcome>>> =
            Box::pin(async move { pipeline(owned).await });
        Driver {
            work: Some(work),
            timer: Some(Timer::start(deadline)),
        }
    }

    /// Ends the run: the stage futures are dropped first, so nothing is still
    /// running by the time this returns, and the timer thread is stopped and
    /// joined.
    fn finish(&mut self, outcome: Outcome) -> Poll<Outcome> {
        self.work = None;
        if let Some(timer) = self.timer.as_ref() {
            timer.clear_waker();
        }
        self.timer = None;
        Poll::Ready(outcome)
    }
}

impl Future for Driver {
    type Output = Outcome;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Outcome> {
        let this = self.get_mut();

        if this.timer.as_ref().map_or(false, |timer| timer.is_expired()) {
            return this.finish(Err(PipelineError::Deadline));
        }

        let polled = match this.work.as_mut() {
            Some(work) => work.as_mut().poll(cx),
            // Already finished: only reachable if polled again after `Ready`.
            None => return Poll::Ready(Err(PipelineError::Cancelled)),
        };
        if let Poll::Ready(outcome) = polled {
            return this.finish(outcome);
        }

        if let Some(timer) = this.timer.as_ref() {
            timer.set_waker(cx.waker());
            // The timer may have fired before the waker was installed; the flag
            // is what decides, so the wake-up cannot be lost.
            if timer.is_expired() {
                return this.finish(Err(PipelineError::Deadline));
            }
        }

        Poll::Pending
    }
}

async fn pipeline(stage: Arc<Stage>) -> Outcome {
    if let Err(name) = fetch_both(Arc::clone(&stage)).await {
        return Err(PipelineError::Stage { name });
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

/// Runs `fetch_a` and `fetch_b` concurrently and waits for both to succeed.
///
/// The first failure wins: it is reported immediately and the sibling is
/// dropped, so nothing runs past the failed fetch.
async fn fetch_both(stage: Arc<Stage>) -> Result<(), StageName> {
    let mut a = Box::pin(stage.run(StageName::FetchA));
    let mut b = Box::pin(stage.run(StageName::FetchB));
    let mut a_done = false;
    let mut b_done = false;
    let mut failed: Option<StageName> = None;

    poll_fn(move |cx| {
        if let Some(name) = failed {
            return Poll::Ready(Err(name));
        }

        if !a_done {
            if let Poll::Ready(result) = a.as_mut().poll(cx) {
                a_done = true;
                if result.is_err() {
                    failed = Some(StageName::FetchA);
                }
            }
        }
        if !b_done {
            if let Poll::Ready(result) = b.as_mut().poll(cx) {
                b_done = true;
                if result.is_err() {
                    failed = Some(StageName::FetchB);
                }
            }
        }

        if let Some(name) = failed {
            return Poll::Ready(Err(name));
        }
        if a_done && b_done {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    })
    .await
}

//! A self-contained pipeline driver.
//!
//! `fetch_a` and `fetch_b` are driven concurrently as futures owned by the
//! future returned by `solve`, so dropping it drops every in-flight stage
//! future with it and no stage keeps running. The overall deadline is honoured
//! by a one-shot timer thread, because a pending stage future is not obliged to
//! wake us when time is up.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageSlot<'a> = Pin<Box<dyn Future<Output = Result<Artifact, ai_task_support::StageError>> + 'a>>;

fn poll_stage(
    slot: &mut Option<StageSlot<'_>>,
    cx: &mut Context<'_>,
) -> Option<Result<Artifact, ai_task_support::StageError>> {
    let future = slot.as_mut()?;
    match future.as_mut().poll(cx) {
        Poll::Ready(value) => Some(value),
        Poll::Pending => None,
    }
}

struct Pipeline<'a> {
    stage: &'a Stage,
    fetch_a: Option<StageSlot<'a>>,
    fetch_b: Option<StageSlot<'a>>,
    a: Option<Artifact>,
    b: Option<Artifact>,
    combine: Option<StageSlot<'a>>,
    combined: Option<Artifact>,
    publish: Option<StageSlot<'a>>,
    published: Option<Artifact>,
    out: Option<Result<Published, PipelineError>>,
}

impl<'a> Pipeline<'a> {
    fn new(stage: &'a Stage) -> Self {
        Pipeline {
            stage,
            fetch_a: None,
            fetch_b: None,
            a: None,
            b: None,
            combine: None,
            combined: None,
            publish: None,
            published: None,
            out: None,
        }
    }

    fn stop(&mut self, result: Result<Published, PipelineError>) {
        self.fetch_a = None;
        self.fetch_b = None;
        self.combine = None;
        self.publish = None;
        self.out = Some(result);
    }

    fn take(&mut self) -> Option<Result<Published, PipelineError>> {
        if let Some(result) = self.out.take() {
            return Some(result);
        }
        if let Some(artifact) = self.published.take() {
            return Some(Ok(Published::from(artifact)));
        }
        None
    }

    fn poll(&mut self, cx: &mut Context<'_>) {
        if self.a.is_none() && self.b.is_none() && self.fetch_a.is_none() && self.fetch_b.is_none()
        {
            let stage: &'a Stage = self.stage;
            self.fetch_a = Some(Box::pin(stage.run(StageName::FetchA)));
            self.fetch_b = Some(Box::pin(stage.run(StageName::FetchB)));
        }

        if self.a.is_none() {
            match poll_stage(&mut self.fetch_a, cx) {
                Some(Ok(artifact)) => self.a = Some(artifact),
                Some(Err(_)) => {
                    self.stop(Err(PipelineError::Stage {
                        name: StageName::FetchA,
                    }));
                    return;
                }
                None => {}
            }
        }

        if self.b.is_none() {
            match poll_stage(&mut self.fetch_b, cx) {
                Some(Ok(artifact)) => self.b = Some(artifact),
                Some(Err(_)) => {
                    self.stop(Err(PipelineError::Stage {
                        name: StageName::FetchB,
                    }));
                    return;
                }
                None => {}
            }
        }

        if self.a.is_some() && self.b.is_some() && self.combine.is_none() {
            self.fetch_a = None;
            self.fetch_b = None;
            let stage: &'a Stage = self.stage;
            self.combine = Some(Box::pin(stage.run(StageName::Combine)));
        }

        if self.combine.is_some() && self.combined.is_none() {
            match poll_stage(&mut self.combine, cx) {
                Some(Ok(artifact)) => self.combined = Some(artifact),
                Some(Err(_)) => {
                    self.stop(Err(PipelineError::Stage {
                        name: StageName::Combine,
                    }));
                    return;
                }
                None => {}
            }
        }

        if self.combined.is_some() && self.publish.is_none() {
            self.combine = None;
            let stage: &'a Stage = self.stage;
            self.publish = Some(Box::pin(stage.run(StageName::Publish)));
        }

        if self.publish.is_some() && self.published.is_none() {
            match poll_stage(&mut self.publish, cx) {
                Some(Ok(artifact)) => self.published = Some(artifact),
                Some(Err(_)) => {
                    self.stop(Err(PipelineError::Stage {
                        name: StageName::Publish,
                    }));
                    return;
                }
                None => {}
            }
        }
    }
}

/// One-shot "the deadline is up" signal that can wake the awaiting task.
struct Signal {
    fired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

impl Signal {
    fn new() -> Self {
        Signal {
            fired: AtomicBool::new(false),
            waker: Mutex::new(None),
        }
    }

    /// Park `waker` to be woken on fire. Returns false if already fired.
    fn arm(&self, waker: &Waker) -> bool {
        let mut slot = self.waker.lock().expect("signal mutex is not poisoned");
        if self.fired.load(Ordering::SeqCst) {
            return false;
        }
        *slot = Some(waker.clone());
        true
    }

    fn fire(&self) {
        self.fired.store(true, Ordering::SeqCst);
        let waker = self.waker.lock().expect("signal mutex is not poisoned").take();
        if let Some(waker) = waker {
            waker.wake();
        }
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.fire();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.fire();
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let started = Instant::now();
    let mut pipeline = Pipeline::new(&stage);
    let signal = Arc::new(Signal::new());
    let mut timer_started = false;

    poll_fn(move |cx| {
        if let Some(done) = pipeline.take() {
            return Poll::Ready(done);
        }

        if started.elapsed() >= deadline {
            pipeline.stop(Err(PipelineError::Deadline));
            return Poll::Ready(
                pipeline
                    .take()
                    .expect("stopping the pipeline records a result"),
            );
        }

        pipeline.poll(cx);

        if let Some(done) = pipeline.take() {
            return Poll::Ready(done);
        }

        if started.elapsed() >= deadline {
            pipeline.stop(Err(PipelineError::Deadline));
            return Poll::Ready(
                pipeline
                    .take()
                    .expect("stopping the pipeline records a result"),
            );
        }

        if !timer_started {
            timer_started = true;
            let remaining = deadline.saturating_sub(started.elapsed());
            let timer_signal = Arc::clone(&signal);
            std::thread::spawn(move || {
                std::thread::sleep(remaining);
                timer_signal.fire();
            });
        }

        if !signal.arm(cx.waker()) {
            pipeline.stop(Err(PipelineError::Deadline));
            return Poll::Ready(
                pipeline
                    .take()
                    .expect("stopping the pipeline records a result"),
            );
        }

        Poll::Pending
    })
    .await
}

//! Bounded fan-out aggregation of `Fetcher` results.
//!
//! At most [`MAX_IN_FLIGHT`] fetches run concurrently. The first observed
//! failure is recorded and every other worker stops before starting another
//! fetch. The whole run is bounded by the caller's deadline, and every task
//! this future owns is aborted when the future is dropped, so no `fetch`
//! outlives `solve`.

use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

/// Hard bound on the number of concurrent `fetch` calls.
const MAX_IN_FLIGHT: usize = 4;

/// Sentinel meaning "no failing id recorded yet"; never a real id in the map.
const NO_FAILURE: u32 = u32::MAX;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Shared state every worker consults before starting a new fetch.
struct Shared {
    /// Set the moment any worker observes a failure.
    failed: AtomicBool,
    /// First failing id, or [`NO_FAILURE`]. First writer wins.
    failing_id: AtomicU32,
}

impl Shared {
    fn new() -> Self {
        Self {
            failed: AtomicBool::new(false),
            failing_id: AtomicU32::new(NO_FAILURE),
        }
    }

    fn is_failed(&self) -> bool {
        self.failed.load(Ordering::Acquire)
    }

    fn record_failure(&self, id: u32) {
        self.failed.store(true, Ordering::Release);
        let _ = self.failing_id.compare_exchange(
            NO_FAILURE,
            id,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
    }

    fn failing_id(&self) -> Option<u32> {
        match self.failing_id.load(Ordering::Acquire) {
            NO_FAILURE => None,
            id => Some(id),
        }
    }
}

/// Drains a strided slice of `ids`, returning the sum of the values it saw.
async fn drain(ids: Arc<Vec<u32>>, fetch: Fetcher, shared: Arc<Shared>, worker: usize) -> u64 {
    let workers = MAX_IN_FLIGHT;
    let mut sum: u64 = 0;
    let mut next = worker;
    while next < ids.len() {
        // No new fetch may start once a failure has been observed anywhere.
        if shared.is_failed() {
            return sum;
        }
        let id = ids[next];
        next += workers;

        match fetch.fetch(id).await {
            Ok(value) => sum = sum.wrapping_add(value),
            Err(_) => {
                // Observed failure: publish it, then stop this worker without
                // starting anything else.
                shared.record_failure(id);
                return sum;
            }
        }
    }
    sum
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }

    let workers = ids.len().min(MAX_IN_FLIGHT);
    let ids = Arc::new(ids);
    let shared = Arc::new(Shared::new());

    let work = async {
        // One long-lived worker per admission slot, each draining a strided
        // slice of the ids. A worker never has more than one fetch in flight,
        // so the slot count is the concurrency bound.
        let tasks: Vec<_> = (0..workers)
            .map(|worker| {
                let ids = Arc::clone(&ids);
                let fetch = fetch.clone();
                let shared = Arc::clone(&shared);
                drain(ids, fetch, shared, worker)
            })
            .collect();

        // Dropping this future (deadline expiry, or the caller dropping us)
        // aborts every worker that is still running.
        let sums: Vec<u64> = join_all_bounded(MAX_IN_FLIGHT, tasks).await;

        match shared.failing_id() {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Ok(sums.into_iter().fold(0u64, |acc, s| acc.wrapping_add(s))),
        }
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchOutcome = (u32, Result<u64, ai_task_support::FetchError>);

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<FetchOutcome> = JoinSet::new();
    let mut pending = ids.into_iter();
    let mut total: u64 = 0;

    loop {
        while set.len() < MAX_IN_FLIGHT {
            let Some(id) = pending.next() else { break };
            let fetcher = fetch.clone();
            set.spawn(async move { (id, fetcher.fetch(id).await) });
        }

        let Some(joined) = set.join_next().await else {
            break;
        };
        let Ok((id, result)) = joined else {
            continue;
        };

        match result {
            Ok(value) => total = total.wrapping_add(value),
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
        }
    }

    Ok(total)
}

/// At most this many `fetch` calls may be in flight at the same time.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    run(ids, fetch, deadline).await
}

async fn run(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    // The set is owned by *this* function, not by the future passed to
    // `timeout`, so a deadline expiry leaves us able to stop the work
    // explicitly instead of depending on the inner future being dropped.
    // Every task it holds is a `fetch` we started, so it is our job to end it.
    let mut running: lgwks_bot::rt::task::JoinSet<(u32, Option<u64>)> =
        lgwks_bot::rt::task::JoinSet::new();

    let outcome = match lgwks_bot::rt::time::timeout(
        deadline,
        drive(&mut running, &ids, &fetch),
    )
    .await
    {
        Ok(result) => result,
        // The deadline passed: report it, then fall through to the shutdown
        // below so no fetch outlives the answer.
        Err(_elapsed) => Err(SolveError::Deadline),
    };

    // Unconditional cleanup: nothing we started may still be running once we
    // hand back an answer. On the success path the set is already empty, so
    // this costs nothing; on the failure paths it cancels the other in-flight
    // fetches and waits for them to actually be gone.
    running.abort_all();
    while running.join_next().await.is_some() {}

    outcome
}

async fn drive(
    running: &mut lgwks_bot::rt::task::JoinSet<(u32, Option<u64>)>,
    ids: &[u32],
    fetch: &ai_task_support::Fetcher,
) -> Result<u64, SolveError> {
    let mut next = 0usize;
    // The ids we have started and not yet retired, in start order. This is
    // the record of what the live work is doing, so we can name it if a task
    // ends without reporting.
    let mut in_flight: Vec<u32> = Vec::new();
    let mut sum: u64 = 0;

    loop {
        // Admit work, never past the bound. A task leaves the set only once it
        // has finished, so `len()` is a truthful in-flight count.
        while running.len() < MAX_IN_FLIGHT && next < ids.len() {
            let id = ids[next];
            next += 1;

            let owned = fetch.clone();
            in_flight.push(id);
            running.spawn(async move { (id, owned.fetch(id).await.ok()) });
        }

        let Some(joined) = running.join_next().await else {
            // Every id was admitted and every task reported in.
            return Ok(sum);
        };

        match joined {
            Ok((id, Some(value))) => {
                retire(&mut in_flight, id);
                sum = sum.saturating_add(value);
            }
            Ok((id, None)) => {
                // This fetch failed. We have observed the failure, so stop
                // admitting: returning here ends the loop before the next
                // fill, and `run` cancels whatever is still in flight.
                retire(&mut in_flight, id);
                return Err(SolveError::Fetch { id });
            }
            Err(_join_error) => {
                // A task ended without reporting a result (it panicked). The
                // error carries no id, so charge the oldest unfinished one.
                let id = in_flight.first().copied().unwrap_or(0);
                return Err(SolveError::Fetch { id });
            }
        }
    }
}

fn retire(in_flight: &mut Vec<u32>, id: u32) {
    if let Some(pos) = in_flight.iter().position(|&pending| pending == id) {
        in_flight.remove(pos);
    }
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

use ai_task_support::Fetcher;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchTask = JoinSet<Result<u64, u32>>;

struct InFlight {
    set: FetchTask,
}

impl InFlight {
    fn new() -> Self {
        InFlight {
            set: JoinSet::new(),
        }
    }
}

impl Drop for InFlight {
    fn drop(&mut self) {
        self.set.abort_all();
    }
}

fn spawn_fetch(set: &mut FetchTask, fetch: &Fetcher, id: u32) {
    let owned = fetch.clone();
    let _ = set.spawn(async move {
        match owned.fetch(id).await {
            Ok(value) => Ok(value),
            Err(_err) => Err(id),
        }
    });
}

async fn run_all(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut in_flight = InFlight::new();
    let mut remaining = ids.into_iter();
    let mut sum: u64 = 0;

    while in_flight.set.len() < MAX_IN_FLIGHT {
        match remaining.next() {
            Some(id) => spawn_fetch(&mut in_flight.set, &fetch, id),
            None => break,
        }
    }

    loop {
        match in_flight.set.join_next().await {
            None => return Ok(sum),
            Some(Ok(Ok(value))) => {
                sum = sum.saturating_add(value);
                while in_flight.set.len() < MAX_IN_FLIGHT {
                    match remaining.next() {
                        Some(id) => spawn_fetch(&mut in_flight.set, &fetch, id),
                        None => break,
                    }
                }
            }
            Some(Ok(Err(id))) => {
                in_flight.set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Some(Err(_join_error)) => {
                in_flight.set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, run_all(ids, fetch)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let failed = Arc::new(AtomicBool::new(false));
    let futures = ids.into_iter().map(|id| {
        let fetch = fetch.clone();
        let failed = failed.clone();
        async move {
            if failed.load(Ordering::SeqCst) {
                return Ok(0);
            }
            match fetch.fetch(id).await {
                Ok(v) => Ok(v),
                Err(_) => {
                    failed.store(true, Ordering::SeqCst);
                    Err(id)
                }
            }
        }
    });

    let results = timeout(deadline, join_all_bounded(4, futures))
        .await
        .map_err(|_| SolveError::Deadline)?;

    let mut sum: u64 = 0;
    for r in results {
        match r {
            Ok(v) => sum = sum.wrapping_add(v),
            Err(id) => return Err(SolveError::Fetch { id }),
        }
    }
    Ok(sum)
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match lgwks_bot::rt::time::timeout(deadline, run(ids, fetch)).await {
        Ok(res) => res,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut total: u64 = 0;
    for wave in ids.chunks(4) {
        let results = lgwks_bot::rt::task::join_all_bounded(
            4,
            wave.iter().map(|&id| {
                let f = fetch.clone();
                async move { (id, f.fetch(id).await) }
            }),
        )
        .await;
        for (id, r) in results {
            match r {
                Ok(v) => total += v,
                Err(_) => return Err(SolveError::Fetch { id }),
            }
        }
    }
    Ok(total)
}

//! Bounded, deadline-aware aggregation over `ai_task_support::Fetcher`.
//!
//! At most 4 fetches are in flight at any moment. The first observed fetch
//! failure stops all further work, and the whole aggregation is bounded by a
//! deadline. Every task started here is owned by a `JoinSet` that lives inside
//! the future returned by [`solve`], so dropping that future aborts anything
//! still running.

use std::collections::VecDeque;
use std::time::Duration;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

const MAX_IN_FLIGHT: usize = 4;

type Fetched = (u32, Result<u64, ai_task_support::FetchError>);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    // The set is owned by this future, so dropping `solve` (or the deadline
    // firing, which drops the inner future) aborts every live fetch.
    let run = async {
        let mut queue: VecDeque<u32> = ids.into_iter().collect();
        let mut set: JoinSet<Fetched> = JoinSet::new();
        let mut sum: u64 = 0;
        let mut failure: Option<u32> = None;

        loop {
            // A failure was already observed: start nothing new.
            if failure.is_some() {
                break;
            }

            // Top up to the concurrency bound with work that is still pending.
            while set.len() < MAX_IN_FLIGHT {
                let id = match queue.pop_front() {
                    Some(id) => id,
                    None => break,
                };
                let f = fetch.clone();
                set.spawn(async move { (id, f.fetch(id).await) });
            }

            // Nothing running and nothing left to start.
            if set.is_empty() {
                break;
            }

            match set.join_next().await {
                Some(Ok((_, Ok(value)))) => sum = sum.wrapping_add(value),
                Some(Ok((id, Err(_)))) => failure = Some(id),
                // A task that did not produce a value (aborted/panicked) is
                // simply not summed; the bound and the deadline still apply.
                Some(Err(_)) => {}
                None => break,
            }
        }

        match failure {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Ok(sum),
        }
    };

    match timeout(deadline, run).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::collections::VecDeque;
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Maximum number of `fetch` calls allowed to be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

/// Output of one spawned fetch: the id it ran for and its result.
type Fetched = (u32, Result<u64, ()>);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    // `timeout` owns the aggregate future: when the deadline elapses it drops
    // that future, which drops the `JoinSet` and aborts every running fetch.
    // Dropping the returned `solve` future has the very same effect.
    match timeout(deadline, aggregate(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn aggregate(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<Fetched> = JoinSet::new();
    let mut incoming = ids.into_iter();

    // Ids that have been spawned but not yet joined back. Its length is the
    // exact number of fetches that may still be running, so it is the admission
    // bound: we never start a fetch while it is at the cap.
    let mut outstanding: VecDeque<u32> = VecDeque::new();
    let mut sum: u64 = 0;

    loop {
        // Top the set up to the concurrency bound. A failure always returns from
        // this function, so no fetch can start after one has been observed.
        while outstanding.len() < MAX_IN_FLIGHT {
            let id = match incoming.next() {
                Some(id) => id,
                None => break,
            };
            let worker = fetch.clone();
            outstanding.push_back(id);
            set.spawn(async move { (id, worker.fetch(id).await.map_err(|_| ())) });
        }

        let joined = match set.join_next().await {
            Some(joined) => joined,
            None => {
                // Nothing is running and nothing further can be started.
                return Ok(sum);
            }
        };

        match joined {
            Ok((id, Ok(value))) => {
                if let Some(pos) = outstanding.iter().position(|pending| *pending == id) {
                    outstanding.remove(pos);
                }
                sum = sum.wrapping_add(value);
                if outstanding.is_empty() && incoming.len() == 0 {
                    return Ok(sum);
                }
            }
            // A failing fetch ends the run: no further fetch is started, and the
            // still-running tasks are dropped (and so aborted) on the way out.
            Ok((id, Err(()))) => return Err(SolveError::Fetch { id }),
            // A task died without producing a value; report it against one of
            // the ids that never came back.
            Err(_) => {
                let id = outstanding.pop_front().unwrap_or(0);
                return Err(SolveError::Fetch { id });
            }
        }
    }
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;
use std::time::Duration;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

async fn one(
    fetch: ai_task_support::Fetcher,
    id: u32,
) -> (u32, Result<u64, ()>) {
    let outcome = fetch.fetch(id).await.map_err(|_| ());
    (id, outcome)
}

async fn run_bounded(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<(u32, Result<u64, ()>)> = JoinSet::new();
    let mut iter = ids.into_iter();

    for _ in 0..MAX_IN_FLIGHT {
        match iter.next() {
            Some(id) => {
                set.spawn(one(fetch.clone(), id));
            }
            None => break,
        }
    }

    let mut total: u64 = 0;
    loop {
        let joined = match set.join_next().await {
            Some(joined) => joined,
            None => return Ok(total),
        };

        let (id, outcome) = match joined {
            Ok(value) => value,
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        };

        match outcome {
            Ok(value) => {
                total = total.wrapping_add(value);
            }
            Err(()) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
        }

        match iter.next() {
            Some(id) => {
                set.spawn(one(fetch.clone(), id));
            }
            None => {}
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, run_bounded(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

//! Bounded, fail-fast fan-out over `ai_task_support::Fetcher`.
//!
//! Concurrency is capped at 4 in-flight `fetch` calls. Work is started in
//! waves of at most 4 so that a failure observed in one wave prevents any
//! further fetch from being started. The whole run is wrapped in a deadline;
//! if it elapses, the inner future is dropped, which aborts every task the
//! fan-out owns, so no `fetch` outlives `solve`.

use std::time::Duration;

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

/// Maximum number of `fetch` calls allowed in flight at any moment.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Sum the values fetched for `ids`.
///
/// Returns `Ok(sum)` on success, `Err(SolveError::Fetch { id })` naming a
/// failing id, or `Err(SolveError::Deadline)` if `deadline` elapses first.
/// Dropping the returned future at any point stops the work it owns.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    // `timeout` drops the inner future when the deadline elapses; dropping the
    // wave future aborts the tasks it started.
    match timeout(deadline, run_bounded(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run_bounded(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
) -> Result<u64, SolveError> {
    let mut total: u64 = 0;
    let mut remaining = ids.into_iter();

    loop {
        let wave: Vec<u32> = remaining.by_ref().take(MAX_IN_FLIGHT).collect();
        if wave.is_empty() {
            break;
        }

        let mut pending: Vec<_> = Vec::with_capacity(wave.len());
        for id in wave {
            let owned = fetch.clone();
            pending.push(async move { (id, owned.fetch(id).await) });
        }

        // Never more than MAX_IN_FLIGHT fetches in flight; the whole wave is
        // aborted if this future is dropped (deadline, or caller drop).
        let results = join_all_bounded(MAX_IN_FLIGHT, pending).await;

        // Only observe the wave once it has fully settled, so no fetch can be
        // started after a failure has been seen.
        for (id, outcome) in results {
            match outcome {
                Ok(value) => total = total.wrapping_add(value),
                Err(_) => return Err(SolveError::Fetch { id }),
            }
        }
    }

    Ok(total)
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

type StageResult = Result<Artifact, StageError>;
type StageFuture = Pin<Box<dyn Future<Output = StageResult> + Send + 'static>>;

/// How long a single poll cycle parks before re-checking progress and the
/// deadline. It only bounds the granularity of deadline detection.
const POLL_SLICE: Duration = Duration::from_millis(2);

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct SignalState {
    waker: Option<Waker>,
}

/// A park/wake rendezvous: any thread that makes stage progress clones the
/// stored waker and wakes the task, so `solve` never busy-spins.
struct Signal {
    state: Mutex<SignalState>,
    wakeup: Condvar,
}

impl Signal {
    fn new() -> Signal {
        Signal {
            state: Mutex::new(SignalState { waker: None }),
            wakeup: Condvar::new(),
        }
    }

    fn lock(&self) -> MutexGuard<'_, SignalState> {
        self.state.lock().unwrap_or_else(|err| err.into_inner())
    }

    fn arm(&self, waker: &Waker) {
        let mut guard = self.lock();
        guard.waker = Some(waker.clone());
    }

    fn notify(&self) {
        let waker = {
            let guard = self.lock();
            guard.waker.clone()
        };
        if let Some(waker) = waker {
            waker.wake_by_ref();
        }
        self.wakeup.notify_all();
    }

    fn nap(&self, slice: Duration) {
        let guard = self.lock();
        let _ = self
            .wakeup
            .wait_timeout(guard, slice)
            .unwrap_or_else(|err| err.into_inner());
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.notify();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.notify();
    }
}

/// One park cycle of the driver. The first poll arms the waker, parks briefly,
/// and re-arms the caller's task so the future is polled again; the second poll
/// completes, which is what yields back to the caller between cycles.
struct Nap<'a> {
    signal: &'a Signal,
    slice: Duration,
    armed: bool,
}

impl Future for Nap<'_> {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if this.armed {
            return Poll::Ready(());
        }
        this.armed = true;
        this.signal.arm(cx.waker());
        this.signal.nap(this.slice);
        this.signal.notify();
        Poll::Pending
    }
}

struct Job {
    name: StageName,
    future: StageFuture,
    out: Option<StageResult>,
}

fn job(stage: &'static Stage, name: StageName) -> Job {
    Job {
        future: Box::pin(stage.run(name.clone())),
        name,
        out: None,
    }
}

/// Poll every job to completion under one shared deadline.
///
/// * the first stage failure is reported as `PipelineError::Stage` and the
///   still-pending siblings are dropped, so nothing runs afterwards;
/// * the deadline covers the whole pipeline;
/// * every future stays owned by this function, so dropping the caller drops
///   the driver and with it any stage that is still in flight.
async fn drain(
    jobs: &mut [Job],
    signal: &Arc<Signal>,
    expires: Instant,
) -> Result<Vec<StageResult>, PipelineError> {
    let waker = Waker::from(Arc::clone(signal));
    let mut cx = Context::from_waker(&waker);

    loop {
        for job in jobs.iter_mut() {
            if job.out.is_none() {
                if let Poll::Ready(value) = job.future.as_mut().poll(&mut cx) {
                    job.out = Some(value);
                }
            }
            if matches!(job.out, Some(Err(_))) {
                return Err(PipelineError::Stage {
                    name: job.name.clone(),
                });
            }
        }

        if jobs.iter().all(|job| job.out.is_some()) {
            let mut outputs = Vec::with_capacity(jobs.len());
            for job in jobs.iter_mut() {
                if let Some(value) = job.out.take() {
                    outputs.push(value);
                }
            }
            return Ok(outputs);
        }

        if Instant::now() >= expires {
            return Err(PipelineError::Deadline);
        }

        Nap {
            signal: signal.as_ref(),
            slice: POLL_SLICE,
            armed: false,
        }
        .await;
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let expires = Instant::now() + deadline;

    // `owner` is declared before every stage future, so the generated drop glue
    // drops the futures first and releases the shared `Stage` only afterwards.
    // That ordering is what keeps the `&'static` borrow below sound, and it is
    // also what releases the stage when the caller drops this future.
    let owner: Arc<Stage> = Arc::new(stage);
    let shared: &'static Stage = unsafe { &*Arc::as_ptr(&owner) };

    let signal = Arc::new(Signal::new());

    // `fetch_a` and `fetch_b` are independent, so both are in flight together
    // and are polled on every cycle; neither starts the other.
    let mut fetches = [job(shared, StageName::FetchA), job(shared, StageName::FetchB)];
    drain(&mut fetches, &signal, expires).await?;

    // `combine` only starts once both fetches succeeded; on failure `drain`
    // already returned and the future above has been dropped.
    let mut combines = [job(shared, StageName::Combine)];
    drain(&mut combines, &signal, expires).await?;

    let mut publishes = [job(shared, StageName::Publish)];
    let published = drain(&mut publishes, &signal, expires).await?;

    match published.into_iter().next() {
        Some(Ok(artifact)) => Ok(Published::from(artifact)),
        _ => Err(PipelineError::Cancelled),
    }
}

//! Pipeline orchestration: fetch_a/fetch_b concurrently, then combine, then
//! publish, all under one overall deadline, with all work owned by (and
//! cancelled with) the future returned by `solve`.

use std::future::Future;
use std::pin::Pin;

use ai_task_support::{Artifact, Published, Stage, StageName, StageError};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: Stage,
    deadline: std::time::Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, execute(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

type StageFuture = Pin<Box<dyn Future<Output = Result<Artifact, StageError>> + Send + 'static>>;

async fn execute(stage: Stage) -> Result<Published, PipelineError> {
    // The two fetches are independent: run them concurrently, bounded to the
    // two of them. Each future owns its own clone of the stage, so nothing is
    // borrowed across the await, and dropping the fan-out future aborts both.
    let stage_a = stage.clone();
    let stage_b = stage.clone();

    let fetch_a: StageFuture = Box::pin(async move { stage_a.run(StageName::FetchA).await });
    let fetch_b: StageFuture = Box::pin(async move { stage_b.run(StageName::FetchB).await });

    // Results come back in input order: [FetchA, FetchB].
    let results = join_all_bounded(2, vec![fetch_a, fetch_b]).await;
    if results.len() != 2 {
        return Err(PipelineError::Cancelled);
    }
    let fetched_a = results[0];
    let fetched_b = results[1];

    // A failed fetch stops the pipeline: neither combine nor publish starts.
    let a = fetched_a.map_err(|_| PipelineError::Stage { name: StageName::FetchA })?;
    let b = fetched_b.map_err(|_| PipelineError::Stage { name: StageName::FetchB })?;
    drop((a, b));

    // combine needs both fetches to have succeeded; publish needs combine.
    let combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;
    drop(combined);

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(artifact))
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageOutcome = Result<Artifact, ()>;
type StageFuture = Pin<Box<dyn Future<Output = StageOutcome>>>;

/// Deadline enforcement without depending on an executor timer: a dedicated
/// watcher thread owns the clock and wakes the pipeline exactly once.
struct TimerState {
    expired: bool,
    disarmed: bool,
    waker: Option<Waker>,
}

struct TimerInner {
    state: Mutex<TimerState>,
    signal: Condvar,
}

struct Timer {
    inner: Arc<TimerInner>,
    watcher: Mutex<Option<std::thread::JoinHandle<()>>>,
}

impl Timer {
    fn new(duration: Duration) -> Timer {
        let inner = Arc::new(TimerInner {
            state: Mutex::new(TimerState {
                expired: duration.is_zero(),
                disarmed: false,
                waker: None,
            }),
            signal: Condvar::new(),
        });

        let watcher = if duration.is_zero() {
            None
        } else {
            let thread_inner = Arc::clone(&inner);
            std::thread::Builder::new()
                .name("pipeline-deadline".to_string())
                .spawn(move || {
                    let start = Instant::now();
                    let mut state = lock(&thread_inner.state);
                    loop {
                        if state.disarmed {
                            return;
                        }
                        let elapsed = start.elapsed();
                        if elapsed >= duration {
                            state.expired = true;
                            if let Some(waker) = state.waker.take() {
                                waker.wake();
                            }
                            return;
                        }
                        let (next, _waited) = thread_inner
                            .signal
                            .wait_timeout(state, duration - elapsed)
                            .unwrap_or_else(|poisoned| poisoned.into_inner());
                        state = next;
                    }
                })
                .ok()
        };

        Timer {
            inner,
            watcher: Mutex::new(watcher),
        }
    }

    fn expired(&self) -> bool {
        lock(&self.inner.state).expired
    }

    fn arm(&self, waker: &Waker) {
        let mut state = lock(&self.inner.state);
        let stale = match state.waker.as_ref() {
            Some(existing) => !existing.will_wake(waker),
            None => true,
        };
        if stale {
            state.waker = Some(waker.clone());
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        {
            let mut state = lock(&self.inner.state);
            state.disarmed = true;
            state.waker = None;
            self.inner.signal.notify_all();
        }
        if let Some(handle) = lock(&self.watcher).take() {
            let _ = handle.join();
        }
    }
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

enum Step {
    Fetches {
        a: StageFuture,
        b: StageFuture,
        a_out: Option<StageOutcome>,
        b_out: Option<StageOutcome>,
    },
    Combine(StageFuture),
    Publish(StageFuture),
    Idle,
}

struct Pipeline {
    stage: Arc<Stage>,
    timer: Timer,
    step: Step,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let stage = Arc::new(stage);
    let a = run_stage(Arc::clone(&stage), StageName::FetchA);
    let b = run_stage(Arc::clone(&stage), StageName::FetchB);

    Pipeline {
        stage,
        timer: Timer::new(deadline),
        step: Step::Fetches {
            a,
            b,
            a_out: None,
            b_out: None,
        },
    }
    .await
}

fn run_stage(stage: Arc<Stage>, name: StageName) -> StageFuture {
    Box::pin(async move { stage.run(name).await.map_err(|_| ()) })
}

impl Future for Pipeline {
    type Output = Result<Published, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        this.timer.arm(cx.waker());
        if this.timer.expired() {
            this.step = Step::Idle;
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        loop {
            let step = std::mem::replace(&mut this.step, Step::Idle);

            match step {
                Step::Fetches {
                    mut a,
                    mut b,
                    mut a_out,
                    mut b_out,
                } => {
                    if a_out.is_none() {
                        if let Poll::Ready(value) = a.as_mut().poll(cx) {
                            a_out = Some(value);
                        }
                    }
                    if b_out.is_none() {
                        if let Poll::Ready(value) = b.as_mut().poll(cx) {
                            b_out = Some(value);
                        }
                    }

                    if matches!(&a_out, Some(Err(_))) {
                        drop(a);
                        drop(b);
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::FetchA,
                        }));
                    }
                    if matches!(&b_out, Some(Err(_))) {
                        drop(a);
                        drop(b);
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::FetchB,
                        }));
                    }

                    if a_out.is_some() && b_out.is_some() {
                        let stage = Arc::clone(&this.stage);
                        this.step = Step::Combine(run_stage(stage, StageName::Combine));
                    } else {
                        this.step = Step::Fetches {
                            a,
                            b,
                            a_out,
                            b_out,
                        };
                        return Poll::Pending;
                    }
                }

                Step::Combine(mut future) => match future.as_mut().poll(cx) {
                    Poll::Ready(Ok(_)) => {
                        drop(future);
                        let stage = Arc::clone(&this.stage);
                        this.step = Step::Publish(run_stage(stage, StageName::Publish));
                    }
                    Poll::Ready(Err(_)) => {
                        drop(future);
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::Combine,
                        }));
                    }
                    Poll::Pending => {
                        this.step = Step::Combine(future);
                        return Poll::Pending;
                    }
                },

                Step::Publish(mut future) => match future.as_mut().poll(cx) {
                    Poll::Ready(Ok(artifact)) => {
                        drop(future);
                        return Poll::Ready(Ok(Published::from(artifact)));
                    }
                    Poll::Ready(Err(_)) => {
                        drop(future);
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::Publish,
                        }));
                    }
                    Poll::Pending => {
                        this.step = Step::Publish(future);
                        return Poll::Pending;
                    }
                },

                Step::Idle => return Poll::Ready(Err(PipelineError::Cancelled)),
            }
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageRun = Pin<Box<dyn Future<Output = Result<Artifact, StageError>> + Send + 'static>>;

enum Fetched {
    Both,
    Failed(StageName),
}

/// Polls `FetchA` and `FetchB` concurrently. Dropping this future drops both
/// in-flight stage futures, so no stage keeps running once the owner is gone.
struct Fetches {
    a: Option<StageRun>,
    b: Option<StageRun>,
    a_value: Option<Artifact>,
    b_value: Option<Artifact>,
    finished: bool,
}

impl Fetches {
    fn start(stage: &Stage) -> Self {
        let a_stage = stage.clone();
        let b_stage = stage.clone();
        Fetches {
            a: Some(Box::pin(async move { a_stage.run(StageName::FetchA).await })),
            b: Some(Box::pin(async move { b_stage.run(StageName::FetchB).await })),
            a_value: None,
            b_value: None,
            finished: false,
        }
    }
}

impl Future for Fetches {
    type Output = Fetched;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        if me.finished {
            return Poll::Pending;
        }

        if let Some(run) = me.a.as_mut() {
            match run.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => {
                    me.a = None;
                    me.a_value = Some(artifact);
                }
                Poll::Ready(Err(_)) => {
                    me.a = None;
                    me.b = None;
                    me.finished = true;
                    return Poll::Ready(Fetched::Failed(StageName::FetchA));
                }
                Poll::Pending => {}
            }
        }

        if let Some(run) = me.b.as_mut() {
            match run.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => {
                    me.b = None;
                    me.b_value = Some(artifact);
                }
                Poll::Ready(Err(_)) => {
                    me.b = None;
                    me.a = None;
                    me.finished = true;
                    return Poll::Ready(Fetched::Failed(StageName::FetchB));
                }
                Poll::Pending => {}
            }
        }

        if me.a_value.is_some() && me.b_value.is_some() {
            me.a_value = None;
            me.b_value = None;
            me.finished = true;
            return Poll::Ready(Fetched::Both);
        }

        Poll::Pending
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    match Fetches::start(&stage).await {
        Fetched::Both => {}
        Fetched::Failed(name) => return Err(PipelineError::Stage { name }),
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    let artifact = match stage.run(StageName::Publish).await {
        Ok(artifact) => artifact,
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Publish,
            })
        }
    };

    Ok(Published::from(artifact))
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

//! Bounded four-stage pipeline: fetch (concurrent) -> combine -> publish.

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;
use std::time::Duration;

/// Why the pipeline could not produce a published artifact.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage failed (or its task died).
    Stage { name: StageName },
    /// The overall deadline elapsed.
    Deadline,
    /// Work was cancelled before completion.
    Cancelled,
}

/// Run the pipeline under a single overall deadline.
///
/// Fetch A and Fetch B run concurrently; a failure in either aborts the other
/// and prevents Combine and Publish. Dropping the returned future aborts every
/// stage still in flight.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async move {
        let sa = stage.clone();
        let sb = stage.clone();

        let mut set: JoinSet<(StageName, Result<Artifact, ai_task_support::StageError>)> =
            JoinSet::new();
        set.spawn(async move { (StageName::FetchA, sa.run(StageName::FetchA).await) });
        set.spawn(async move { (StageName::FetchB, sb.run(StageName::FetchB).await) });

        let mut a: Option<Artifact> = None;
        let mut b: Option<Artifact> = None;
        while let Some(joined) = set.join_next().await {
            let (name, result) = joined.map_err(|_| PipelineError::Cancelled)?;
            let artifact = result.map_err(|_| PipelineError::Stage { name })?;
            match name {
                StageName::FetchA => a = Some(artifact),
                _ => b = Some(artifact),
            }
        }
        // First failure aborts the sibling fetch and stops the pipeline.
        let (_a, _b) = (a.ok_or(PipelineError::Stage { name: StageName::FetchA })?,
                       b.ok_or(PipelineError::Stage { name: StageName::FetchB })?);

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;
        stage
            .run(StageName::Publish)
            .await
            .map(Published::from)
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })
    };

    match timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn fetch(stage: Stage, name: StageName) -> (StageName, Result<Artifact, PipelineError>) {
    let result = stage.run(name).await.map_err(|_| PipelineError::Stage { name });
    (name, result)
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let mut set = JoinSet::new();
    set.spawn(fetch(stage.clone(), StageName::FetchA));
    set.spawn(fetch(stage.clone(), StageName::FetchB));

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    while let Some(joined) = set.join_next().await {
        let (name, result) = match joined {
            Ok(pair) => pair,
            Err(_) => continue,
        };
        match (name, result) {
            (StageName::FetchA, Ok(artifact)) => a = Some(artifact),
            (StageName::FetchB, Ok(artifact)) => b = Some(artifact),
            (name, Err(err)) => return Err(err),
            _ => {}
        }
    }
    if a.is_none() || b.is_none() {
        return Err(PipelineError::Stage { name: StageName::Combine });
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageResult = Result<Artifact, StageError>;

fn stage_error(name: StageName) -> impl Fn(StageError) -> PipelineError {
    move |_err| PipelineError::Stage { name }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // fetch_a and fetch_b are independent: run them concurrently. The
    // fan-out owns its tasks, so dropping it aborts whatever is still in
    // flight.
    let stage_a = stage.clone();
    let stage_b = stage.clone();
    let fetch_a: Pin<Box<dyn Future<Output = StageResult> + Send + 'static>> =
        Box::pin(async move { stage_a.run(StageName::FetchA).await });
    let fetch_b: Pin<Box<dyn Future<Output = StageResult> + Send + 'static>> =
        Box::pin(async move { stage_b.run(StageName::FetchB).await });

    // Results come back in input order, and both futures always run to
    // completion, so index 0 is fetch_a and index 1 is fetch_b.
    let results = lgwks_bot::rt::task::join_all_bounded(2, vec![fetch_a, fetch_b]).await;
    let mut results = results.into_iter();
    let a = results
        .next()
        .ok_or(PipelineError::Stage { name: StageName::FetchA })?;
    let b = results
        .next()
        .ok_or(PipelineError::Stage { name: StageName::FetchB })?;

    // Both fetches must have succeeded before anything downstream runs.
    a.map_err(stage_error(StageName::FetchA))?;
    b.map_err(stage_error(StageName::FetchB))?;

    stage
        .run(StageName::Combine)
        .await
        .map_err(stage_error(StageName::Combine))?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(stage_error(StageName::Publish))?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    // The timeout owns the pipeline future, so on expiry it is dropped: the
    // fan-out is aborted and no later stage is started. If the caller drops
    // this future, the same teardown happens.
    match lgwks_bot::rt::time::timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(
    stage: Stage,
    name: StageName,
) -> (StageName, Result<Artifact, StageError>) {
    let outcome = stage.run(name.clone()).await;
    (name, outcome)
}

async fn pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    let results = join_all_bounded(
        2,
        [
            run_stage(stage.clone(), StageName::FetchA),
            run_stage(stage.clone(), StageName::FetchB),
        ],
    )
    .await;

    for (name, outcome) in results {
        if outcome.is_err() {
            return Err(PipelineError::Stage { name });
        }
    }

    let _ = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(&stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;
use std::time::Duration;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Which step of the pipeline we are on. This is our own copy of the stage
/// names, so naming a stage in an error never depends on cloning or copying
/// `StageName`.
#[derive(Clone, Copy)]
enum Phase {
    FetchA,
    FetchB,
    Combine,
    Publish,
}

impl Phase {
    fn name(self) -> StageName {
        match self {
            Phase::FetchA => StageName::FetchA,
            Phase::FetchB => StageName::FetchB,
            Phase::Combine => StageName::Combine,
            Phase::Publish => StageName::Publish,
        }
    }
}

/// Runs the whole pipeline under one overall deadline.
///
/// The deadline wraps the entire body rather than each stage, so a run of fast
/// stages still cannot overrun it, and a stage that is still in flight when the
/// budget runs out stops there: no later stage starts.
pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

/// The pipeline itself, with no deadline of its own.
///
/// Everything started here is owned by the future that drives it: the two
/// fetches live in a `JoinSet`, whose drop aborts whatever is still running,
/// and `combine`/`publish` are awaited inline. So dropping this future — on a
/// deadline, or because the caller dropped `solve` — leaves no stage running.
async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // A failing fetch returns here. The set is dropped on the way out, which
    // aborts the sibling, so `combine` and `publish` never start.
    let (_a, _b) = fetch_both(&stage).await?;

    run_phase(&stage, Phase::Combine).await?;
    let published = run_phase(&stage, Phase::Publish).await?;

    Ok(Published::from(published))
}

async fn run_phase(stage: &Stage, phase: Phase) -> Result<Artifact, PipelineError> {
    stage
        .run(phase.name())
        .await
        .map_err(|_| PipelineError::Stage { name: phase.name() })
}

type FetchResult = (Phase, Result<Artifact, ai_task_support::StageError>);

/// Runs `fetch_a` and `fetch_b` concurrently and returns both artifacts.
async fn fetch_both(stage: &Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut set: JoinSet<FetchResult> = JoinSet::new();
    // The handles are held for the whole collection loop: the set owns the
    // tasks, and the handles are kept alive rather than dropped early.
    let mut _handles = Vec::with_capacity(2);

    for which in vec![Phase::FetchA, Phase::FetchB] {
        // Each task owns its own clone: spawned futures must be 'static, and
        // the set is the only thing keeping this work alive.
        let owned = stage.clone();
        _handles.push(set.spawn(async move { (which, owned.run(which.name()).await) }));
    }

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while let Some(joined) = set.join_next().await {
        // A task that produced no value was aborted or panicked.
        let (which, result) = joined.map_err(|_| PipelineError::Cancelled)?;
        let artifact = result.map_err(|_| PipelineError::Stage { name: which.name() })?;

        match which {
            Phase::FetchA => a = Some(artifact),
            Phase::FetchB => b = Some(artifact),
            _ => {}
        }
    }

    match (a, b) {
        (Some(a), Some(b)) => Ok((a, b)),
        // The set drained without both fetches reporting in: report the
        // cancellation it is, rather than naming a stage that never failed.
        _ => Err(PipelineError::Cancelled),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Run one stage, tagging any failure with that stage's own name.
///
/// Takes the `Stage` by value so the resulting future is `Send + 'static` and
/// can be owned by the fan-out, which is what makes cancellation-on-drop work.
async fn run_named(stage: Stage, name: StageName) -> Result<Artifact, PipelineError> {
    stage.run(name).await.map_err(|_| PipelineError::Stage { name })
}

/// `fetch_a` and `fetch_b` concurrently, then `combine`, then `publish`.
///
/// Nothing is detached from the future the caller holds: the fan-out owns the
/// two fetch tasks and aborts them when dropped, and `combine`/`publish` are
/// awaited in place, so dropping this future stops every stage.
async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // `join_all_bounded` returns outputs in input order and does not fail fast,
    // so both fetches run to completion and are inspected afterwards.
    let mut fetched = join_all_bounded(
        2usize,
        vec![
            run_named(stage.clone(), StageName::FetchA),
            run_named(stage.clone(), StageName::FetchB),
        ],
    )
    .await
    .into_iter();

    // `combine` requires both fetches: if either failed, name it and stop.
    let _a: Artifact = fetched
        .next()
        .ok_or(PipelineError::Stage {
            name: StageName::FetchA,
        })??;
    let _b: Artifact = fetched
        .next()
        .ok_or(PipelineError::Stage {
            name: StageName::FetchB,
        })??;

    let _combined: Artifact = run_named(stage.clone(), StageName::Combine).await?;
    let published: Artifact = run_named(stage, StageName::Publish).await?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    // The timeout wraps the whole pipeline: when it fires no later stage runs,
    // and dropping `solve` drops the inner future, aborting the fan-out.
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}
